pure function c_string(s) result(c)
    !! `s` as a NUL-terminated C string.
    character(len=*), intent(in) :: s   !! the Fortran string
    character(kind=c_char) :: c(len(s) + 1)
    integer :: k
    do k = 1, len(s)
