module fdoc_model
!! The documented program: source files and the entities in them.
!!
!! Entities live in one list and refer to each other by index. Each is held through an allocatable, so
!! that growing the list or merging one list into another moves entities and does not copy them.
use fdoc_util, only: string_t, push, push_int, name_index_t
implicit none
private

public :: is_procedure

! entity kinds
integer, parameter, public :: E_NONE = 0
integer, parameter, public :: E_FILE = 1          !! a source file
integer, parameter, public :: E_MODULE = 2
integer, parameter, public :: E_SUBMODULE = 3
integer, parameter, public :: E_PROGRAM = 4
integer, parameter, public :: E_BLOCKDATA = 5
integer, parameter, public :: E_SUBROUTINE = 6
integer, parameter, public :: E_FUNCTION = 7
integer, parameter, public :: E_MODPROC = 8       !! implementation of a separate module procedure
integer, parameter, public :: E_INTERFACE = 9     !! a generic interface; other blocks dissolve into their bodies
integer, parameter, public :: E_TYPE = 10
integer, parameter, public :: E_ENUM = 11
integer, parameter, public :: E_BOUNDPROC = 12
integer, parameter, public :: E_FINAL = 13
integer, parameter, public :: E_VARIABLE = 14
integer, parameter, public :: E_NAMELIST = 15
integer, parameter, public :: E_COMMON = 16

! how a procedure relates to an interface block
integer, parameter, public :: IFACE_NONE = 0      !! an ordinary procedure, or the body of a generic interface
integer, parameter, public :: IFACE_EXPLICIT = 1  !! the body of an unnamed interface block
integer, parameter, public :: IFACE_ABSTRACT = 2  !! the body of an abstract interface block

! how a variable relates to its procedure or type
integer, parameter, public :: VAR_PLAIN = 0       !! listed among the variables of its parent
integer, parameter, public :: VAR_ARGUMENT = 1    !! a dummy argument
integer, parameter, public :: VAR_RESULT = 2      !! the result of a function
integer, parameter, public :: VAR_HIDDEN = 3      !! not shown, such as `external` names
integer, parameter, public :: VAR_COMMON = 4      !! a member of a common block, shown with the block

type, public :: attribute_t
    !! An attribute given in a statement of its own, such as `public :: x`, waiting to be applied.
    character(len=:), allocatable :: name       !! the entity, in lowercase
    character(len=:), allocatable :: value      !! the attribute
end type attribute_t

type, public :: rename_t
    !! A name in the `only` list of a `use` statement.
    character(len=:), allocatable :: used   !! the name in the used module, in lowercase
    character(len=:), allocatable :: local  !! the name in the using scope, in lowercase
end type rename_t

type, public :: use_t
    !! A `use` statement.
    character(len=:), allocatable :: module     !! the module, in lowercase
    character(len=:), allocatable :: spec       !! what follows the module name
    integer :: target = 0                       !! the module's entity, if it is known
    logical :: only = .false.                   !! has an `only` list
    type(rename_t), allocatable :: renames(:)   !! the `only` list
end type use_t

type, public :: meta_t
    !! A metadata entry of a doc comment, such as `author: me`.
    character(len=:), allocatable :: key        !! the key, in lowercase
    type(string_t), allocatable :: values(:)    !! the values
end type meta_t

type, public :: entity_more_t
    !! What only some entities have. Most entities are variables, which share one of these, so an
    !! entity takes half the memory; this makes up most of the memory used on large projects.
    type(use_t), allocatable :: uses(:)         !! its `use` statements
    type(attribute_t), allocatable :: pending(:)    !! attributes waiting to be applied
    type(attribute_t), allocatable :: parameters(:) !! values from `parameter` statements
    type(string_t), allocatable :: public_list(:)   !! names known to be public, in lowercase
    character(len=:), allocatable :: ancestor       !! the ancestor module, in lowercase
    character(len=:), allocatable :: parent_submodule  !! the parent submodule, in lowercase
    integer, allocatable :: descendants(:)      !! the submodules directly below this entity
    type(string_t), allocatable :: args(:)      !! dummy argument names as written
    integer, allocatable :: arg_ids(:)          !! the entity of each argument
    character(len=:), allocatable :: result_name    !! the result's name as written
    character(len=:), allocatable :: bind_c     !! the text of `bind(...)`, if any
    type(string_t), allocatable :: calls(:)     !! `%`-separated names of what it calls, in lowercase
    type(string_t), allocatable :: unknown_calls(:) !! the names of calls that were not found
    type(string_t), allocatable :: modprocs(:)  !! procedures listed by `module procedure`
    integer, allocatable :: modproc_ids(:)      !! those procedures, once found
    character(len=:), allocatable :: extends    !! the parent type's name as written, if any
    type(string_t), allocatable :: parameters_list(:)   !! type parameter names
    integer, allocatable :: inherited(:)        !! the components and bindings it inherits
    type(string_t), allocatable :: bindings(:)  !! what it is bound to
    character(len=:), allocatable :: proto_text !! the interface in `procedure(...)`, if any
    integer, allocatable :: binding_ids(:)      !! what each of `bindings` is, once found
    logical :: saved_state = .false.            !! a procedure that keeps values between calls
    logical :: common_block = .false.          !! a procedure with a common block
end type entity_more_t

type, public :: entity_t
    !! A file, program unit, procedure, type, variable or the like. Which components apply depends on
    !! `kind`.
    type(entity_more_t), pointer :: more => null()  !! what only some entities have
    integer :: kind = E_NONE                    !! one of the `E_*` constants
    integer :: parent = 0                       !! the entity containing this one
    integer :: file = 0                         !! the file containing this entity
    integer :: line = 0                         !! line of its first statement in the text parsed
    character(len=:), allocatable :: name       !! its name as written
    character(len=:), allocatable :: permission !! `public`, `private` or `protected`
    type(string_t), allocatable :: doc(:)       !! its documentation, without metadata
    type(meta_t), allocatable :: meta(:)        !! the metadata of its documentation
    character(len=:), allocatable :: html       !! its documentation as HTML
    character(len=:), allocatable :: summary    !! its summary as HTML
    type(string_t), allocatable :: attribs(:)   !! its attributes
    integer, allocatable :: children(:)         !! the entities directly inside this one, in order
    logical :: visible = .true.                 !! false once pruned
    type(string_t), allocatable :: display(:)   !! the permissions shown inside this entity
    logical :: internals = .false.              !! the `proc_internals` setting that applies here
    character(len=:), allocatable :: external_url  !! where it is documented, if in another project
    character(len=:), allocatable :: page       !! the name of its page, unique in its directory, if it has one
    character(len=:), allocatable :: source_text !! the text of a file, as it is
    integer :: source_first = 0                 !! where its code starts in the text of its file, if found
    integer :: source_last = 0                  !! where its code ends

    ! containers
    logical :: in_contains = .false.            !! true after its `contains` statement
    character(len=:), allocatable :: child_permission  !! permission of what is declared from here on

    ! submodules
    integer :: ancestor_id = 0                  !! the ancestor module, once found
    integer :: parent_submodule_id = 0          !! the parent submodule, once found

    ! procedures
    integer :: result = 0                       !! the result variable of a function
    logical :: is_module = .false.              !! has the `module` prefix
    integer :: iface = IFACE_NONE               !! one of the `IFACE_*` constants
    integer, allocatable :: call_ids(:)         !! the procedures called, once found
    integer :: implements = 0                   !! the interface of a separate module procedure, once found
    integer :: bound_to = 0                     !! a type that this procedure is bound to, once found

    ! interfaces
    logical :: abstract = .false.               !! an `abstract interface` block
    logical :: generic = .false.                !! a generic interface or binding

    ! types
    logical :: sequence = .false.               !! has a `sequence` statement
    integer :: extends_id = 0                   !! the parent type, once found
    integer :: constructor = 0                  !! the procedure or interface named like it, once found
    integer :: inherit_state = 0                !! 0 not done, 1 in progress, 2 done

    ! bound procedures
    logical :: deferred = .false.               !! has the `deferred` attribute
    integer :: proto_id = 0                     !! the interface or type it refers to, once found

    ! variables
    integer :: var_role = VAR_PLAIN             !! one of the `VAR_*` constants
    character(len=:), allocatable :: vartype    !! its type keyword, in lowercase
    character(len=:), allocatable :: type_kind  !! its kind, if any
    character(len=:), allocatable :: strlen     !! its character length, if any
    type(string_t), allocatable :: proto(:)     !! the type or interface name, and its arguments
    character(len=:), allocatable :: intent     !! `in`, `out`, `inout` or empty
    logical :: optional = .false.               !! has the `optional` attribute
    logical :: parameter = .false.              !! has the `parameter` attribute
    logical :: points = .false.                 !! initialized with `=>`
    character(len=:), allocatable :: initial    !! its initial value, if any
    character(len=:), allocatable :: dimension  !! its dimensions, if declared after the name
end type entity_t

type, public :: entity_box_t
    !! Holds an entity, so that it can be moved without being copied.
    type(entity_t), allocatable :: e    !! the entity
end type entity_box_t

type, public :: entity_list_t
    !! A list of entities. Indices start at 1, and 0 means no entity.
    type(entity_box_t), allocatable :: box(:)   !! storage; only `box(1:n)` is in use
    integer :: n = 0                            !! number of entities
    type(name_index_t) :: names                 !! the first entity of each lowercase name, once built
    integer, allocatable :: next_named(:)       !! the next entity with the same name, or 0
contains
    procedure :: add => list_add                !! add an entity
end type entity_list_t


!> What all variables share. This is never written to.
type(entity_more_t), target, save, public :: no_more

contains

!> True if `kind` is a subroutine or function.
elemental logical function is_procedure(kind)
    integer, intent(in) :: kind     !! one of the `E_*` constants

    is_procedure = kind == E_SUBROUTINE .or. kind == E_FUNCTION
end function is_procedure

!> Add an entity of kind `kind` inside `parent`, returning its index.
integer function list_add(self, kind, parent) result(id)
    class(entity_list_t), intent(inout) :: self     !! the list
    integer, intent(in) :: kind                     !! one of the `E_*` constants
    integer, intent(in) :: parent                   !! the containing entity, or 0
    type(entity_box_t), allocatable :: grown(:)
    integer :: k

    if (.not. allocated(self%box)) allocate (self%box(64))
    if (self%n == size(self%box)) then
        allocate (grown(2*self%n))
        do k = 1, self%n
            call move_alloc(self%box(k)%e, grown(k)%e)
        end do
        call move_alloc(grown, self%box)
    end if
    self%n = self%n + 1
    id = self%n
    allocate (self%box(id)%e)
    self%box(id)%e%kind = kind
    if (kind == E_VARIABLE) then
        self%box(id)%e%more => no_more
    else
        allocate (self%box(id)%e%more)
    end if
    self%box(id)%e%parent = parent
    allocate (self%box(id)%e%children(0))
    if (parent > 0) then
        self%box(id)%e%file = self%box(parent)%e%file
        call push_int(self%box(parent)%e%children, id)
    end if
end function list_add

end module fdoc_model
 
 
!>>>>> build/dependencies/fdot/src/fdot.f90
module fdot
!! The graph layout of Graphviz `dot`, in modern Fortran: a port of the part that draws directed graphs
!! of named boxes, for fdoc. Give it nodes and edges, and get an SVG drawing back as a string. There is
!! no DOT language, no plugins, no files and no external process.
!!
!! Graphviz is under the Eclipse Public License 2.0, and so is this port. It is safe to use different
!! graphs in different threads at once.
use iso_fortran_env, only: int64
use fdot_structure
use fdot_text, only: text_width, text_height
use fdot_rank, only: dot_rank
use fdot_order, only: dot_mincross
use fdot_position, only: dot_position
use fdot_route, only: dot_splines
use fdot_draw, only: node_size, arrow_polygon, translate_drawing
use fdot_svg
implicit none
private

public :: graph_t, node_style_t, edge_style_t, point_t, wp

integer, parameter, public :: RANK_LR = 1   !! ranks go from left to right
integer, parameter, public :: RANK_RL = 2   !! ranks go from right to left

integer, parameter, public :: FDOT_OK = 0               !! success
integer, parameter, public :: FDOT_INVALID = 1          !! a node of an edge does not exist
integer, parameter, public :: FDOT_NO_RANKS = 2         !! network simplex failed
integer, parameter, public :: FDOT_FLAT_EDGE = 3        !! an edge joins nodes of one rank
integer, parameter, public :: FDOT_NO_ROUTE = 4         !! no route was found for an edge

real(wp), parameter :: PAD = 4.0_wp                     !! points around a drawing
real(wp), parameter :: BASELINE = 0.36_wp               !! where the middle of text is above its baseline, in font sizes

type :: node_style_t
    !! How nodes look, by default as fdoc draws them.
    real(wp) :: font_size = 13.0_wp     !! the size of names, in points
    real(wp) :: height = 21.6_wp        !! the smallest height, in points
    real(wp) :: margin_x = 7.2_wp       !! the margin beside names, in points
    real(wp) :: margin_y = 2.88_wp      !! the margin above and below names, in points
    real(wp) :: pen_width = 2.0_wp      !! the width of an outline, in points
end type node_style_t

type :: edge_style_t
    !! How edges look, by default as fdoc draws them.
    real(wp) :: font_size = 11.0_wp                 !! the size of labels, in points
    real(wp) :: arrow_size = 0.7_wp                 !! the size of arrowheads
    character(len=:), allocatable :: colour         !! the colour of edges that give none
    character(len=:), allocatable :: label_colour   !! the colour of labels
end type edge_style_t

type :: node_data_t
    !! What was given for a node.
    character(len=:), allocatable :: name, fill, link, outline
end type node_data_t

type :: edge_data_t
    !! What was given for an edge.
    integer :: from = 0, to = 0
    logical :: dashed = .false.
    character(len=:), allocatable :: label, colour
end type edge_data_t

type :: graph_t
    !! A graph, and its layout.
    private
    integer :: direction = RANK_LR
    logical :: concentrate = .false.
    logical :: done = .false.
    type(node_style_t) :: node_style
    type(edge_style_t) :: edge_style
    integer :: nn = 0, ne = 0
    type(node_data_t), allocatable :: nodes(:)
    type(edge_data_t), allocatable :: edges(:)
    type(core_t) :: c
contains
    private
    procedure, public :: initialize         !! start a new graph
    procedure, public :: add_node           !! add a node
    procedure, public :: add_edge           !! add an edge
    procedure, public :: layout             !! compute the layout
    procedure, public :: write_svg          !! draw the layout
    procedure, public :: write_dot          !! write the graph in the DOT language, for debugging
    procedure, public :: node_count         !! how many nodes there are
    procedure, public :: edge_count         !! how many edges there are
    procedure, public :: size_of_drawing    !! the size of the layout
    procedure, public :: node_position      !! where a node is
    procedure, public :: edge_curves        !! how many curves an edge has
    procedure, public :: edge_curve         !! the control points of a curve of an edge
    procedure, public :: edge_label_position    !! where the label of an edge is
end type graph_t

contains

!> Start a new graph. By default ranks go from left to right, and edges are not concentrated.
pure subroutine initialize(this, direction, concentrate, node_style, edge_style)
    class(graph_t), intent(inout) :: this                   !! the graph
    integer, intent(in), optional :: direction              !! `RANK_LR` or `RANK_RL`
    logical, intent(in), optional :: concentrate            !! whether to merge edges that run together
    type(node_style_t), intent(in), optional :: node_style  !! how nodes look
    type(edge_style_t), intent(in), optional :: edge_style  !! how edges look

    this%direction = RANK_LR
    if (present(direction)) this%direction = direction
    this%concentrate = .false.
    if (present(concentrate)) this%concentrate = concentrate
    this%node_style = node_style_t()
    if (present(node_style)) this%node_style = node_style
    this%edge_style = edge_style_t()
    if (present(edge_style)) this%edge_style = edge_style
    if (.not. allocated(this%edge_style%colour)) this%edge_style%colour = '#8a93a5'
    if (.not. allocated(this%edge_style%label_colour)) this%edge_style%label_colour = '#8a93a5'
    this%nn = 0
    this%ne = 0
    this%done = .false.
    if (allocated(this%nodes)) deallocate (this%nodes)
    if (allocated(this%edges)) deallocate (this%edges)
    allocate (this%nodes(16), this%edges(16))
end subroutine initialize

!> Add a node, and return its number. The colours and the link are passed through as text.
pure subroutine add_node(this, name, id, fill, link, outline)
    class(graph_t), intent(inout) :: this           !! the graph
    character(len=*), intent(in) :: name            !! the text of the node
    integer, intent(out) :: id                      !! its number
    character(len=*), intent(in), optional :: fill  !! the fill colour
    character(len=*), intent(in), optional :: link  !! where it links to
    character(len=*), intent(in), optional :: outline   !! the colour of an outline
    type(node_data_t), allocatable :: bigger(:)
    integer :: k

    if (.not. allocated(this%nodes)) call this%initialize()
    if (this%nn == size(this%nodes)) then
        allocate (bigger(2*this%nn))
        do k = 1, this%nn
            call move_alloc(this%nodes(k)%name, bigger(k)%name)
            call move_alloc(this%nodes(k)%fill, bigger(k)%fill)
            call move_alloc(this%nodes(k)%link, bigger(k)%link)
            call move_alloc(this%nodes(k)%outline, bigger(k)%outline)
        end do
        call move_alloc(bigger, this%nodes)
    end if
    this%nn = this%nn + 1
    id = this%nn
    this%done = .false.
    associate (n => this%nodes(id))
        n%name = name
        n%fill = '#646d7e'
        if (present(fill)) n%fill = fill
        n%link = ''
        if (present(link)) n%link = link
        n%outline = ''
        if (present(outline)) n%outline = outline
    end associate
end subroutine add_node

!> Add an edge between two nodes. An edge with a label is dashed unless told otherwise.
pure subroutine add_edge(this, from, to, colour, label, dashed)
    class(graph_t), intent(inout) :: this               !! the graph
    integer, intent(in) :: from                         !! where it starts
    integer, intent(in) :: to                           !! where it ends
    character(len=*), intent(in), optional :: colour    !! the colour
    character(len=*), intent(in), optional :: label     !! the label
    logical, intent(in), optional :: dashed             !! whether it is dashed
    type(edge_data_t), allocatable :: bigger(:)
    integer :: k

    if (.not. allocated(this%edges)) call this%initialize()
    if (this%ne == size(this%edges)) then
        allocate (bigger(2*this%ne))
        do k = 1, this%ne
            bigger(k)%from = this%edges(k)%from
            bigger(k)%to = this%edges(k)%to
            bigger(k)%dashed = this%edges(k)%dashed
            call move_alloc(this%edges(k)%label, bigger(k)%label)
            call move_alloc(this%edges(k)%colour, bigger(k)%colour)
        end do
        call move_alloc(bigger, this%edges)
    end if
    this%ne = this%ne + 1
    this%done = .false.
    associate (e => this%edges(this%ne))
        e%from = from
        e%to = to
        e%colour = this%edge_style%colour
        if (present(colour)) e%colour = colour
        e%label = ''
        if (present(label)) e%label = label
        e%dashed = len(e%label) > 0
        if (present(dashed)) e%dashed = dashed
    end associate
end subroutine add_edge

!> Compute the layout. `stat` is `FDOT_OK`, or says what went wrong.
subroutine layout(this, stat)
    class(graph_t), intent(inout) :: this   !! the graph
    integer, intent(out) :: stat            !! the result
    type(core_t) :: fresh
    integer, allocatable :: count(:)
    integer :: k, v, e, h, r

    stat = FDOT_OK
    this%done = .false.
    this%c = fresh
    if (this%nn == 0) then
        this%done = .true.
        return
    end if
    do e = 1, this%ne
        if (min(this%edges(e)%from, this%edges(e)%to) < 1 .or. max(this%edges(e)%from, this%edges(e)%to) > this%nn) then
            stat = FDOT_INVALID
            return
        end if
    end do
    associate (c => this%c)
        c%concentrate = this%concentrate
        c%flip = .true.
        c%arrow_size = this%edge_style%arrow_size
        call set_up_nodes(this)
        call set_up_edges(this)

        ! the edges of each node in the order `agfstout` gives them: by the node they go to
        allocate (c%gout(this%nn), count(this%nn))
        count = 0
        do e = 1, this%ne
            count(this%edges(e)%to) = count(this%edges(e)%to) + 1
        end do
        k = 1
        do v = 1, this%nn
            h = count(v)
            count(v) = k
            k = k + h
        end do
        block
            integer, allocatable :: sorted(:)

            allocate (sorted(this%ne))
            do e = 1, this%ne
                sorted(count(this%edges(e)%to)) = e
                count(this%edges(e)%to) = count(this%edges(e)%to) + 1
            end do
            do k = 1, this%ne
                call push(c%gout(this%edges(sorted(k))%from), sorted(k))
            end do
        end block

        call dot_rank(c, r)
        if (r /= 0) then
            stat = FDOT_NO_RANKS
            return
        end if
        call dot_mincross(c, r)
        if (r /= 0) then
            stat = FDOT_FLAT_EDGE
            return
        end if
        call dot_position(c, r)
        if (r /= 0) then
            stat = FDOT_NO_RANKS
            return
        end if
        call dot_splines(c, r)
        if (r /= 0) then
            stat = FDOT_NO_ROUTE
            return
        end if
        call translate_drawing(c, this%direction == RANK_RL)
    end associate
    this%done = .true.
end subroutine layout

!> Make the nodes of the working graph, with their sizes.
pure subroutine set_up_nodes(this)
    class(graph_t), intent(inout) :: this   !! the graph
    real(wp) :: w, h, pen
    integer :: k, v

    allocate (this%c%out_w(this%nn), this%c%out_h(this%nn))
    do k = 1, this%nn
        call new_node(this%c, v)
        associate (n => this%c%nd(v), s => this%node_style)
            call node_size(text_width(this%nodes(k)%name, s%font_size), text_height(s%font_size), &
                           s%margin_x, s%margin_y, s%height, w, h)
            ! ranks go across the page, so the layout works with the box on its side
            n%lw = h/2
            n%rw = h/2
            n%ht = w
            pen = merge(s%pen_width, 1.0_wp, len(this%nodes(k)%outline) > 0)
            this%c%out_w(v) = (w + pen)/2
            this%c%out_h(v) = (h + pen)/2
        end associate
    end do
    this%c%nn = this%nn
end subroutine set_up_nodes

!> Make the edges of the working graph, with the sizes of their labels.
pure subroutine set_up_edges(this)
    class(graph_t), intent(inout) :: this   !! the graph
    integer :: k, e

    allocate (this%c%label_w(this%ne), this%c%label_h(this%ne), this%c%labelled(this%ne), this%c%label_pos(this%ne))
    do k = 1, this%ne
        call new_edge(this%c, this%edges(k)%from, this%edges(k)%to, e)
        this%c%ed(e)%etype = NORMAL
        this%c%ed(e)%seq = e
        this%c%labelled(e) = len(this%edges(k)%label) > 0
        this%c%label_w(e) = 0
        this%c%label_h(e) = 0
        if (this%c%labelled(e)) then
            this%c%label_w(e) = text_width(this%edges(k)%label, this%edge_style%font_size)
            this%c%label_h(e) = text_height(this%edge_style%font_size)
            this%c%has_labels = .true.
        end if
    end do
    this%c%ne = this%ne
end subroutine set_up_edges

!> Draw the layout as SVG. The drawing is empty if there is no layout.
pure subroutine write_svg(this, svg)
    class(graph_t), intent(in) :: this                  !! the graph
    character(len=:), allocatable, intent(out) :: svg   !! the drawing
    type(buffer_t) :: b
    logical, allocatable :: drawn(:)
    integer :: v, k, e

    svg = ''
    if (.not. this%done .or. this%nn == 0) return
    associate (c => this%c)
        call svg_begin(b, c%bb%urx, c%bb%ury, PAD, this%edge_style%colour, this%node_style%font_size)
        allocate (drawn(this%nn), source=.false.)
        do v = 1, this%nn
            if (.not. drawn(v)) call draw_node(this, v, b)
            drawn(v) = .true.
            do k = 1, c%gout(v)%n
                e = c%gout(v)%a(k)
                if (.not. drawn(c%ed(e)%head)) call draw_node(this, c%ed(e)%head, b)
                drawn(c%ed(e)%head) = .true.
                call draw_edge(this, e, b)
            end do
        end do
        call svg_end(b)
    end associate
    call take(b, svg)
end subroutine write_svg

!> Draw a node.
pure subroutine draw_node(this, v, b)
    class(graph_t), intent(in) :: this  !! the graph
    integer, intent(in) :: v            !! the node
    type(buffer_t), intent(inout) :: b  !! the drawing
    real(wp) :: w, h, x, y

    call node_position(this, v, x, y, w, h)
    associate (n => this%nodes(v))
        if (len(n%link) > 0) then
            call add(b, '<a href="')
            call add_xml(b, n%link)
            call add(b, '" fill="white" stroke="none">')
            call svg_box_in_link(b, x - w/2, -y - h/2, w, h, n%fill, n%outline, this%node_style%pen_width)
            call svg_text(b, x, -y + BASELINE*this%node_style%font_size, n%name, 0.0_wp, '')
            call add(b, '</a>')
        else
            call svg_box(b, x - w/2, -y - h/2, w, h, n%fill, n%outline, this%node_style%pen_width)
            call svg_text(b, x, -y + BASELINE*this%node_style%font_size, n%name, 0.0_wp, 'white')
        end if
    end associate
end subroutine draw_node

!> Draw the box of a node inside a link, which has `stroke="none"` already.
pure subroutine svg_box_in_link(b, x, y, width, height, fill, outline, pen)
    type(buffer_t), intent(inout) :: b      !! the drawing
    real(wp), intent(in) :: x               !! the left side
    real(wp), intent(in) :: y               !! the top side, downwards
    real(wp), intent(in) :: width           !! the width
    real(wp), intent(in) :: height          !! the height
    character(len=*), intent(in) :: fill    !! the fill
    character(len=*), intent(in) :: outline !! the colour of the outline
    real(wp), intent(in) :: pen             !! the width of the outline
    type(buffer_t) :: box
    character(len=:), allocatable :: text
    integer :: at

    call svg_box(box, x, y, width, height, fill, outline, pen)
    call take(box, text)
    at = index(text, ' stroke="none"')
    if (at > 0) text = text(1:at - 1)//text(at + 14:)
    call add(b, text)
end subroutine svg_box_in_link

!> Draw an edge.
pure subroutine draw_edge(this, e, b)
    class(graph_t), intent(in) :: this  !! the graph
    integer, intent(in) :: e            !! the edge
    type(buffer_t), intent(inout) :: b  !! the drawing
    type(point_t) :: corners(3)
    character(len=:), allocatable :: stroke
    integer :: j, n

    stroke = ''
    if (this%edges(e)%colour /= this%edge_style%colour) stroke = this%edges(e)%colour
    do j = 1, this%c%spl(e)%n
        associate (s => this%c%spl(e)%b(j))
            n = size(s%list)
            call svg_curve(b, s%list, stroke, this%edges(e)%dashed)
            if (s%sflag) then
                call arrow_polygon(s%sp, s%list(1), this%edge_style%arrow_size, corners)
                call svg_arrow(b, corners, this%edges(e)%colour, stroke)
            end if
            if (s%eflag) then
                call arrow_polygon(s%ep, s%list(n), this%edge_style%arrow_size, corners)
                call svg_arrow(b, corners, this%edges(e)%colour, stroke)
            end if
        end associate
    end do
    if (this%c%labelled(e)) then
        call svg_text(b, this%c%label_pos(e)%x, -this%c%label_pos(e)%y + BASELINE*this%edge_style%font_size, &
                      this%edges(e)%label, this%edge_style%font_size, this%edge_style%label_colour)
    end if
end subroutine draw_edge

!> Write the graph in the DOT language, for debugging and for comparing with `dot`.
pure subroutine write_dot(this, text)
    class(graph_t), intent(in) :: this                  !! the graph
    character(len=:), allocatable, intent(out) :: text  !! the text
    character(len=*), parameter :: NL = new_line('a')
    type(buffer_t) :: b
    integer :: k

    call add(b, 'digraph g {'//NL//'rankdir='//merge('RL', 'LR', this%direction == RANK_RL)// &
             '; bgcolor="transparent"; concentrate='//merge('true ', 'false', this%concentrate)//';'//NL)
    call add(b, 'node [shape=box, style="rounded,filled", fontname="Helvetica", fontsize=')
    call add_tenths(b, this%node_style%font_size)
    call add(b, ', fontcolor=white, color=transparent, height=0.3, margin="0.1,0.04"];'//NL)
    call add(b, 'edge [color="'//this%edge_style%colour//'", arrowsize=')
    call add_tenths(b, this%edge_style%arrow_size)
    call add(b, '];'//NL)
    do k = 1, this%nn
        call add(b, 'n')
        call add_int(b, int(k, int64))
        call add(b, ' [label="')
        call add_dot_string(b, this%nodes(k)%name)
        call add(b, '", fillcolor="'//this%nodes(k)%fill//'"')
        if (len(this%nodes(k)%outline) > 0) then
            call add(b, ', penwidth=')
            call add_tenths(b, this%node_style%pen_width)
            call add(b, ', color="'//this%nodes(k)%outline//'"')
        end if
        if (len(this%nodes(k)%link) > 0) then
            call add(b, ', URL="')
            call add_dot_string(b, this%nodes(k)%link)
            call add(b, '"')
        end if
        call add(b, '];'//NL)
    end do
    do k = 1, this%ne
        call add(b, 'n')
        call add_int(b, int(this%edges(k)%from, int64))
        call add(b, ' -> n')
        call add_int(b, int(this%edges(k)%to, int64))
        call add(b, ' [color="'//this%edges(k)%colour//'"')
        if (this%edges(k)%dashed) call add(b, ', style=dashed')
        if (len(this%edges(k)%label) > 0) then
            call add(b, ', fontname="Helvetica", fontsize=')
            call add_tenths(b, this%edge_style%font_size)
            call add(b, ', fontcolor="'//this%edge_style%label_colour//'", label="')
            call add_dot_string(b, this%edges(k)%label)
            call add(b, '"')
        end if
        call add(b, '];'//NL)
    end do
    call add(b, '}'//NL)
    call take(b, text)
end subroutine write_dot

!> Append text for a quoted string of DOT.
pure subroutine add_dot_string(b, text)
    type(buffer_t), intent(inout) :: b      !! the buffer
    character(len=*), intent(in) :: text    !! the text
    integer :: k

    do k = 1, len(text)
        if (text(k:k) == '"' .or. text(k:k) == '\') call add(b, '\')
        call add(b, text(k:k))
    end do
end subroutine add_dot_string

!> How many nodes there are.
pure integer function node_count(this)
    class(graph_t), intent(in) :: this  !! the graph

    node_count = this%nn
end function node_count

!> How many edges there are.
pure integer function edge_count(this)
    class(graph_t), intent(in) :: this  !! the graph

    edge_count = this%ne
end function edge_count

!> The size of the layout in points, without padding.
pure subroutine size_of_drawing(this, width, height)
    class(graph_t), intent(in) :: this  !! the graph
    real(wp), intent(out) :: width      !! the width
    real(wp), intent(out) :: height     !! the height

    width = this%c%bb%urx
    height = this%c%bb%ury
end subroutine size_of_drawing

!> Where a node is, in points, with `y` going up, and optionally its rank and place in the rank.
pure subroutine node_position(this, id, x, y, width, height, rank, order)
    class(graph_t), intent(in) :: this      !! the graph
    integer, intent(in) :: id               !! the node
    real(wp), intent(out) :: x              !! the centre
    real(wp), intent(out) :: y              !! the centre
    real(wp), intent(out) :: width          !! the width
    real(wp), intent(out) :: height         !! the height
    integer, intent(out), optional :: rank  !! the rank
    integer, intent(out), optional :: order !! the place in the rank

    x = this%c%nd(id)%x
    y = this%c%nd(id)%y
    ! the layout had the box on its side
    width = this%c%nd(id)%ht
    height = this%c%nd(id)%lw + this%c%nd(id)%rw
    if (present(rank)) rank = this%c%nd(id)%rank
    if (present(order)) order = this%c%nd(id)%order
end subroutine node_position

!> How many curves edge `id` has. A concentrated edge can have several, or none.
pure integer function edge_curves(this, id)
    class(graph_t), intent(in) :: this  !! the graph
    integer, intent(in) :: id           !! the edge

    edge_curves = this%c%spl(id)%n
end function edge_curves

!> The control points of curve `k` of edge `id`, from tail to head, and the end points of arrowheads.
pure subroutine edge_curve(this, id, k, points, has_start, start, has_end, end)
    class(graph_t), intent(in) :: this      !! the graph
    integer, intent(in) :: id               !! the edge
    integer, intent(in) :: k                !! the curve
    type(point_t), allocatable, intent(out) :: points(:)    !! the control points
    logical, intent(out), optional :: has_start     !! whether there is an arrowhead at the start
    type(point_t), intent(out), optional :: start   !! where it ends
    logical, intent(out), optional :: has_end       !! whether there is an arrowhead at the end
    type(point_t), intent(out), optional :: end     !! where it ends

    points = this%c%spl(id)%b(k)%list
    if (present(has_start)) has_start = this%c%spl(id)%b(k)%sflag
    if (present(start)) start = this%c%spl(id)%b(k)%sp
    if (present(has_end)) has_end = this%c%spl(id)%b(k)%eflag
    if (present(end)) end = this%c%spl(id)%b(k)%ep
end subroutine edge_curve

!> Where the label of edge `id` is, if it has one.
pure subroutine edge_label_position(this, id, x, y, has_label)
    class(graph_t), intent(in) :: this  !! the graph
    integer, intent(in) :: id           !! the edge
    real(wp), intent(out) :: x          !! the centre
    real(wp), intent(out) :: y          !! the centre
    logical, intent(out) :: has_label   !! whether it has a label

    has_label = this%c%labelled(id)
    x = 0
    y = 0
    if (has_label) then
        x = this%c%label_pos(id)%x
        y = this%c%label_pos(id)%y
    end if
end subroutine edge_label_position

end module fdot
 
 
!>>>>> build/dependencies/fformat/src/ffmt_constructs.f90
module ffmt_constructs
!! Classifies statements by their role in the block structure: opening a construct or program
!! unit, continuing one (`else`, `case`, `contains`, ...), or closing one.
!!
!! Classification looks only at a statement's code tokens. Keywords are not reserved in Fortran,
!! so a keyword followed by `=`, `=>` or `%` is treated as a variable (`end = 1`).
use ffmt_tokens
use ffmt_statements, only: statement_view_t
use ffmt_strings, only: string_t
implicit none
private

public :: classify_statement, construct_label, closed_construct

! roles
integer, parameter, public :: ROLE_NONE = 0
integer, parameter, public :: ROLE_OPEN = 1
integer, parameter, public :: ROLE_MIDDLE = 2
integer, parameter, public :: ROLE_CLOSE = 3

! constructs
integer, parameter, public :: C_NONE = 0         !! no construct
integer, parameter, public :: C_ANY = 1          !! a bare `end`
integer, parameter, public :: C_PROGRAM = 2
integer, parameter, public :: C_MODULE = 3
integer, parameter, public :: C_SUBMODULE = 4
integer, parameter, public :: C_SUBROUTINE = 5
integer, parameter, public :: C_FUNCTION = 6
integer, parameter, public :: C_PROCEDURE = 7    !! separate module procedure (`module procedure name` in a submodule)
integer, parameter, public :: C_BLOCK_DATA = 8
integer, parameter, public :: C_INTERFACE = 9
integer, parameter, public :: C_TYPE = 10
integer, parameter, public :: C_ENUM = 11
integer, parameter, public :: C_IF = 12
integer, parameter, public :: C_DO = 13
integer, parameter, public :: C_SELECT = 14
integer, parameter, public :: C_ASSOCIATE = 15
integer, parameter, public :: C_BLOCK = 16
integer, parameter, public :: C_CRITICAL = 17
integer, parameter, public :: C_TEAM = 18
integer, parameter, public :: C_WHERE = 19
integer, parameter, public :: C_FORALL = 20
integer, parameter, public :: C_CONTAINS = 21    !! `contains` (a middle statement of program units and types)
integer, parameter, public :: C_ENUMERATION = 22 !! `enumeration type` (F2023)

integer, parameter :: NCONSTRUCTS = 22
integer, parameter :: WORD_LEN = 32     !! longer than any keyword
character(len=*), parameter :: LABELS(0:NCONSTRUCTS) = [character(len=16) :: &
                                                        'none', 'end', 'program', 'module', 'submodule', 'subroutine', 'function', &
                                                        'procedure', &
                                                        'block data', 'interface', 'type', 'enum', 'if', 'do', 'select', &
                                                        'associate', 'block', &
                                                        'critical', 'change team', 'where', 'forall', 'contains', &
                                                        'enumeration type']

type, public :: stmt_info_t
    !! What a statement does to the block structure, as found by `classify_statement`.
    integer :: role = ROLE_NONE      !! `ROLE_OPEN`, `ROLE_MIDDLE`, `ROLE_CLOSE`, or `ROLE_NONE` for other statements
    integer :: construct = C_NONE    !! the construct opened, continued or closed: one of the `C_*` constants
    integer :: label = 0         !! statement label, or 0
    integer :: do_label = 0      !! for `do 10 ...`: the label of the statement that ends the loop
    character(len=:), allocatable :: name  !! construct name, as in `outer: do`
end type stmt_info_t

type :: words_t
    !! The words of a statement, with combined keywords such as `endif` split into `end`, `if`.
    type(string_t), allocatable :: w(:)  !! the words of the first token; the others are its code tokens
    integer, allocatable :: tok(:)     !! index into the code token list for each word
    integer :: n = 0                   !! number of words
end type words_t

contains

pure integer function label_width(construct)
    !! Length of the text of `construct_label`.
    integer, intent(in) :: construct   !! one of the `C_*` constants
    label_width = 1
    if (construct >= 0 .and. construct <= NCONSTRUCTS) label_width = len_trim(LABELS(construct))
end function label_width

pure function construct_label(construct) result(label)
    !! Name of a construct for messages (`'if'`, `'select'`, `'end'` for a bare `end`), or `'?'`.
    integer, intent(in) :: construct   !! one of the `C_*` constants
    character(len=label_width(construct)) :: label
    if (construct < 0 .or. construct > NCONSTRUCTS) then
        label = '?'
    else
        label = LABELS(construct)
    end if
end function construct_label

function classify_statement(src, tokens, v, in_interface) result(info)
    !! Classify a code statement. `in_interface` is true directly inside an interface block,
    !! where `module procedure` lists procedures instead of starting one.
    character(len=*), intent(in) :: src           !! source text
    type(token_list_t), intent(in) :: tokens      !! tokens of `src`
    type(statement_view_t), intent(in) :: v       !! the statement
    logical, intent(in) :: in_interface           !! the innermost open construct is an interface block
    type(stmt_info_t) :: info

    type(words_t) :: wd
    integer :: k, j

    if (v%n == 0) return
    k = v%first
    if (k == 2) call read_label(v%low(v%lo(1):v%hi(1)), info%label)
    ! construct name, possibly partly generated by fypp: `outer: do`, `get_${x}$: if (...) then`
    j = k
    do while (j < v%n)
        if (.not. is_name(j)) exit
        j = j + 1
    end do
    if (j > k .and. j < v%n .and. v%is(j, ':')) then
        info%name = src(tokens%tok(v%code(k))%first:tokens%tok(v%code(j - 1))%last)
        k = j + 1
    end if
    if (.not. is_name(k)) return
    ! an assignment to a variable named like a keyword, or to an element of one (`rank (1) = n`)
    j = k + 1
    if (v%is(j, '(')) then
        if (v%closing(j) > 0) j = v%closing(j) + 1
    end if
    if (v%is(j, '=') .or. v%is(j, '=>') .or. v%is(j, '%')) return
    call split_words()
    call classify_words()

contains

    logical function is_name(j)
        !! True if code token `j` is a name, or inline fypp that generates one (`${name}$`).
        integer, intent(in) :: j   !! index into `v%code(:)`
        is_name = v%kind_of(j) == TK_NAME .or. v%kind_of(j) == TK_FYPP
    end function is_name

    function word(j) result(t)
        !! Lowercase word `j`, or blank past the end. Words are only compared with keywords, all
        !! shorter than `WORD_LEN`, so one that is cut short cannot match by mistake. The length is
        !! fixed because classification must be thread-safe: the length of a deferred-length
        !! function result is kept in static storage by gfortran.
        integer, intent(in) :: j   !! index into the words `wd`
        character(len=WORD_LEN) :: t
        if (j > wd%n) then
            t = ''
        else if (j <= size(wd%w)) then
            t = wd%w(j)%s
        else
            t = v%low(v%lo(wd%tok(j)):v%hi(wd%tok(j)))
        end if
    end function word

    integer function after_parens(j) result(next)
        !! Index of the code token after the parenthesis that opens at word `j`, or 0 if word `j`
        !! is not `(` or the parenthesis is not closed.
        integer, intent(in) :: j   !! index into the words `wd`
        next = 0
        if (j > wd%n) return
        next = v%closing(wd%tok(j))
        if (next > 0) next = next + 1
    end function after_parens

    logical function is_name_word(j)
        !! True if word `j` is a name, or inline fypp that generates one (`${name}$`).
        integer, intent(in) :: j   !! index into the words `wd`
        is_name_word = .false.
        if (j > wd%n) return
        is_name_word = is_name(wd%tok(j))
    end function is_name_word

    logical function has_attribute(attr)
        !! True if `attr` appears among the words before `::`.
        character(len=*), intent(in) :: attr   !! the attribute, in lowercase
        integer :: j
        has_attribute = .false.
        do j = 2, wd%n
            if (word(j) == '::') return
            if (word(j) == attr) then
                has_attribute = .true.
                return
            end if
        end do
    end function has_attribute

    integer function word_at(c) result(j)
        !! Index of the first word at or after code token `c`, or `wd%n + 1` if there is none.
        integer, intent(in) :: c   !! index into `v%code(:)`
        do j = 1, wd%n
            if (wd%tok(j) >= c) return
        end do
        j = wd%n + 1
    end function word_at

    subroutine split_words()
        !! Fill `wd` with the words of the statement from code token `k` on, splitting the first
        !! one with `expand_keyword`.
        type(string_t), allocatable :: parts(:)
        integer :: j, np

        ! only `end...`, `else...`, `select...`, `block...`, `change...` and `double...` can be
        ! combined keywords; other first words are read from the view, like the rest (see `word`)
        associate (first => v%low(v%lo(k):v%hi(k)))
            if (index(first, 'end') == 1 .or. index(first, 'else') == 1 .or. index(first, 'select') == 1 .or. &
                index(first, 'block') == 1 .or. index(first, 'change') == 1 .or. index(first, 'double') == 1) then
                parts = expand_keyword(first)
                if (size(parts) > 1) call move_alloc(parts, wd%w)
            end if
        end associate
        if (.not. allocated(wd%w)) allocate (wd%w(0))
        np = max(1, size(wd%w))
        allocate (wd%tok(np + v%n - k))
        wd%tok(1:np) = k
        wd%n = np
        do j = k + 1, v%n
            wd%n = wd%n + 1
            wd%tok(wd%n) = j
        end do
    end subroutine split_words

    subroutine classify_words()
        !! Set `info` from the words in `wd`, by the first word.
        integer :: c
        character(len=:), allocatable :: label_text

        select case (word(1))
        case ('end')
            c = closed_construct(word(2), word(3))
            if (c /= C_NONE) call set(info, ROLE_CLOSE, c)
        case ('else')
            select case (word(2))
            case ('', 'if')
                call set(info, ROLE_MIDDLE, C_IF)
            case ('where')
                call set(info, ROLE_MIDDLE, C_WHERE)
            case default
                if (wd%n == 2) call set(info, ROLE_MIDDLE, C_IF)   ! else construct-name
            end select
        case ('if')
            c = after_parens(2)
            if (c > 0 .and. c == v%n) then
                if (v%is(c, 'then')) call set(info, ROLE_OPEN, C_IF)
            end if
        case ('do')
            call set(info, ROLE_OPEN, C_DO)
            if (wd%n >= 2) then
                if (v%kind_of(wd%tok(2)) == TK_INT) then
                    label_text = word(2)
                    call read_label(label_text, info%do_label)
                end if
            end if
        case ('select')
            select case (word(2))
            case ('case', 'type', 'rank')
                call set(info, ROLE_OPEN, C_SELECT)
            end select
        case ('case', 'rank')
            if (word(2) == '(' .or. word(2) == 'default') call set(info, ROLE_MIDDLE, C_SELECT)
        case ('type')
            if (word(2) == 'is' .and. word(3) == '(') then
                call set(info, ROLE_MIDDLE, C_SELECT)
            else if (word(2) == '(') then
                call check_procedure(1)
            else if (wd%n >= 2 .and. .not. has_attribute('deferred')) then
                ! `type, deferred :: T` declares a type parameter of a template (F202Y)
                call set(info, ROLE_OPEN, C_TYPE)
            end if
        case ('class')
            if ((word(2) == 'is' .and. word(3) == '(') .or. (word(2) == 'default' .and. wd%n == 2)) then
                call set(info, ROLE_MIDDLE, C_SELECT)
            else
                call check_procedure(1)
            end if
        case ('module')
            if (word(2) == 'procedure') then
                if (.not. in_interface) call set(info, ROLE_OPEN, C_PROCEDURE)
            else
                call check_procedure(1)
                if (info%role == ROLE_NONE .and. is_name_word(2)) call set(info, ROLE_OPEN, C_MODULE)
            end if
        case ('submodule')
            if (word(2) == '(') call set(info, ROLE_OPEN, C_SUBMODULE)
        case ('program')
            call set(info, ROLE_OPEN, C_PROGRAM)
        case ('block')
            if (wd%n == 1) then
                call set(info, ROLE_OPEN, C_BLOCK)
            else if (word(2) == 'data') then
                call set(info, ROLE_OPEN, C_BLOCK_DATA)
            end if
        case ('interface')
            call set(info, ROLE_OPEN, C_INTERFACE)
        case ('abstract')
            if (word(2) == 'interface') call set(info, ROLE_OPEN, C_INTERFACE)
        case ('enum')
            call set(info, ROLE_OPEN, C_ENUM)
        case ('enumeration')
            if (word(2) == 'type') call set(info, ROLE_OPEN, C_ENUMERATION)
        case ('associate')
            if (word(2) == '(') call set(info, ROLE_OPEN, C_ASSOCIATE)
        case ('critical')
            call set(info, ROLE_OPEN, C_CRITICAL)
        case ('change')
            if (word(2) == 'team') call set(info, ROLE_OPEN, C_TEAM)
        case ('where')
            if (after_parens(2) == v%n + 1) call set(info, ROLE_OPEN, C_WHERE)
        case ('forall')
            if (after_parens(2) == v%n + 1) call set(info, ROLE_OPEN, C_FORALL)
        case ('contains')
            if (wd%n == 1) call set(info, ROLE_MIDDLE, C_CONTAINS)
        case default
            call check_procedure(1)
        end select
    end subroutine classify_words

    subroutine check_procedure(j0)
        !! `[prefixes] [type-spec] function name` or `[prefixes] subroutine name`, starting at word `j0`:
        !! if the words match, set `info` to open a function or subroutine.
        integer, intent(in) :: j0   !! index of the first word to look at
        integer :: j, c

        j = j0
        do while (j <= wd%n)
            if (v%kind_of(wd%tok(j)) == TK_FYPP) then
                j = j + 1   ! a type or prefix generated by fypp, e.g. `${t}$ function f()`
                cycle
            end if
            select case (word(j))
            case ('pure', 'impure', 'elemental', 'recursive', 'non_recursive', 'module', 'simple')
                j = j + 1
            case ('integer', 'real', 'complex', 'logical', 'character', 'doubleprecision', 'doublecomplex')
                j = j + 1
                call skip_selector(j)
            case ('double')
                j = j + 1
                if (word(j) == 'precision' .or. word(j) == 'complex') j = j + 1
            case ('type', 'class')
                c = after_parens(j + 1)
                if (c == 0) return
                j = word_at(c)
            case ('function', 'subroutine')
                if (j + 1 > wd%n) return
                if (.not. is_name_word(j + 1)) return
                call set(info, ROLE_OPEN, merge(C_FUNCTION, C_SUBROUTINE, word(j) == 'function'))
                return
            case default
                ! a prefix made by a cpp macro: `PURE_IF_NO_DEBUG FUNCTION f(x)`
                if (.not. is_name_word(j)) return
                if (word(j + 1) /= 'function' .and. word(j + 1) /= 'subroutine') return
                j = j + 1
            end select
        end do
    end subroutine check_procedure

    subroutine skip_selector(j)
        !! Skip a kind or length selector after an intrinsic type: `(kind=8)`, `(len=*)`, `*8`, `*(*)`.
        integer, intent(inout) :: j   !! word index: the word after the type name, then the word after the selector
        integer :: c
        if (word(j) == '(') then
            c = after_parens(j)
            if (c > 0) j = word_at(c)
        else if (word(j) == '*') then
            j = j + 1
            if (word(j) == '(') then
                c = after_parens(j)
                if (c > 0) j = word_at(c)
            else
                j = j + 1
            end if
        end if
    end subroutine skip_selector

end function classify_statement

pure integer function closed_construct(second, third) result(construct)
    !! The construct that `end second third` closes (`C_ANY` for a bare `end`), or `C_NONE` if
    !! `second` names no construct, so that the `end` is not a closing statement.
    character(len=*), intent(in) :: second   !! the word after `end`, in lowercase, or `''`
    character(len=*), intent(in) :: third    !! the word after that, or `''` (`data` in `end block data`)
    select case (second)
    case ('')
        construct = C_ANY
    case ('if')
        construct = C_IF
    case ('do')
        construct = C_DO
    case ('select')
        construct = C_SELECT
    case ('associate')
        construct = C_ASSOCIATE
    case ('block')
        construct = merge(C_BLOCK_DATA, C_BLOCK, third == 'data')
    case ('blockdata')
        construct = C_BLOCK_DATA
    case ('critical')
        construct = C_CRITICAL
    case ('team')
        construct = C_TEAM
    case ('where')
        construct = C_WHERE
    case ('forall')
        construct = C_FORALL
    case ('enum')
        construct = C_ENUM
    case ('enumeration')
        construct = merge(C_ENUMERATION, C_NONE, third == 'type')
    case ('interface')
        construct = C_INTERFACE
    case ('type')
        construct = C_TYPE
    case ('function')
        construct = C_FUNCTION
    case ('subroutine')
        construct = C_SUBROUTINE
    case ('procedure')
        construct = C_PROCEDURE
    case ('module')
        construct = C_MODULE
    case ('submodule')
        construct = C_SUBMODULE
    case ('program')
        construct = C_PROGRAM
    case default
        construct = C_NONE
    end select
end function closed_construct

pure subroutine read_label(text, label)
    !! Set `label` to the value of `text`, unless that is not a statement label. This is not an internal
    !! `read`, because it runs in parallel, where those take a lock in the runtime library.
    character(len=*), intent(in) :: text    !! the label
    integer, intent(inout) :: label         !! its value, or as it was
    integer :: k, n, value

    n = len_trim(text)
    if (n == 0 .or. n > 9) return
    value = 0
    do k = 1, n
        if (text(k:k) < '0' .or. text(k:k) > '9') return
        value = 10*value + iachar(text(k:k)) - iachar('0')
    end do
    label = value
end subroutine read_label

pure subroutine set(info, role, construct)
    !! Set the role and construct of `info`.
    type(stmt_info_t), intent(inout) :: info   !! the classification to update
    integer, intent(in) :: role                !! one of the `ROLE_*` constants
    integer, intent(in) :: construct           !! one of the `C_*` constants
    info%role = role
    info%construct = construct
end subroutine set

pure function expand_keyword(w) result(parts)
    !! Split a keyword that may be written as one word (`endif`, `elseif`, `selectcase`,
    !! `endblockdata`, ...) into its parts. Other words are returned unchanged.
    character(len=*), intent(in) :: w   !! the word, in lowercase
    type(string_t), allocatable :: parts(:)
    character(len=*), parameter :: ends(*) = [character(len=11) :: &
                                              'associate', 'blockdata', 'block', 'critical', 'do', 'enum', 'forall', 'function', &
                                              'if', &
                                              'interface', 'module', 'procedure', 'program', 'select', 'submodule', 'subroutine', &
                                              'team', &
                                              'type', 'where']
    integer :: k

    if (len(w) > 3 .and. w(1:min(3, len(w))) == 'end') then
        do k = 1, size(ends)
            if (w(4:) == trim(ends(k))) then
                if (w(4:) == 'blockdata') then
                    parts = [string_t('end'), string_t('block'), string_t('data')]
                else
                    parts = [string_t('end'), string_t(w(4:))]
                end if
                return
            end if
        end do
    end if
    select case (w)
    case ('elseif')
        parts = [string_t('else'), string_t('if')]
    case ('elsewhere')
        parts = [string_t('else'), string_t('where')]
    case ('selectcase')
        parts = [string_t('select'), string_t('case')]
    case ('selecttype')
        parts = [string_t('select'), string_t('type')]
    case ('selectrank')
        parts = [string_t('select'), string_t('rank')]
    case ('blockdata')
        parts = [string_t('block'), string_t('data')]
    case ('changeteam')
        parts = [string_t('change'), string_t('team')]
    case ('doubleprecision')
        parts = [string_t('double'), string_t('precision')]
    case default
        parts = [string_t(w)]
    end select
end function expand_keyword

end module ffmt_constructs
 
 
!>>>>> build/dependencies/fformat/src/ffmt_directives.f90
module ffmt_directives
!! Formatter directives in comments, which protect code from formatting:
!!
!! * `!&` at the end of a statement keeps the statement exactly as it is.
!! * `!&<` on a line of its own starts a region that is kept exactly as it is, and `!&>` ends it.
use ffmt_tokens
use ffmt_statements
implicit none
private

public :: protected_items

integer, parameter :: DIR_NONE = 0, DIR_KEEP = 1, DIR_OFF = 2, DIR_ON = 3   !! none, `!&`, `!&<`, `!&>`

contains

function protected_items(src, tokens, stmts) result(keep)
    !! True for each item that must be written exactly as it is: statements with a `!&` comment, and
    !! everything from a `!&<` line to the next `!&>` line, both included.
    character(len=*), intent(in) :: src              !! source text
    type(token_list_t), intent(in) :: tokens         !! tokens of `src`
    type(statement_list_t), intent(in) :: stmts      !! items of `tokens`
    logical, allocatable :: keep(:)
    logical :: off
    integer :: k, j, d

    allocate (keep(stmts%n))
    off = .false.
    do k = 1, stmts%n
        keep(k) = off
        do j = stmts%s(k)%first, stmts%s(k)%last
            if (tokens%tok(j)%kind /= TK_COMMENT) cycle
            d = directive(src, tokens%tok(j))
            if (stmts%s(k)%kind == SK_COMMENT .and. d == DIR_OFF) then
                off = .true.
                keep(k) = .true.
            else if (stmts%s(k)%kind == SK_COMMENT .and. d == DIR_ON) then
                off = .false.
                keep(k) = .true.
            else if (stmts%s(k)%kind == SK_CODE .and. d == DIR_KEEP) then
                keep(k) = .true.
            end if
        end do
    end do
end function protected_items

integer function directive(src, t)
    !! Formatter directive (one of the DIR_* constants) of a comment token.
    character(len=*), intent(in) :: src   !! source text
    type(token_t), intent(in) :: t        !! a comment token of `src`
    character(len=:), allocatable :: text
    integer :: n
    directive = DIR_NONE
    if (t%sub /= CM_FORMATTER) return
    text = token_text(src, t)
    n = len(text)
    do while (n > 0)                        ! without trailing blanks and tabs
        if (text(n:n) /= ' ' .and. text(n:n) /= achar(9)) exit
        n = n - 1
    end do
    text = text(1:n)
    if (text == '!&<') then
        directive = DIR_OFF
    else if (text == '!&>') then
        directive = DIR_ON
    else if (len(text) == 2) then
        directive = DIR_KEEP
    else if (text(3:3) == ' ') then
        directive = DIR_KEEP
    end if
end function directive

end module ffmt_directives
 
 
