!> Sorting algorithms to work with hash maps
module tomlf_utils_sort
   use tomlf_type_value, only : toml_key
   implicit none
   private

   public :: sort, compare_less


   !> Create overloaded interface for export
   interface sort
      module procedure :: sort_keys
   end interface


   abstract interface
      !> Define order relation between two TOML keys
      pure function compare_less(lhs, rhs) result(less)
         import :: toml_key
         !> Left hand side TOML key in comparison
         type(toml_key), intent (in) :: lhs
         !> Right hand side TOML key in comparison
         type(toml_key), intent (in) :: rhs
         !> Comparison result
         logical :: less
      end function compare_less
   end interface


contains


   !> Entry point for sorting algorithm
   pure subroutine sort_keys(list, idx, compare)

      !> List of TOML keys to be sorted
      type(toml_key), intent(inout) :: list(:)

      !> Optionally, mapping from unsorted list to sorted list
      integer, intent(out), optional :: idx(:)

      !> Function implementing the order relation between two TOML keys
      procedure(compare_less), optional :: compare

      integer  :: low, high, i
      type(toml_key), allocatable  :: sorted(:)
      integer, allocatable :: indexarray(:)

      low = 1
      high = size(list)

      allocate(sorted, source=list)

      allocate(indexarray(high), source=[(i, i=low, high)])

      if (present(compare)) then
         call quicksort(sorted, indexarray, low, high, compare)
      else
         call quicksort(sorted, indexarray, low, high, compare_keys_less)
      end if

      do i = low, high
         list(i) = sorted(indexarray(i))
      end do

      if (present(idx)) then
         idx = indexarray
      end if

   end subroutine sort_keys


   !> Actual quick sort implementation
   pure recursive subroutine quicksort(list, idx, low, high, less)
      type(toml_key), intent(inout) :: list(:)
      integer, intent(inout) :: idx(:)
      integer, intent(in) :: low, high
      procedure(compare_less) :: less

      integer :: i, last
      integer :: pivot

      if (low < high) then

         call swap(idx(low), idx((low + high)/2))
         last = low
         do i = low + 1, high
            if (less(list(idx(i)), list(idx(low)))) then
               last = last + 1
               call swap(idx(last), idx(i))
            end if
         end do
         call swap(idx(low), idx(last))
         pivot = last

         call quicksort(list, idx, low, pivot - 1, less)
         call quicksort(list, idx, pivot + 1, high, less)
      end if

   end subroutine quicksort


   !> Swap two integer values
   pure subroutine swap(lhs, rhs)
      integer, intent(inout) :: lhs
      integer, intent(inout) :: rhs

      integer :: tmp

      tmp = lhs
      lhs = rhs
      rhs = tmp

   end subroutine swap


   !> Default comparison between two TOML keys
   pure function compare_keys_less(lhs, rhs) result(less)
      type(toml_key), intent (in) :: lhs
      type(toml_key), intent (in) :: rhs
      logical :: less

      less = lhs%key < rhs%key

   end function compare_keys_less


end module tomlf_utils_sort
 
 
!>>>>> ././src/fdoc_generics.f90
module fdoc_generics
!! The overview of a generic interface: which ways there are to call it, and which types and ranks each
!! one takes. Specific procedures with the same arguments make a call form, and each form gets a table
!! with a row for each combination of types and a column for each rank. Types are compared as written,
!! so two names of one kind count as different types. Pages are rendered in parallel, so nothing here
!! calls a function returning a deferred-length string (see `example/slen_race.f90`).
use fdoc_util
use fdoc_buffer
use fdoc_model
use fdoc_urls, only: entity_anchor
implicit none
private

public :: write_call_forms

integer, parameter :: ANY_RANK = -1     !! the rank of an assumed-rank argument

contains

!> Write the call forms of generic `name`, if it has more than one specific procedure. `shown` says
!> whether anything was written.
subroutine write_call_forms(list, name, specifics, b, shown)
    type(entity_list_t), intent(in) :: list !! the entities
    character(len=*), intent(in) :: name    !! the generic
    integer, intent(in) :: specifics(:)     !! its specific procedures
    type(buffer_t), intent(inout) :: b      !! the HTML
    logical, intent(out) :: shown           !! whether anything was written
    type(string_t), allocatable :: keys(:)
    integer, allocatable :: form_of(:)
    logical, allocatable :: usable(:)
    character(len=:), allocatable :: key
    integer :: k, j, forms

    shown = .false.
    allocate (keys(size(specifics)), form_of(size(specifics)), usable(size(specifics)))
    do k = 1, size(specifics)
        usable(k) = allocated(list%box(specifics(k))%e%more%arg_ids)
    end do
    if (count(usable) < 2) return
    shown = .true.
    forms = 0
    form_of = 0
    do k = 1, size(specifics)
        if (.not. usable(k)) cycle
        call form_key(list, specifics(k), key)
        do j = 1, forms
            if (keys(j)%s == key) form_of(k) = j
        end do
        if (form_of(k) == 0) then
            forms = forms + 1
            keys(forms)%s = key
            form_of(k) = forms
        end if
    end do
    call add(b, '<h2 id="call-forms">Call forms</h2>'//achar(10))
    do j = 1, forms
        call write_form(list, name, pack(specifics, form_of == j), b)
    end do
end subroutine write_call_forms

!> What specific procedure `id` has in common with those of its call form.
subroutine form_key(list, id, key)
    type(entity_list_t), intent(in) :: list             !! the entities
    integer, intent(in) :: id                           !! the procedure
    character(len=:), allocatable, intent(out) :: key   !! the key
    type(buffer_t) :: b
    integer :: k

    associate (e => list%box(id)%e)
        call add(b, merge('f', 's', e%kind == E_FUNCTION))
        do k = 1, size(e%more%arg_ids)
            call add(b, ',')
            if (e%more%arg_ids(k) == 0) cycle
            associate (a => list%box(e%more%arg_ids(k))%e)
                call add(b, lowercase(a%name))
                if (a%optional) call add(b, '?')
            end associate
        end do
    end associate
    call take(b, key)
end subroutine form_key

!> Write one call form, whose specific procedures are `ids`.
subroutine write_form(list, name, ids, b)
    type(entity_list_t), intent(in) :: list !! the entities
    character(len=*), intent(in) :: name    !! the generic
    integer, intent(in) :: ids(:)           !! the specific procedures of the form
    type(buffer_t), intent(inout) :: b      !! the HTML
    type(string_t), allocatable :: types(:, :), labels(:, :), result_types(:), result_labels(:), rows(:)
    integer, allocatable :: ranks(:, :), result_ranks(:), row_of(:), columns(:), offset(:)
    logical, allocatable :: in_table(:), varies(:), tied(:)
    character(len=:), allocatable :: key, relative
    logical :: has_result, elemental, new
    integer :: n, m, a, j, r, c, primary, num_rows, column

    n = size(ids)
    m = size(list%box(ids(1))%e%more%arg_ids)
    allocate (types(m, n), labels(m, n), ranks(m, n), result_types(n), result_labels(n), result_ranks(n))
    allocate (rows(n), row_of(n), in_table(m), varies(m), tied(m), offset(m))
    has_result = .true.
    elemental = .true.
    do j = 1, n
        associate (e => list%box(ids(j))%e)
            do a = 1, m
                call describe(list, e%more%arg_ids(a), types(a, j)%s, ranks(a, j))
            end do
            has_result = has_result .and. e%kind == E_FUNCTION .and. e%result > 0
            elemental = elemental .and. is_elemental(e)
        end associate
    end do
    if (has_result) then
        do j = 1, n
            call describe(list, list%box(ids(j))%e%result, result_types(j)%s, result_ranks(j))
        end do
    end if

    ! the first argument of varying rank gives the columns
    primary = 0
    do a = 1, m
        varies(a) = any(ranks(a, :) /= ranks(a, 1))
        if (varies(a) .and. primary == 0) primary = a
    end do
    relative = ''
    if (primary > 0) relative = 'rank('//list%box(list%box(ids(1))%e%more%arg_ids(primary))%e%name//')'
    do a = 1, m
        tied(a) = .false.
        if (primary > 0 .and. a /= primary) tied(a) = all(ranks(a, :) - ranks(primary, :) == ranks(a, 1) - ranks(primary, 1))
        in_table(a) = (varies(a) .and. a /= primary .and. .not. tied(a))
        do j = 2, n
            if (types(a, j)%s /= types(a, 1)%s) in_table(a) = .true.
        end do
    end do
    if (.not. any(in_table) .and. primary > 0) in_table(primary) = .true.
    do a = 1, m
        offset(a) = 0
        if (tied(a)) offset(a) = ranks(a, 1) - ranks(primary, 1)
    end do
    do j = 1, n
        do a = 1, m
            call rank_label(types(a, j)%s, ranks(a, j), a == primary, tied(a), relative, &
                            offset(a), labels(a, j)%s)
        end do
    end do
    if (has_result) then
        call label_results(ranks, primary, relative, result_types, result_ranks, result_labels)
    end if

    ! a row for each combination of types
    num_rows = 0
    do j = 1, n
        key = ''
        do a = 1, m
            if (in_table(a)) key = key//labels(a, j)%s//'|'
        end do
        if (has_result) key = key//result_labels(j)%s
        if (primary == 0) key = key//'|'//trim(int_text(j))
        new = .true.
        do r = 1, num_rows
            if (rows(r)%s /= key) cycle
            row_of(j) = r
            new = .false.
        end do
        if (new) then
            num_rows = num_rows + 1
            rows(num_rows)%s = key
            row_of(j) = num_rows
        end if
    end do

    ! a column for each rank, in order
    allocate (columns(0))
    if (primary > 0) then
        do j = 1, n
            if (.not. any(columns == ranks(primary, j))) call push_int(columns, ranks(primary, j))
        end do
        call sort_ints(columns)
    end if

    call add(b, '<div class="form">'//achar(10)//'<div class="sig">')
    call call_text(list, name, ids(1), has_result, b)
    if (elemental) call add(b, ' <span class="attr attr-elemental">elemental</span>')
    call add(b, '</div>'//achar(10))
    call shared_summary(list, ids, b)
    call add(b, '<table class="forms">'//achar(10)//'<thead><tr>')
    do a = 1, m
        if (.not. in_table(a)) cycle
        call add(b, '<th>')
        call html_escape(list%box(list%box(ids(1))%e%more%arg_ids(a))%e%name, b, .false.)
        call add(b, '</th>')
    end do
    if (primary == 0) call add(b, '<th>Procedure</th>')
    do c = 1, size(columns)
        call add(b, '<th class="rank">')
        call html_escape(relative, b, .false.)
        call add(b, ' = ')
        if (columns(c) == ANY_RANK) then
            call add(b, 'any')
        else
            call add(b, trim(int_text(columns(c))))
        end if
        call add(b, '</th>')
    end do
    if (has_result) call add(b, '<th>Result</th>')
    call add(b, '</tr></thead>'//achar(10)//'<tbody>'//achar(10))
    do r = 1, num_rows
        j = findloc(row_of, r, 1)
        call add(b, '<tr>')
        do a = 1, m
            if (.not. in_table(a)) cycle
            call add(b, '<td class="type">')
            call html_escape(labels(a, j)%s, b, .false.)
            call add(b, '</td>')
        end do
        if (primary == 0) then
            call add(b, '<td class="name">')
            call specific_link(list, ids(j), list%box(ids(j))%e%name, b)
            call add(b, '</td>')
        end if
        do c = 1, size(columns)
            call add(b, '<td class="rank">')
            do column = 1, n
                if (row_of(column) /= r) cycle
                if (ranks(primary, column) == columns(c)) call specific_link(list, ids(column), '&#10003;', b)
            end do
            call add(b, '</td>')
        end do
        if (has_result) then
            call add(b, '<td class="type">')
            call html_escape(result_labels(j)%s, b, .false.)
            call add(b, '</td>')
        end if
        call add(b, '</tr>'//achar(10))
    end do
    call add(b, '</tbody>'//achar(10)//'</table>'//achar(10))

    ! what is the same in every specific procedure of the form
    new = .true.
    do a = 1, m
        if (in_table(a) .or. a == primary) cycle
        if (new) then
            call add(b, '<p class="fixed">')
        else
            call add(b, ', ')
        end if
        new = .false.
        call add(b, '<code>')
        call html_escape(list%box(list%box(ids(1))%e%more%arg_ids(a))%e%name, b, .false.)
        call add(b, '</code> is ')
        call html_escape(labels(a, 1)%s, b, .false.)
    end do
    if (.not. new) call add(b, '</p>'//achar(10))
    call add(b, '</div>'//achar(10))
end subroutine write_form

!> The text and rank of the type of variable `id`. Anything else, such as a dummy procedure, is `procedure`.
subroutine describe(list, id, text, rank)
    type(entity_list_t), intent(in) :: list             !! the entities
    integer, intent(in) :: id                           !! the variable
    character(len=:), allocatable, intent(out) :: text  !! its type
    integer, intent(out) :: rank                        !! its rank
    type(buffer_t) :: b

    rank = 0
    text = 'procedure'
    if (id == 0) return
    associate (e => list%box(id)%e)
        if (e%kind /= E_VARIABLE .or. .not. allocated(e%vartype)) return
        call add(b, e%vartype)
        if (allocated(e%type_kind) .and. allocated(e%strlen)) then
            call add(b, '(len='//e%strlen//', '//e%type_kind//')')
        else if (allocated(e%type_kind)) then
            call add(b, '('//e%type_kind//')')
        else if (allocated(e%strlen)) then
            call add(b, '(len='//e%strlen//')')
        else if (allocated(e%proto)) then
            call add(b, '('//e%proto(1)%s//')')
        end if
        if (allocated(e%dimension)) rank = rank_of(e%dimension)
    end associate
    call take(b, text)
end subroutine describe

!> The rank given by `dimension`, such as `(:,:)`: one more than the commas outside inner parentheses.
pure integer function rank_of(dimension)
    character(len=*), intent(in) :: dimension   !! the dimensions
    integer :: k, depth

    rank_of = 0
    if (len(dimension) < 2) return
    if (dimension(1:1) /= '(') return
    if (index(dimension, '..') > 0) then
        rank_of = ANY_RANK
        return
    end if
    rank_of = 1
    depth = 0
    do k = 1, len(dimension)
        select case (dimension(k:k))
        case ('('); depth = depth + 1
        case (')'); depth = depth - 1
        case (','); if (depth == 1) rank_of = rank_of + 1
        end select
    end do
end function rank_of

!> The text of type `text` with its rank. A rank in `columns` is left out, and a tied one is relative.
subroutine rank_label(text, rank, in_columns, tied, relative, offset, label)
    character(len=*), intent(in) :: text                !! the type
    integer, intent(in) :: rank                         !! the rank
    logical, intent(in) :: in_columns                   !! true if the columns of the table show the rank
    logical, intent(in) :: tied                         !! true if it is a fixed distance from the columns
    character(len=*), intent(in) :: relative            !! the rank of the columns, as text
    integer, intent(in) :: offset                       !! that distance
    character(len=:), allocatable, intent(out) :: label !! the result
    type(buffer_t) :: b

    call add(b, text)
    if (rank == ANY_RANK) then
        call add(b, ', any rank')
    else if (in_columns) then
        continue
    else if (tied) then
        call add(b, ', '//relative)
        if (offset > 0) call add(b, ' + '//trim(int_text(offset)))
        if (offset < 0) call add(b, ' - '//trim(int_text(-offset)))
    else if (rank > 0) then
        call add(b, ', rank '//trim(int_text(rank)))
    end if
    call take(b, label)
end subroutine rank_label

!> The text of each result.
subroutine label_results(ranks, primary, relative, types, result_ranks, labels)
    integer, intent(in) :: ranks(:, :)                  !! the rank of each argument of each procedure
    integer, intent(in) :: primary                      !! the argument of the columns, or 0
    character(len=*), intent(in) :: relative            !! its rank, as text
    type(string_t), intent(in) :: types(:)              !! the type of each result
    integer, intent(in) :: result_ranks(:)              !! the rank of each result
    type(string_t), intent(inout) :: labels(:)          !! the text of each result
    logical :: tied
    integer :: j, offset

    tied = .false.
    offset = 0
    if (primary > 0) then
        offset = result_ranks(1) - ranks(primary, 1)
        tied = all(result_ranks - ranks(primary, :) == offset) .and. any(result_ranks /= result_ranks(1))
    end if
    do j = 1, size(types)
        call rank_label(types(j)%s, result_ranks(j), .false., tied, relative, offset, labels(j)%s)
    end do
end subroutine label_results

!> True if procedure `e` is elemental.
pure logical function is_elemental(e)
    type(entity_t), intent(in) :: e !! the procedure
    integer :: k

    is_elemental = .false.
    if (.not. allocated(e%attribs)) return
    do k = 1, size(e%attribs)
        if (lowercase(e%attribs(k)%s) == 'elemental') is_elemental = .true.
    end do
end function is_elemental

!> Write the summary of the procedures `ids`, if they all have the same one.
subroutine shared_summary(list, ids, b)
    type(entity_list_t), intent(in) :: list !! the entities
    integer, intent(in) :: ids(:)           !! the procedures
    type(buffer_t), intent(inout) :: b      !! the HTML
    integer :: j

    do j = 1, size(ids)
        if (.not. allocated(list%box(ids(j))%e%summary)) return
        if (list%box(ids(j))%e%summary /= list%box(ids(1))%e%summary) return
    end do
    call add(b, list%box(ids(1))%e%summary//achar(10))
end subroutine shared_summary

!> Write how a call of a form looks. Square brackets mark what is optional.
subroutine call_text(list, name, id, has_result, b)
    type(entity_list_t), intent(in) :: list !! the entities
    character(len=*), intent(in) :: name    !! the generic
    integer, intent(in) :: id               !! a procedure of the form
    logical, intent(in) :: has_result       !! true for a function
    type(buffer_t), intent(inout) :: b      !! the HTML
    character(len=:), allocatable :: low, symbol, left, right
    integer :: k, n

    associate (e => list%box(id)%e)
        n = size(e%more%arg_ids)
        low = lowercase(name)
        if (index(low, 'operator(') == 1 .and. n >= 1 .and. n <= 2) then
            symbol = name(10:len(name) - 1)
            call argument_name(list, e%more%arg_ids(1), left)
            call add(b, 'result = ')
            if (n == 1) then
                call html_escape(symbol//' '//left, b, .false.)
            else
                call argument_name(list, e%more%arg_ids(2), right)
                call html_escape(left//' '//symbol//' '//right, b, .false.)
            end if
            return
        end if
        if (index(low, 'assignment(') == 1 .and. n == 2) then
            call argument_name(list, e%more%arg_ids(1), left)
            call argument_name(list, e%more%arg_ids(2), right)
            call html_escape(left//' = '//right, b, .false.)
            return
        end if
        if (has_result) then
            call add(b, 'result = ')
        else
            call add(b, 'call ')
        end if
        call html_escape(name, b, .false.)
        call add(b, '(')
        do k = 1, n
            call argument_name(list, e%more%arg_ids(k), left)
            if (e%more%arg_ids(k) > 0) then
                if (list%box(e%more%arg_ids(k))%e%optional) then
                    if (k > 1) call add(b, ' ')
                    call add(b, '[')
                    if (k > 1) call add(b, ', ')
                    call html_escape(left, b, .false.)
                    call add(b, ']')
                    cycle
                end if
            end if
            if (k > 1) call add(b, ', ')
            call html_escape(left, b, .false.)
        end do
        call add(b, ')')
    end associate
end subroutine call_text

!> The name of argument `id`.
subroutine argument_name(list, id, name)
    type(entity_list_t), intent(in) :: list             !! the entities
    integer, intent(in) :: id                           !! the argument, or 0
    character(len=:), allocatable, intent(out) :: name  !! its name

    name = '*'
    if (id > 0) name = list%box(id)%e%name
end subroutine argument_name

!> Write a link to specific procedure `id`, further down the page.
subroutine specific_link(list, id, text, b)
    type(entity_list_t), intent(in) :: list !! the entities
    integer, intent(in) :: id               !! the procedure
    character(len=*), intent(in) :: text    !! the text, as HTML
    type(buffer_t), intent(inout) :: b      !! the HTML

    call add(b, '<a href="#')
    call entity_anchor(list, id, b)
    call add(b, '" title="')
    call html_escape(list%box(id)%e%name, b, .true.)
    call add(b, '">'//text//'</a>')
end subroutine specific_link

!> Put `list` in order.
pure subroutine sort_ints(list)
    integer, intent(inout) :: list(:)   !! the list
    integer :: k, j, value

    do k = 2, size(list)
        value = list(k)
        j = k - 1
        do while (j >= 1)
            if (list(j) <= value) exit
            list(j + 1) = list(j)
            j = j - 1
        end do
        list(j + 1) = value
    end do
end subroutine sort_ints

end module fdoc_generics
 
 
!>>>>> build/dependencies/fformat/src/ffmt_structure.f90
module ffmt_structure
!! Block structure of a file: the nesting depth of every statement, from a stack of open
!! constructs, plus diagnostics for statements that do not fit (an `end` with nothing to close,
!! an `else` outside an `if`, a construct still open at the end of the file, ...).
use ffmt_tokens
use ffmt_statements
use ffmt_constructs
use ffmt_source, only: source_t
use ffmt_strings, only: to_s
implicit none
private

public :: analyze_structure

type, public :: diagnostic_t
    !! A problem with the block structure, such as an `end` that matches no open construct.
    integer :: line = 0                       !! source line of the statement concerned
    character(len=:), allocatable :: message  !! what is wrong, e.g. `'if is not closed'`
end type diagnostic_t

type, public :: structure_t
    !! The block structure of a source: for each item (see [[ffmt_statements]]) what it is and how
    !! deeply it is nested.
    type(stmt_info_t), allocatable :: info(:)   !! classification of each item (`ROLE_NONE` for non-code)
    integer, allocatable :: depth(:)            !! nesting depth of each item: the constructs around it
    integer, allocatable :: units(:)            !! how many of those are program units (module, submodule
                                                !! or main program)
    integer, allocatable :: procedures(:)       !! how many are procedure definitions (subroutine,
                                                !! function or separate module procedure, but not
                                                !! interface bodies)
    integer, allocatable :: fypp(:)             !! fypp blocks (`#:if`, `#:for`, `#:def`, ...) around each
                                                !! item; a directive line is outside its own block
end type structure_t

type :: scope_t
    !! An open construct on the scope stack.
    integer :: construct = C_NONE   !! one of the `C_*` constants
    integer :: do_label = 0         !! for `do 10 ...`: the label of the statement that ends the loop, else 0
    integer :: line = 0             !! source line of the opening statement
end type scope_t

type :: scope_stack_t
    !! The open constructs, outermost first.
    type(scope_t), allocatable :: s(:)   !! storage; only `s(1:top)` is in use
    integer :: top = 0                   !! number of open constructs
contains
    procedure :: push => stack_push          !! open a construct
    procedure :: restore => stack_restore    !! replace the open constructs by saved ones
    procedure :: snapshot => stack_snapshot  !! the open constructs, to save
end type scope_stack_t

type :: saved_stack_t
    !! Scope stacks for one preprocessor conditional: as it was at the `#if` (restored at each
    !! `#elif` / `#else`) and as it was at the end of the first branch (used after `#endif`).
    type(scope_t), allocatable :: at_if(:)        !! the stack at the `#if`
    type(scope_t), allocatable :: after_first(:)  !! the stack at the end of the first branch; unallocated until then
end type saved_stack_t

! preprocessor conditionals
integer, parameter :: PP_OTHER = 0, PP_IF = 1, PP_ELSE = 2, PP_ENDIF = 3

! fypp block directives
integer, parameter :: FY_OTHER = 0   !! not a block directive (`#:set`, `$:`, cpp, ...)
integer, parameter :: FY_OPEN = 1    !! `#:if`, `#:for`, `#:def`, `#:block`, `#:call`, `#:mute`
integer, parameter :: FY_MIDDLE = 2  !! `#:elif`, `#:else`, `#:nextarg`
integer, parameter :: FY_CLOSE = 3   !! `#:endif`, `#:endfor`, ...

contains

subroutine analyze_structure(source, views, st, diags)
    !! Classify every statement and compute its depth: the number of constructs enclosing it, and
    !! how many of those are program units and procedures, so callers can choose not to indent
    !! their bodies.
    !! An opening statement is at the depth outside its construct, the statements inside are one
    !! deeper, and middle (`else`, `contains`, ...) and closing statements are at the opening depth.
    !! Non-code items get the depth of the code around them.
    !!
    !! Branches of preprocessor conditionals (cpp `#if`/`#ifdef`/`#elif`/`#else`/`#endif` and
    !! fypp `#:if`/`#:elif`/`#:else`/`#:endif`) are treated as alternatives: each branch starts
    !! from the structure at the `#if`, and the structure at the end of the first branch carries
    !! on after the `#endif`. That keeps code such as `#ifdef X` / `do` / `#endif` ... `#ifdef X` /
    !! `end do` / `#endif` balanced.
    type(source_t), intent(in) :: source                          !! the source
    type(statement_view_t), intent(in) :: views(:)                !! the view of each item (see [[statement_views]])
    type(structure_t), intent(out) :: st                          !! the structure
    type(diagnostic_t), allocatable, intent(out) :: diags(:)      !! structure problems found, in the order found

    type(scope_stack_t) :: stack
    type(saved_stack_t), allocatable :: saved(:)
    type(stmt_info_t), allocatable :: info(:)
    integer, allocatable :: depth(:), nunits(:), nprocs(:)
    integer :: k, line, nsaved
    logical :: in_interface

    associate (n => source%stmts%n)
        allocate (info(n), depth(n), nunits(n), nprocs(n), diags(0), saved(0))
    end associate
    nsaved = 0
    do k = 1, source%stmts%n
        depth(k) = stack%top
        if (source%stmts%s(k)%kind == SK_PREPROC) call preprocessor(k)
        if (source%stmts%s(k)%kind /= SK_CODE) then
            call count_units(k)
            cycle
        end if
        line = source%tokens%tok(source%stmts%s(k)%first)%line
        in_interface = .false.
        if (stack%top > 0) in_interface = stack%s(stack%top)%construct == C_INTERFACE
        info(k) = classify_statement(source%text, source%tokens, views(k), in_interface)

        select case (info(k)%role)
        case (ROLE_OPEN)
            call stack%push(scope_t(info(k)%construct, info(k)%do_label, line))
        case (ROLE_MIDDLE)
            if (stack%top == 0 .and. info(k)%construct == C_CONTAINS) then
                ! a main program without a `program` statement
                call stack%push(scope_t(C_PROGRAM, 0, line))
            else if (stack%top == 0) then
                call diagnose(line, construct_label(info(k)%construct)//' statement outside any construct')
            else if (.not. middle_fits(info(k)%construct, stack%s(stack%top)%construct)) then
                call diagnose(line, construct_label(info(k)%construct)//' statement inside '// &
                              trim(opened(stack%s(stack%top))))
            else
                depth(k) = stack%top - 1
            end if
        case (ROLE_CLOSE)
            call close_scope(info(k)%construct, line)
            depth(k) = stack%top
        end select
        call count_units(k)

        ! the labeled statement that ends `do 10 ...` loops is part of the innermost loop body
        if (info(k)%label > 0) then
            do while (stack%top > 0)
                if (stack%s(stack%top)%construct /= C_DO .or. stack%s(stack%top)%do_label /= info(k)%label) exit
                stack%top = stack%top - 1
            end do
        end if
    end do

    do k = stack%top, 1, -1
        call diagnose(stack%s(k)%line, construct_label(stack%s(k)%construct)//' is not closed')
    end do
    call move_alloc(info, st%info)
    call move_alloc(depth, st%depth)
    call move_alloc(nunits, st%units)
    call move_alloc(nprocs, st%procedures)
    st%fypp = fypp_depths(source)

contains

    subroutine count_units(k)
        !! Record how many of the scopes enclosing item `k` are program units, and procedures.
        integer, intent(in) :: k   !! index into `stmts`
        integer :: j
        nunits(k) = 0
        nprocs(k) = 0
        do j = 1, depth(k)
            select case (stack%s(j)%construct)
            case (C_MODULE, C_SUBMODULE, C_PROGRAM)
                nunits(k) = nunits(k) + 1
            case (C_SUBROUTINE, C_FUNCTION, C_PROCEDURE)
                ! interface bodies are declarations, not procedure definitions
                if (j == 1) then
                    nprocs(k) = nprocs(k) + 1
                else if (stack%s(j - 1)%construct /= C_INTERFACE) then
                    nprocs(k) = nprocs(k) + 1
                end if
            end select
        end do
    end subroutine count_units

    subroutine preprocessor(k)
        !! Save or restore the scope stack at the preprocessor conditionals in item `k`, and set
        !! the depth of the item to that of the restored stack.
        integer, intent(in) :: k   !! index into `stmts` of a preprocessor item
        integer :: j
        do j = source%stmts%s(k)%first, source%stmts%s(k)%last
            if (source%tokens%tok(j)%kind /= TK_PREPROC) cycle
            select case (conditional_kind(token_lower(source%text, source%tokens%tok(j))))
            case (PP_IF)
                nsaved = nsaved + 1
                if (nsaved > size(saved)) saved = [saved, saved_stack_t()]
                saved(nsaved)%at_if = stack%snapshot()
                if (allocated(saved(nsaved)%after_first)) deallocate (saved(nsaved)%after_first)
            case (PP_ELSE)
                if (nsaved > 0) then
                    if (.not. allocated(saved(nsaved)%after_first)) saved(nsaved)%after_first = stack%snapshot()
                    call stack%restore(saved(nsaved)%at_if)
                    depth(k) = stack%top
                end if
            case (PP_ENDIF)
                if (nsaved > 0) then
                    if (allocated(saved(nsaved)%after_first)) call stack%restore(saved(nsaved)%after_first)
                    depth(k) = stack%top
                    nsaved = nsaved - 1
                end if
            end select
        end do
    end subroutine preprocessor

    subroutine close_scope(construct, line)
        !! Pop the construct closed by an `end` statement, with a diagnostic if it does not match
        !! the innermost open construct. If an outer one matches, everything down to it is closed.
        integer, intent(in) :: construct   !! construct named by the `end` (`C_ANY` for a bare `end`)
        integer, intent(in) :: line        !! source line of the `end` statement
        integer :: j

        if (stack%top == 0) then
            ! `end` or `end program` may close a main program without a `program` statement
            if (construct /= C_ANY .and. construct /= C_PROGRAM) &
                call diagnose(line, 'end '//construct_label(construct)//' without an open construct')
            return
        end if
        if (closes(construct, stack%s(stack%top)%construct)) then
            stack%top = stack%top - 1
            return
        end if
        ! recover from a missing `end`: close down to a matching construct if there is one
        do j = stack%top - 1, 1, -1
            if (closes(construct, stack%s(j)%construct)) then
                call diagnose(line, 'end '//construct_label(construct)//' closes '// &
                              trim(opened(stack%s(stack%top))))
                stack%top = j - 1
                return
            end if
        end do
        call diagnose(line, 'end '//construct_label(construct)//' does not match '// &
                      trim(opened(stack%s(stack%top))))
    end subroutine close_scope

    function opened(sc) result(text)
        !! `sc` for messages: `do (opened on line 12)`.
        type(scope_t), intent(in) :: sc   !! an open construct
        character(len=64) :: text
        text = construct_label(sc%construct)//' (opened on line '//to_s(sc%line)//')'
    end function opened

    subroutine diagnose(line, message)
        !! Add a diagnostic to `diags`.
        integer, intent(in) :: line             !! source line
        character(len=*), intent(in) :: message !! text of the warning
        diags = [diags, diagnostic_t(line, message)]
    end subroutine diagnose

end subroutine analyze_structure

pure subroutine stack_push(self, sc)
    !! Open construct `sc`, growing the storage as needed.
    class(scope_stack_t), intent(inout) :: self  !! the stack
    type(scope_t), intent(in) :: sc               !! the construct to open
    type(scope_t), allocatable :: tmp(:)
    if (.not. allocated(self%s)) allocate (self%s(16))
    if (self%top == size(self%s)) then
        allocate (tmp(2*self%top))
        tmp(1:self%top) = self%s(1:self%top)
        call move_alloc(tmp, self%s)
    end if
    self%top = self%top + 1
    self%s(self%top) = sc
end subroutine stack_push

pure subroutine stack_restore(self, scopes)
    !! Replace the open constructs by `scopes` (outermost first).
    class(scope_stack_t), intent(inout) :: self  !! the stack
    type(scope_t), intent(in) :: scopes(:)        !! a saved stack (see [[stack_snapshot]])
    integer :: j
    self%top = 0
    do j = 1, size(scopes)
        call self%push(scopes(j))
    end do
end subroutine stack_restore

pure function stack_snapshot(self) result(scopes)
    !! The open constructs, outermost first.
    class(scope_stack_t), intent(in) :: self  !! the stack
    type(scope_t), allocatable :: scopes(:)
    if (allocated(self%s)) then
        scopes = self%s(1:self%top)
    else
        allocate (scopes(0))
    end if
end function stack_snapshot

function fypp_depths(source) result(fypp)
    !! The number of fypp blocks around each item of `source`. The directives are counted wherever
    !! they are, also inside a continued statement; a directive line itself is at the level outside
    !! its block, like `else` and `end` statements.
    type(source_t), intent(in) :: source   !! the source
    integer, allocatable :: fypp(:)
    integer :: k, j, d

    allocate (fypp(source%stmts%n))
    d = 0
    do k = 1, source%stmts%n
        fypp(k) = d
        do j = source%stmts%s(k)%first, source%stmts%s(k)%last
            if (source%tokens%tok(j)%kind /= TK_PREPROC) cycle
            select case (fypp_kind(token_lower(source%text, source%tokens%tok(j))))
            case (FY_OPEN)
                d = d + 1
            case (FY_MIDDLE)
                if (source%stmts%s(k)%kind == SK_PREPROC) fypp(k) = max(0, d - 1)
            case (FY_CLOSE)
                d = max(0, d - 1)
                if (source%stmts%s(k)%kind == SK_PREPROC) fypp(k) = d
            end select
        end do
    end do
end function fypp_depths

pure integer function fypp_kind(text) result(kind)
    !! Kind of a preprocessor line (lowercase text) as a fypp block directive: one of the FY_*
    !! constants.
    character(len=*), intent(in) :: text   !! text of the preprocessor token, in lowercase
    integer :: i, j

    kind = FY_OTHER
    if (len(text) < 3) return
    if (text(1:2) /= '#:') return
    i = 3
    do while (i <= len(text))
        if (text(i:i) /= ' ' .and. text(i:i) /= achar(9)) exit
        i = i + 1
    end do
    j = i
    do while (j <= len(text))
        if (text(j:j) < 'a' .or. text(j:j) > 'z') exit
        j = j + 1
    end do
    select case (text(i:j - 1))
    case ('if', 'for', 'def', 'block', 'call', 'mute')
        kind = FY_OPEN
    case ('elif', 'else', 'nextarg')
        kind = FY_MIDDLE
    case ('endif', 'endfor', 'enddef', 'endblock', 'endcall', 'endmute')
        kind = FY_CLOSE
    end select
end function fypp_kind

pure integer function conditional_kind(text) result(kind)
    !! Kind of a preprocessor line (lowercase text): `PP_IF`, `PP_ELSE` (`#elif`, `#else`), `PP_ENDIF`
    !! or `PP_OTHER`.
    character(len=*), intent(in) :: text   !! text of the preprocessor token, in lowercase
    character(len=:), allocatable :: directive
    integer :: i, j

    kind = PP_OTHER
    i = 2                                   ! after '#'
    if (len(text) < 2 .or. text(1:1) /= '#') return
    if (text(2:2) == ':') i = 3             ! fypp
    do while (i <= len(text))
        if (text(i:i) /= ' ' .and. text(i:i) /= achar(9)) exit
        i = i + 1
    end do
    j = i
    do while (j <= len(text))
        if (text(j:j) < 'a' .or. text(j:j) > 'z') exit
        j = j + 1
    end do
    directive = text(i:j - 1)
    select case (directive)
    case ('if', 'ifdef', 'ifndef')
        kind = PP_IF
    case ('elif', 'else')
        kind = PP_ELSE
    case ('endif')
        kind = PP_ENDIF
    end select
end function conditional_kind

pure logical function closes(closing, open)
    !! True if an `end` of kind `closing` ends the open construct `open`.
    integer, intent(in) :: closing   !! construct named by the `end` (`C_ANY` for a bare `end`)
    integer, intent(in) :: open      !! construct that is open
    closes = closing == open .or. closing == C_ANY
    ! `end function` / `end subroutine` may close a separate module procedure, and vice versa
    if (closing == C_PROCEDURE) closes = closes .or. open == C_FUNCTION .or. open == C_SUBROUTINE
    if (open == C_PROCEDURE) closes = closes .or. closing == C_FUNCTION .or. closing == C_SUBROUTINE
end function closes

pure logical function middle_fits(middle, open)
    !! True if a middle statement of construct `middle` (`else` of `C_IF`, `contains`, ...) may
    !! appear directly inside the open construct `open`.
    integer, intent(in) :: middle   !! construct of the middle statement
    integer, intent(in) :: open     !! construct that is open
    select case (middle)
    case (C_CONTAINS)
        select case (open)
        case (C_PROGRAM, C_MODULE, C_SUBMODULE, C_SUBROUTINE, C_FUNCTION, C_PROCEDURE, C_TYPE)
            middle_fits = .true.
        case default
            middle_fits = .false.
        end select
    case default
        middle_fits = middle == open
    end select
end function middle_fits

end module ffmt_structure
 
 
