module fdoc_project_file
!! Reading settings from a project file, `fpm.toml` or a TOML string.
!!
!! A project file starts with Markdown metadata, optionally between `---` lines: `key: value` lines,
!! with values continued on lines indented by four or more blanks. Metadata ends at the first blank
!! line, at an end marker, or at a line that fits neither form. The rest of the file is the text of
!! the front page. An `[extra.ford]` table in `fpm.toml` next to the project file replaces its
!! metadata, as in FORD; the text of the project file is then used whole. An `[extra.fdoc]` table does
!! the same and comes first, and can give the front page: its text in `front_page`, or the Markdown
!! file that holds it in `front_page_file`, relative to `fpm.toml`.
use tomlf, only: toml_table, toml_array, toml_keyval, toml_key, toml_value, toml_error, toml_load, toml_loads, &
                 get_value, len
use tomlf_constants, only: toml_type
use ffmt_fs, only: join_path, parent_directory
use ffmt_strings, only: to_s
use fdoc_util
use fdoc_settings, only: settings_t, new_settings, set_option, is_option
use fdoc_progress, only: warn
implicit none
private

public :: parse_metadata, load_project, apply_toml_string, metadata_t

type :: meta_item_t
    !! A metadata key and the values given for it.
    character(len=:), allocatable :: key
    type(string_t), allocatable :: values(:)
end type meta_item_t

type :: metadata_t
    !! The metadata of a project file and what follows it.
    type(meta_item_t), allocatable :: items(:)
    type(string_t), allocatable :: body(:)      !! the lines after the metadata
end type metadata_t

contains

!> Split project file `text` into metadata and body.
subroutine parse_metadata(text, meta)
    character(len=*), intent(in) :: text    !! the file
    type(metadata_t), intent(out) :: meta   !! the result
    type(string_t), allocatable :: lines(:)
    character(len=:), allocatable :: key, value
    integer :: n, current

    lines = split_lines(text)
    allocate (meta%items(0))
    n = 1
    if (size(lines) > 0) then
        if (is_marker(lines(1)%s, '-')) n = 2
    end if
    current = 0
    do while (n <= size(lines))
        associate (line => lines(n)%s)
            if (strip(line) == '' .or. is_marker(line, '-') .or. is_marker(line, '.')) then
                n = n + 1
                exit
            end if
            if (match_key(line, key, value)) then
                call add_value(meta, key, value, current)
            else if (current > 0 .and. leading_blanks(line) >= 4) then
                call push(meta%items(current)%values, strip(line))
            else
                exit
            end if
        end associate
        n = n + 1
    end do
    meta%body = lines(n:)
end subroutine parse_metadata

!> Add a value for `key`, whose position in `meta%items` is returned in `current`.
subroutine add_value(meta, key, value, current)
    type(metadata_t), intent(inout) :: meta !! the metadata
    character(len=*), intent(in) :: key     !! the key
    character(len=*), intent(in) :: value   !! the value
    integer, intent(out) :: current         !! the item for `key`
    type(meta_item_t), allocatable :: items(:)
    integer :: k

    do k = 1, size(meta%items)
        if (meta%items(k)%key == key) then
            current = k
            call push(meta%items(k)%values, value)
            return
        end if
    end do
    allocate (items(size(meta%items) + 1))
    do k = 1, size(meta%items)
        call move_alloc(meta%items(k)%key, items(k)%key)
        call move_alloc(meta%items(k)%values, items(k)%values)
    end do
    current = size(items)
    items(current)%key = key
    call push(items(current)%values, value)
    call move_alloc(items, meta%items)
end subroutine add_value

!> Number of blanks at the start of `line`.
pure integer function leading_blanks(line)
    character(len=*), intent(in) :: line    !! the line
    leading_blanks = verify(line, ' ') - 1
    if (leading_blanks < 0) leading_blanks = len(line)
end function leading_blanks

!> True if `line` is three of `c`, alone or followed by whitespace and anything else.
pure logical function is_marker(line, c)
    character(len=*), intent(in) :: line    !! the line
    character, intent(in) :: c              !! the marker character
    is_marker = len(line) >= 3
    if (.not. is_marker) return
    is_marker = line(1:3) == c//c//c
    if (is_marker .and. len(line) > 3) is_marker = line(4:4) == ' ' .or. line(4:4) == achar(9)
end function is_marker

!> True if `line` is `key: value`, indented by at most three blanks.
logical function match_key(line, key, value)
    character(len=*), intent(in) :: line                !! the line
    character(len=:), allocatable, intent(out) :: key   !! the key, in lowercase
    character(len=:), allocatable, intent(out) :: value !! the value
    character(len=*), parameter :: KEY_CHARS = &
                                   'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-'
    integer :: a, b

    match_key = .false.
    a = leading_blanks(line) + 1
    if (a > 4 .or. a > len(line)) return
    b = verify(line(a:), KEY_CHARS)
    if (b <= 1) return
    b = a + b - 1
    if (line(b:b) /= ':') return
    key = lowercase(line(a:b - 1))
    value = strip(line(b + 1:))
    match_key = .true.
end function match_key

!> Read the settings and front page text of the project. Settings come from an `[extra.fdoc]` or
!> `[extra.ford]` table in `fpm.toml` if there is one, and otherwise from the metadata of the project
!> file. With no `path` the project file is `ford.md`, if it exists: `[extra.fdoc]` does not need one,
!> as the text of the front page can be in its `front_page`, or the file named by `front_page_file`.
subroutine load_project(path, directory, s, body, stat, errmsg)
    character(len=*), intent(in) :: path                !! the project file, or `''`
    character(len=*), intent(in) :: directory           !! its directory
    type(settings_t), intent(out) :: s                  !! the settings
    character(len=:), allocatable, intent(out) :: body  !! the front page text
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(metadata_t) :: meta
    character(len=:), allocatable :: text, file, front
    logical :: found, exists
    integer :: k

    s = new_settings()
    stat = 0
    file = path
    if (len(file) == 0) then
        inquire (file=join_path(directory, 'ford.md'), exist=exists)
        if (exists) file = join_path(directory, 'ford.md')
    end if
    text = ''
    if (len(file) > 0) then
        call read_whole_file(file, text, stat, errmsg)
        if (stat /= 0) return
    end if
    call load_fpm_settings(join_path(directory, 'fpm.toml'), s, found, front, stat, errmsg)
    if (stat /= 0) return
    if (found) then
        if (allocated(front)) then
            body = front
        else
            body = text
        end if
        return
    end if
    if (len(file) == 0) then
        stat = 1
        errmsg = 'no project file: give one, or add an [extra.fdoc] table to fpm.toml'
        return
    end if
    if (ends_with(file, 'fpm.toml')) then
        stat = 1
        errmsg = file//' has no [extra.fdoc] or [extra.ford] table: give the project file instead'
        return
    end if
    call parse_metadata(text, meta)
    body = join(meta%body, achar(10))
    do k = 1, size(meta%items)
        associate (item => meta%items(k))
            if (.not. is_option(item%key)) then
                call warn("In '"//file//"': Ignoring unknown Ford metadata key '"//item%key//"'")
                cycle
            end if
            call set_option(s, item%key, item%values, stat, errmsg)
            if (stat /= 0) then
                errmsg = "Error parsing settings from '"//file//"': "//errmsg
                return
            end if
        end associate
    end do
end subroutine load_project

!> Read the `[extra.fdoc]` or `[extra.ford]` table of `fpm.toml` file `path`, if there is one.
subroutine load_fpm_settings(path, s, found, front, stat, errmsg)
    character(len=*), intent(in) :: path                !! the file
    type(settings_t), intent(inout) :: s                !! the settings
    logical, intent(out) :: found                       !! true if a table exists
    character(len=:), allocatable, intent(out) :: front !! its `front_page`, if it has one
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(toml_table), allocatable :: top
    type(toml_table), pointer :: extra, table
    type(toml_error), allocatable :: error
    character(len=:), allocatable :: file
    logical :: exists

    stat = 0
    found = .false.
    inquire (file=path, exist=exists)
    if (.not. exists) return
    call toml_load(top, path, error=error)
    if (allocated(error)) then
        stat = 1
        errmsg = path//': '//error%message
        return
    end if
    call get_value(top, 'extra', extra, requested=.false.)
    if (.not. associated(extra)) return
    call get_value(extra, 'fdoc', table, requested=.false.)
    if (.not. associated(table)) call get_value(extra, 'ford', table, requested=.false.)
    if (.not. associated(table)) return
    found = .true.
    call get_value(table, 'front_page', front)
    call get_value(table, 'front_page_file', file)
    if (allocated(file)) then
        call read_whole_file(join_path(parent_directory(path), file), front, stat, errmsg)
        if (stat /= 0) return
    end if
    call apply_table(table, s, stat, errmsg)
end subroutine load_fpm_settings

!> Apply `--config` options: TOML with `;` between lines.
subroutine apply_toml_string(text, s, stat, errmsg)
    character(len=*), intent(in) :: text                !! the options
    type(settings_t), intent(inout) :: s                !! the settings
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(toml_table), allocatable :: top
    type(toml_error), allocatable :: error

    call toml_loads(top, join(split_on(text, ';'), achar(10)), error=error)
    if (allocated(error)) then
        stat = 1
        errmsg = '--config: '//error%message
        return
    end if
    call apply_table(top, s, stat, errmsg)
end subroutine apply_toml_string

!> Apply the keys of TOML `table` as options.
subroutine apply_table(table, s, stat, errmsg)
    type(toml_table), intent(inout) :: table            !! the table
    type(settings_t), intent(inout) :: s                !! the settings
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(toml_key), allocatable :: keys(:)
    class(toml_value), pointer :: v
    type(string_t), allocatable :: values(:)
    character(len=:), allocatable :: key
    integer :: k

    stat = 0
    call table%get_keys(keys)
    do k = 1, size(keys)
        key = keys(k)%key
        if (key == 'front_page' .or. key == 'front_page_file') cycle
        if (.not. is_option(key)) then
            call warn("Ignoring unknown Ford option '"//key//"'")
            cycle
        end if
        call table%get(key, v)
        allocate (values(0))
        select type (v)
        type is (toml_keyval)
            call push(values, scalar_text(table, key, v%get_type()))
        type is (toml_array)
            call array_values(v, values, stat, errmsg)
        type is (toml_table)
            call map_values(v, merge(':', '=', key == 'extra_mods'), values)
        class default
            stat = 1
            errmsg = "unexpected value for option '"//key//"'"
        end select
        if (stat == 0) call set_option(s, key, values, stat, errmsg)
        deallocate (values)
        if (stat /= 0) return
    end do
end subroutine apply_table

!> A string, integer or logical value of `table` as text.
function scalar_text(table, key, kind) result(text)
    type(toml_table), intent(inout) :: table    !! the table
    character(len=*), intent(in) :: key         !! the key
    integer, intent(in) :: kind                 !! the value's `toml_type`
    character(len=:), allocatable :: text
    integer :: i
    logical :: flag

    text = ''
    if (kind == toml_type%string) then
        call get_value(table, key, text)
    else if (kind == toml_type%int) then
        call get_value(table, key, i)
        text = to_s(i)
    else if (kind == toml_type%boolean) then
        call get_value(table, key, flag)
        text = trim(merge('true ', 'false', flag))
    end if
end function scalar_text

!> The items of a TOML array as text. An array of tables is taken to be `extra_filetypes`.
subroutine array_values(array, values, stat, errmsg)
    type(toml_array), intent(inout) :: array            !! the array
    type(string_t), allocatable, intent(inout) :: values(:)   !! the items
    integer, intent(inout) :: stat                      !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(toml_table), pointer :: item
    character(len=:), allocatable :: text, part
    integer :: k, ios

    do k = 1, len(array)
        call get_value(array, k, text, stat=ios)
        if (ios == 0 .and. allocated(text)) then
            call push(values, text)
            cycle
        end if
        call get_value(array, k, item, stat=ios)
        if (ios /= 0 .or. .not. associated(item)) then
            stat = 1
            errmsg = 'expected strings or tables in an array'
            return
        end if
        text = ''
        call get_value(item, 'extension', part, '')
        text = part
        call get_value(item, 'comment', part, '')
        text = text//' '//part
        call get_value(item, 'lexer', part, '')
        if (part /= '') text = text//' '//part
        call push(values, text)
    end do
end subroutine array_values

!> The string entries of `table` in the form `key<sep>value`.
subroutine map_values(table, sep, values)
    type(toml_table), intent(inout) :: table    !! the table
    character, intent(in) :: sep                !! the separator
    type(string_t), allocatable, intent(inout) :: values(:) !! the entries
    type(toml_key), allocatable :: keys(:)
    character(len=:), allocatable :: text
    integer :: k

    call table%get_keys(keys)
    do k = 1, size(keys)
        call get_value(table, keys(k)%key, text, '')
        call push(values, keys(k)%key//sep//text)
    end do
end subroutine map_values

end module fdoc_project_file
 
 
!>>>>> ././src/fdoc_parser.f90
module fdoc_parser
!! Turning a source text into entities: fformat finds the statements and their structure, and this
!! module reads the declarations and doc comments.
!!
!! Doc comments are attached to code statements. A statement's documentation is any `predocmark`
!! block before it, then its inline comments, then the `docmark` lines after it.
!!
!! Each file is parsed into a list of its own, in parallel with others, so nothing here calls a
!! function returning a deferred-length string (see `example/slen_race.f90`).
use ffmt_tokens
use ffmt_statements, only: statement_view_t, SK_CODE, SK_COMMENT, SK_BLANK
use ffmt_source, only: source_t, parse_source, set_views
use ffmt_structure, only: analyze_structure, structure_t, diagnostic_t
use ffmt_constructs
use fdoc_util
use fdoc_model
use fdoc_settings, only: settings_t
use fdoc_project_file, only: parse_metadata, metadata_t
use fdoc_decl
use fdoc_intrinsics, only: is_intrinsic
implicit none
private

public :: parse_file

integer, parameter :: MAX_DEPTH = 256

character(len=*), parameter :: ATTRIBUTE_WORDS(*) = [character(len=12) :: 'asynchronous', 'allocatable', 'data', 'dimension', &
                                                     'external', 'optional', 'parameter', 'pointer', 'private', 'protected', &
                                                     'public', 'save', 'target', 'value', 'volatile']
character(len=*), parameter :: META_KEYS = &
    ' author category copy_subdir date deprecated display graph graph_maxdepth graph_maxnodes license num_lines '// &
    'ordered_subpage proc_internals since source summary title version '

type :: association_t
    !! A name given by an `associate` statement.
    character(len=:), allocatable :: name       !! the name, in lowercase
    character(len=:), allocatable :: chain      !! what it stands for, `%`-separated
    integer :: level = 0                        !! how many `associate` constructs are open
end type association_t

type :: doc_lines_t
    !! Documentation lines of one item.
    type(string_t), allocatable :: lines(:) !! the lines, without the comment marker
end type doc_lines_t

contains

!> Length of the result of [[inherited_permission]].
pure integer function permission_length(list, id)
    type(entity_list_t), intent(in) :: list !! the entities
    integer, intent(in) :: id               !! the entity
    permission_length = 6
    if (allocated(list%box(id)%e%child_permission)) permission_length = len(list%box(id)%e%child_permission)
end function permission_length

!> Length of the first blank-separated word of `text`.
pure integer function word_length(text)
    character(len=*), intent(in) :: text    !! the text
    integer :: a, b
    a = verify(text//'x', ' ')
    b = index(text(min(a, len(text) + 1):)//' ', ' ')
    word_length = b - 1
end function word_length

!> Number of commas in `text`.
pure integer function comma_count(text)
    character(len=*), intent(in) :: text    !! the text
    integer :: k
    comma_count = 0
    do k = 1, len(text)
        if (text(k:k) == ',') comma_count = comma_count + 1
    end do
end function comma_count

!> Parse source `text` of file `path` into `list`, whose first entity is the file.
subroutine parse_file(path, text, s, list)
    character(len=*), intent(in) :: path        !! the file
    character(len=*), intent(in) :: text        !! the text to parse
    type(settings_t), intent(in) :: s           !! the settings
    type(entity_list_t), intent(out) :: list    !! the entities
    type(source_t) :: src
    type(statement_view_t), allocatable :: views(:)
    type(structure_t) :: st
    type(diagnostic_t), allocatable :: diags(:)
    type(doc_lines_t), allocatable :: docs(:)
    type(string_t), allocatable :: file_doc(:)
    type(association_t), allocatable :: associations(:)
    character(len=:), allocatable :: line
    integer :: stack(0:MAX_DEPTH)
    integer :: top, k, root, current, id, depth, caller, level

    call parse_source(text, src)
    call set_views(src, views)
    call analyze_structure(src, views, st, diags)
    call collect_docs(src, s, docs, file_doc)

    root = list%add(E_FILE, 0)
    list%box(root)%e%name = path
    list%box(root)%e%file = root
    call set_doc(list%box(root)%e, s, file_doc)
    call inherit_display(list, root, s)
    stack(0) = root
    top = 0
    level = 0
    allocate (associations(0))

    do k = 1, src%stmts%n
        if (src%stmts%s(k)%kind /= SK_CODE) cycle
        associate (info => st%info(k))
            ! fformat knows the structure, including what a statement label closes: close what it
            ! says is closed here. A middle statement such as `contains` is at its construct's depth.
            depth = st%depth(k)
            if (info%role == ROLE_MIDDLE) depth = depth + 1
            do while (top > depth)
                if (stack(top) > 0) call close_unit(list, stack(top), s)
                top = top - 1
            end do
            current = stack(top)
            caller = nearest_caller(list, stack, top)
            if (caller > 0) call statement_calls(views(k), info, list%box(caller)%e, associations, level)
            select case (info%role)
            case (ROLE_OPEN)
                id = 0
                if (current > 0) then
                    call statement_text(src, k, line)
                    call open_unit(list, current, info%construct, line, k, src, docs(k), s, id)
                end if
                if (top < MAX_DEPTH) then
                    top = top + 1
                    stack(top) = id
                end if
            case (ROLE_MIDDLE)
                if (current > 0 .and. info%construct == C_CONTAINS) then
                    list%box(current)%e%in_contains = .true.
                    if (list%box(current)%e%kind == E_TYPE) list%box(current)%e%child_permission = 'public'
                end if
            case (ROLE_CLOSE)
                continue
            case default
                if (current > 0) then
                    call statement_text(src, k, line)
                    call parse_statement(list, current, line, docs(k), s)
                end if
            end select
        end associate
    end do
    do while (top > 0)
        if (stack(top) > 0) call close_unit(list, stack(top), s)
        top = top - 1
    end do
end subroutine parse_file

!> The innermost entity on `stack` that can call procedures, or 0 if there is none or a declaration
!> scope such as a type is inside it.
pure integer function nearest_caller(list, stack, top) result(caller)
    type(entity_list_t), intent(in) :: list !! the entities
    integer, intent(in) :: top              !! the top of the stack
    integer, intent(in) :: stack(0:top)     !! the open constructs
    integer :: k

    caller = 0
    do k = top, 0, -1
        if (stack(k) == 0) cycle
        select case (list%box(stack(k))%e%kind)
        case (E_SUBROUTINE, E_FUNCTION, E_MODPROC, E_PROGRAM)
            caller = stack(k)
        end select
        return
    end do
end function nearest_caller

!> True if statement `v` can have procedure references: not a declaration.
logical function is_executable(v, info, source_low)
    type(statement_view_t), intent(in) :: v     !! the statement
    type(stmt_info_t), intent(in) :: info       !! its classification
    character(len=*), intent(in) :: source_low  !! its first words, in lowercase

    is_executable = .false.
    select case (info%role)
    case (ROLE_CLOSE)
        return
    case (ROLE_OPEN)
        select case (info%construct)
        case (C_IF, C_DO, C_SELECT, C_ASSOCIATE, C_WHERE, C_FORALL)
            is_executable = .true.
        end select
        return
    case (ROLE_MIDDLE)
        is_executable = info%construct /= C_CONTAINS
        return
    end select
    if (v%n == 0) return
    if (is_type_declaration(source_low) .or. is_attribute_statement(source_low)) return
    if (starts_word(source_low, 'use') .or. starts_word(source_low, 'implicit') .or. &
        starts_word(source_low, 'import') .or. starts_word(source_low, 'namelist') .or. &
        starts_word(source_low, 'common') .or. starts_word(source_low, 'format') .or. &
        starts_word(source_low, 'equivalence') .or. starts_word(source_low, 'module')) return
    if (starts_word(source_low, 'goto') .or. starts_word(source_low, 'go')) then
        is_executable = index(source_low, '(') == 0
        return
    end if
    is_executable = .true.
end function is_executable

!> The first code tokens of `v` from token `j`, in lowercase and joined by blanks, up to about 80
!> characters.
pure function leading_text(v, j) result(text)
    type(statement_view_t), intent(in) :: v     !! the statement
    integer, intent(in) :: j                    !! the first token
    character(len=80) :: text
    integer :: k, n, w

    text = ''
    n = 0
    do k = j, v%n
        w = v%hi(k) - v%lo(k) + 1
        if (n + w >= len(text)) exit
        text(n + 1:n + w) = v%low(v%lo(k):v%hi(k))
        n = n + w + merge(1, 0, v%kind_of(k) == TK_NAME .and. v%kind_of(k + 1) == TK_NAME)
    end do
end function leading_text

!> Add the procedures that a statement refers to to `e%more%calls`.
subroutine statement_calls(v, info, e, associations, level)
    type(statement_view_t), intent(in) :: v             !! the statement's tokens
    type(stmt_info_t), intent(in) :: info               !! its classification
    type(entity_t), intent(inout) :: e                  !! the entity it is in
    type(association_t), allocatable, intent(inout) :: associations(:)  !! the names in scope
    integer, intent(inout) :: level                     !! how many `associate` constructs are open
    character(len=80) :: first
    integer :: j, call_at, last, target

    if (info%role == ROLE_CLOSE .and. info%construct == C_ASSOCIATE) then
        associations = pack(associations, associations%level /= level)
        level = max(0, level - 1)
        return
    end if
    if (v%n == 0) return
    first = leading_text(v, v%first)
    if (.not. is_executable(v, info, trim(first))) return

    ! a computed `go to` looks like a function reference
    do j = v%first, v%n - 1
        if (v%is(j + 1, '(') .and. (v%is(j, 'goto') .or. (v%is(j, 'to') .and. v%is(j - 1, 'go')))) return
    end do

    ! `call` may follow a logical `if`
    call_at = 0
    do j = v%first, v%n
        if (v%depth(j) == 0 .and. v%is(j, 'call')) then
            if (j == v%first .or. v%is(j - 1, ')')) then
                call_at = j
                exit
            end if
        end if
    end do
    target = 0
    if (call_at > 0) then
        last = call_at + 1
        target = chain_end(v, last)
        if (target > 0) call add_call(v, target, e, associations)
    end if

    do j = v%first, v%n - 1
        if (v%kind_of(j) /= TK_NAME .or. .not. v%is(j + 1, '(')) cycle
        if (call_at > 0 .and. j > call_at .and. v%depth(j) == 0) cycle
        if (v%closing(j + 1) > 0) then
            if (v%is(v%closing(j + 1) + 1, '%')) cycle
        end if
        call add_call(v, j, e, associations)
    end do

    if (info%role == ROLE_OPEN .and. info%construct == C_ASSOCIATE) call read_associations(v, associations, level)
end subroutine statement_calls

!> The last name of the component chain starting at token `j`, or 0.
function chain_end(v, j) result(last)
    type(statement_view_t), intent(in) :: v     !! the statement
    integer, intent(in) :: j                    !! the first name
    integer :: last, k

    last = 0
    k = j
    do
        if (v%kind_of(k) /= TK_NAME) return
        last = k
        k = k + 1
        if (v%is(k, '(')) then
            if (v%closing(k) == 0) return
            k = v%closing(k) + 1
        end if
        if (.not. v%is(k, '%')) return
        k = k + 1
    end do
end function chain_end

!> The first token of the component chain ending at name `j`.
function chain_start(v, j) result(first)
    type(statement_view_t), intent(in) :: v     !! the statement
    integer, intent(in) :: j                    !! the last name
    integer :: first, k, depth

    first = j
    do
        if (.not. v%is(first - 1, '%')) return
        k = first - 2
        if (v%is(k, ')')) then
            depth = 0
            do while (k >= 1)
                if (v%is(k, ')')) depth = depth + 1
                if (v%is(k, '(')) depth = depth - 1
                if (depth == 0) exit
                k = k - 1
            end do
            k = k - 1
        end if
        if (k < 1) return
        if (v%kind_of(k) /= TK_NAME) return
        first = k
    end do
end function chain_start

!> Add the reference ending at name `j` to `e%more%calls`, unless it is intrinsic or already there.
subroutine add_call(v, j, e, associations)
    type(statement_view_t), intent(in) :: v     !! the statement
    integer, intent(in) :: j                    !! the last name
    type(entity_t), intent(inout) :: e          !! the entity it is in
    type(association_t), intent(in) :: associations(:)  !! the names in scope
    character(len=:), allocatable :: chain
    integer :: k, depth, a, first
    logical :: start

    if (is_intrinsic(v%low(v%lo(j):v%hi(j)))) return
    if (.not. allocated(e%more%calls)) allocate (e%more%calls(0))
    do k = 1, size(e%more%calls)
        if (ends_with(e%more%calls(k)%s, v%low(v%lo(j):v%hi(j)))) then
            if (e%more%calls(k)%s == v%low(v%lo(j):v%hi(j))) return
            a = len(e%more%calls(k)%s) - (v%hi(j) - v%lo(j) + 1)
            if (e%more%calls(k)%s(a:a) == '%') return
        end if
    end do

    first = chain_start(v, j)
    chain = ''
    start = .true.
    depth = v%depth(first)
    do k = first, j
        if (v%depth(k) /= depth .or. v%kind_of(k) /= TK_NAME) cycle
        if (start) then
            start = .false.
            chain = v%low(v%lo(k):v%hi(k))
            do a = size(associations), 1, -1
                if (associations(a)%name == chain) then
                    chain = associations(a)%chain
                    exit
                end if
            end do
        else
            chain = chain//'%'//v%low(v%lo(k):v%hi(k))
        end if
    end do
    call push(e%more%calls, chain)
end subroutine add_call

!> Add the names of an `associate` statement to `associations`.
subroutine read_associations(v, associations, level)
    type(statement_view_t), intent(in) :: v     !! the statement
    type(association_t), allocatable, intent(inout) :: associations(:)  !! the names in scope
    integer, intent(inout) :: level             !! how many `associate` constructs are open
    character(len=:), allocatable :: chain
    integer :: j, k, depth, stop_at, head

    level = level + 1
    do j = v%first, v%n - 1
        if (.not. v%is(j + 1, '=>')) cycle
        if (v%kind_of(j) /= TK_NAME) cycle
        depth = v%depth(j)
        stop_at = j + 2
        do while (stop_at < v%n)
            if (v%depth(stop_at + 1) < depth .or. (v%depth(stop_at + 1) == depth .and. v%is(stop_at + 1, ','))) exit
            stop_at = stop_at + 1
        end do
        chain = ''
        do k = j + 2, stop_at
            if (v%depth(k) /= depth) cycle
            if (v%kind_of(k) == TK_NAME) then
                if (len(chain) > 0) chain = chain//'%'
                chain = chain//v%low(v%lo(k):v%hi(k))
            else if (.not. v%is(k, '%') .and. .not. v%is(k, '(') .and. .not. v%is(k, ')')) then
                chain = ''
                exit
            end if
        end do
        if (len(chain) == 0) cycle
        ! what it stands for may itself be an associated name
        head = index(chain//'%', '%') - 1
        do k = size(associations), 1, -1
            if (associations(k)%name == chain(:head)) then
                chain = associations(k)%chain//chain(head + 1:)
                exit
            end if
        end do
        associations = [associations, association_t(v%low(v%lo(j):v%hi(j)), chain, level)]
    end do
end subroutine read_associations

!> The code of statement `item`: its tokens as written, without comments and continuation marks.
!> Continuation lines are joined as FORD joins them.
subroutine statement_text(src, item, text)
    type(source_t), intent(in) :: src                   !! the source
    integer, intent(in) :: item                         !! the statement
    character(len=:), allocatable, intent(out) :: text  !! its code
    character(len=:), allocatable :: buffer
    logical :: after_break, pending_blank
    integer :: t, first, last, n, width

    first = src%stmts%s(item)%first
    last = src%stmts%s(item)%last
    allocate (character(len=src%tokens%tok(last)%last - src%tokens%tok(first)%first + 2) :: buffer)
    n = 0
    after_break = .false.
    pending_blank = .false.
    do t = first, last
        associate (tok => src%tokens%tok(t))
            select case (tok%kind)
            case (TK_NEWLINE)
                after_break = .true.
            case (TK_COMMENT, TK_PREPROC)
                cycle
            case (TK_CONT)
                if (tok%sub == CT_LEADING) then
                    after_break = .false.
                    pending_blank = .false.
                end if
            case (TK_SPACE)
                if (.not. after_break) pending_blank = .true.
            case default
                if (after_break) pending_blank = .true.
                after_break = .false.
                if (tok%kind == TK_OP .and. src%text(tok%first:tok%last) == ';') cycle
                if (pending_blank .and. n > 0) then
                    n = n + 1
                    buffer(n:n) = ' '
                end if
                pending_blank = .false.
                width = tok%last - tok%first + 1
                buffer(n + 1:n + width) = src%text(tok%first:tok%last)
                n = n + width
            end select
        end associate
    end do
    text = buffer(1:n)
end subroutine statement_text

!> Find the documentation of each code statement.
subroutine collect_docs(src, s, docs, file_doc)
    type(source_t), intent(in) :: src                       !! the source
    type(settings_t), intent(in) :: s                       !! the settings
    type(doc_lines_t), allocatable, intent(out) :: docs(:)  !! the documentation of each item
    type(string_t), allocatable, intent(out) :: file_doc(:) !! documentation before the first statement
    type(string_t), allocatable :: pending(:)
    logical :: in_predoc, in_predoc_alt, in_alt
    integer :: k, t, last

    allocate (docs(src%stmts%n), pending(0), file_doc(0))
    in_predoc = .false.
    in_predoc_alt = .false.
    in_alt = .false.
    last = 0
    do k = 1, src%stmts%n
        associate (item => src%stmts%s(k))
            select case (item%kind)
            case (SK_COMMENT)
                do t = item%first, item%last
                    if (src%tokens%tok(t)%kind == TK_COMMENT) then
                        call comment_line(src%text(src%tokens%tok(t)%first:src%tokens%tok(t)%last))
                    end if
                end do
            case (SK_BLANK)
                in_alt = .false.
                if (last > 0 .and. .not. in_predoc .and. .not. in_predoc_alt .and. size(pending) == 0) then
                    if (allocated(docs(last)%lines)) then
                        if (size(docs(last)%lines) > 0) call push(docs(last)%lines, '')
                    end if
                end if
            case (SK_CODE)
                call move_alloc(pending, docs(k)%lines)
                allocate (pending(0))
                in_predoc = .false.
                in_predoc_alt = .false.
                in_alt = .false.
                last = k
                do t = item%first, item%last
                    if (src%tokens%tok(t)%kind == TK_COMMENT) then
                        call comment_line(src%text(src%tokens%tok(t)%first:src%tokens%tok(t)%last))
                        in_alt = .false.
                    end if
                end do
            end select
        end associate
    end do

contains

    !> Handle one comment.
    subroutine comment_line(c)
        character(len=*), intent(in) :: c   !! the comment, from its `!`

        if (has_mark(c, s%predocmark)) then
            in_predoc = .true.
            in_alt = .false.
            in_predoc_alt = .false.
            call push(pending, strip_trailing(c(2 + len(s%predocmark):)))
        else if (has_mark(c, s%predocmark_alt)) then
            in_predoc_alt = .true.
            in_predoc = .false.
            in_alt = .false.
            call push(pending, strip_trailing(c(2 + len(s%predocmark_alt):)))
        else if (has_mark(c, s%docmark_alt)) then
            in_alt = .true.
            in_predoc = .false.
            in_predoc_alt = .false.
            call add_post(c(2 + len(s%docmark_alt):))
        else if (has_mark(c, s%docmark)) then
            in_alt = .false.
            in_predoc_alt = .false.
            if (in_predoc) then
                call push(pending, strip_trailing(c(2 + len(s%docmark):)))
            else
                call add_post(c(2 + len(s%docmark):))
            end if
        else if (in_predoc_alt) then
            call push(pending, strip_trailing(c(2:)))
        else if (in_alt) then
            call add_post(c(2:))
        end if
    end subroutine comment_line

    !> Add a line to the documentation of the last statement, or of the file before any statement.
    subroutine add_post(line)
        character(len=*), intent(in) :: line    !! the line
        if (last == 0) then
            call push(file_doc, strip_trailing(line))
        else
            if (.not. allocated(docs(last)%lines)) allocate (docs(last)%lines(0))
            call push(docs(last)%lines, strip_trailing(line))
        end if
    end subroutine add_post

end subroutine collect_docs

!> The first blank-separated word of `text`, after any leading blanks.
pure function first_word_of(text) result(word)
    character(len=*), intent(in) :: text    !! the text
    character(len=word_length(text)) :: word
    integer :: a
    a = verify(text//'x', ' ')
    word = text(a:)
end function first_word_of

!> `s` without trailing whitespace.
pure function strip_trailing(s) result(t)
    character(len=*), intent(in) :: s   !! the text
    character(len=len_trim(s)) :: t
    t = s
end function strip_trailing

!> True if comment `c` starts with `!` and doc marker `mark`.
pure logical function has_mark(c, mark)
    character(len=*), intent(in) :: c       !! the comment
    character(len=*), intent(in) :: mark    !! the marker
    has_mark = .false.
    if (len(mark) == 0 .or. len(c) < 1 + len(mark)) return
    has_mark = c(2:1 + len(mark)) == mark
end function has_mark

!> Set the documentation and metadata of `e` from its doc lines.
subroutine set_doc(e, s, lines)
    type(entity_t), intent(inout) :: e      !! the entity
    type(settings_t), intent(in) :: s       !! the settings
    type(string_t), intent(in) :: lines(:)  !! the doc lines
    type(string_t), allocatable :: work(:), moved(:)
    type(metadata_t) :: meta
    integer :: k, at

    allocate (e%meta(0))
    if (size(lines) == 0) then
        allocate (e%doc(0))
        return
    end if
    work = lines
    if (s%doxygen) then
        ! doxygen commands such as `@brief text` are metadata, wherever they are
        allocate (moved(0))
        do k = 1, size(work)
            call doxygen_meta(work(k)%s, moved)
        end do
        work = [moved, work]
    end if
    if (size(work) == 1) then
        at = index(work(1)%s, ':')
        if (at > 0) then
            if (index(META_KEYS, ' '//lowercase(strip(work(1)%s(:at - 1)))//' ') == 0) work = [string_t(''), work]
        end if
    end if
    call parse_metadata(join(work, achar(10)), meta)
    call move_alloc(meta%body, e%doc)
    deallocate (e%meta)
    allocate (e%meta(size(meta%items)))
    do k = 1, size(meta%items)
        e%meta(k)%key = meta%items(k)%key
        e%meta(k)%values = meta%items(k)%values
    end do
end subroutine set_doc

!> If `line` is a doxygen command, blank it and add it to `moved` as a metadata line.
subroutine doxygen_meta(line, moved)
    character(len=:), allocatable, intent(inout) :: line    !! the doc line
    type(string_t), allocatable, intent(inout) :: moved(:)  !! the metadata lines
    character(len=len(line)) :: text
    integer :: at, stop_at

    if (len(line) == 0) return
    text = adjustl(line)
    if (text(1:1) /= '@') return
    stop_at = index(trim(text), ' ')
    if (stop_at < 3) return
    at = len_trim(text(:stop_at))
    select case (text(2:at))
    case ('see')
        line = '[['//strip(first_word_of(text(stop_at:)))//']]'//text(stop_at + len(first_word_of(strip(text(stop_at:)))) + 1:)
        return
    case ('note', 'warning', 'todo', 'bug', 'history')
        return
    case ('brief')
        call push(moved, 'summary: '//strip(text(stop_at:)))
    case default
        call push(moved, text(2:at)//': '//strip(text(stop_at:)))
    end select
    line = ''
end subroutine doxygen_meta

!> Copy the display settings that apply to `id` from its parent, and apply its own metadata.
subroutine inherit_display(list, id, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the entity
    type(settings_t), intent(in) :: s           !! the settings
    type(string_t), allocatable :: wanted(:)
    logical :: flag, ok
    integer :: k, j

    associate (e => list%box(id)%e)
        if (e%parent > 0) then
            e%display = list%box(e%parent)%e%display
            e%internals = list%box(e%parent)%e%internals
        else
            e%display = s%display
            e%internals = s%proc_internals
        end if
        do k = 1, size(e%meta)
            if (e%meta(k)%key == 'proc_internals') then
                call parse_bool(e%meta(k)%values(1)%s, flag, ok)
                if (ok) e%internals = flag
            else if (e%meta(k)%key == 'display') then
                allocate (wanted(size(e%meta(k)%values)))
                do j = 1, size(wanted)
                    wanted(j)%s = lowercase(e%meta(k)%values(j)%s)
                end do
                if (contains_string(wanted, 'none') .and. e%kind /= E_FILE) then
                    e%display = [string_t ::]
                else if (contains_string(wanted, 'public') .or. contains_string(wanted, 'private') .or. &
                         contains_string(wanted, 'protected')) then
                    call move_alloc(wanted, e%display)
                end if
                if (allocated(wanted)) deallocate (wanted)
            end if
        end do
    end associate
end subroutine inherit_display

!> Create the entity for the statement opening construct `construct`, if it has one.
subroutine open_unit(list, parent, construct, line, item, src, doc, s, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: parent               !! the entity around it
    integer, intent(in) :: construct            !! one of the `C_*` constants
    character(len=*), intent(in) :: line        !! the statement
    integer, intent(in) :: item                 !! the statement's item
    type(source_t), intent(in) :: src           !! the source
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    integer, intent(out) :: id                  !! the new entity, or 0
    character(len=len(line)) :: low
    character(len=:), allocatable :: words

    id = 0
    low = lowercase(line)
    select case (construct)
    case (C_MODULE)
        id = list%add(E_MODULE, parent)
        words = strip(line(7:))
        list%box(id)%e%name = words
        list%box(id)%e%permission = 'public'
    case (C_SUBMODULE)
        id = list%add(E_SUBMODULE, parent)
        call read_submodule(list%box(id)%e, line)
        list%box(id)%e%permission = 'private'
    case (C_PROGRAM)
        id = list%add(E_PROGRAM, parent)
        words = strip(line(8:))
        list%box(id)%e%name = words
        list%box(id)%e%permission = 'public'
    case (C_BLOCK_DATA)
        id = list%add(E_BLOCKDATA, parent)
        words = strip(line(index(low, 'data') + 4:))
        list%box(id)%e%name = words
        list%box(id)%e%permission = 'public'
    case (C_SUBROUTINE, C_FUNCTION)
        call open_procedure(list, parent, line, id)
    case (C_PROCEDURE)
        id = list%add(E_MODPROC, parent)
        words = strip(line(index(low, 'procedure') + 9:))
        list%box(id)%e%name = words
        list%box(id)%e%permission = inherited_permission(list, parent)
    case (C_INTERFACE)
        id = list%add(E_INTERFACE, parent)
        associate (e => list%box(id)%e)
            e%abstract = starts_word(low, 'abstract')
            e%permission = inherited_permission(list, parent)
            words = strip(line(index(low, 'interface') + 9:))
            e%name = words
            e%generic = len(words) > 0
            allocate (e%more%modprocs(0))
        end associate
    case (C_TYPE)
        id = list%add(E_TYPE, parent)
        list%box(id)%e%permission = inherited_permission(list, parent)
        list%box(id)%e%child_permission = 'public'
        call read_type_statement(list%box(id)%e, line)
    case (C_ENUM)
        id = list%add(E_ENUM, parent)
        list%box(id)%e%name = ''
        list%box(id)%e%permission = inherited_permission(list, parent)
        list%box(id)%e%child_permission = inherited_permission(list, parent)
    end select
    if (id == 0) return

    associate (e => list%box(id)%e)
        e%line = src%tokens%tok(src%stmts%s(item)%first)%line
        if (.not. allocated(e%child_permission)) e%child_permission = e%permission
        if (.not. allocated(e%attribs)) allocate (e%attribs(0))
        if (.not. allocated(e%more%uses)) allocate (e%more%uses(0))
        allocate (e%more%pending(0), e%more%parameters(0), e%more%public_list(0))
        if (.not. allocated(e%meta)) then
            if (allocated(doc%lines)) then
                call set_doc(e, s, doc%lines)
            else
                call set_doc(e, s, [string_t ::])
            end if
        end if
    end associate
    call inherit_display(list, id, s)
end subroutine open_unit

!> The permission of what is declared now in `id`.
pure function inherited_permission(list, id) result(permission)
    type(entity_list_t), intent(in) :: list !! the entities
    integer, intent(in) :: id               !! the entity
    character(len=permission_length(list, id)) :: permission

    if (allocated(list%box(id)%e%child_permission)) then
        permission = list%box(id)%e%child_permission
    else
        permission = 'public'
    end if
end function inherited_permission

!> Read a `submodule` statement.
subroutine read_submodule(e, line)
    type(entity_t), intent(inout) :: e      !! the submodule
    character(len=*), intent(in) :: line    !! the statement
    character(len=:), allocatable :: inside
    integer :: open, close, colon

    open = index(line, '(')
    close = index(line, ')')
    e%name = strip(line(close + 1:))
    inside = lowercase(remove_blanks(line(open + 1:close - 1)))
    colon = index(inside, ':')
    if (colon > 0) then
        e%more%ancestor = inside(:colon - 1)
        e%more%parent_submodule = inside(colon + 1:)
    else
        e%more%ancestor = inside
    end if
end subroutine read_submodule

!> Read a `type` statement.
subroutine read_type_statement(e, line)
    type(entity_t), intent(inout) :: e      !! the type
    character(len=*), intent(in) :: line    !! the statement
    type(string_t), allocatable :: parts(:)
    character(len=:), allocatable :: rest, low, base
    integer :: at, k, open

    allocate (e%attribs(0))
    rest = strip(line(5:))
    at = top_index(rest, '::')
    if (at > 0) then
        if (rest(1:1) == ',') then
            parts = top_split(rest(2:at - 1), ',')
            do k = 1, size(parts)
                low = lowercase(parts(k)%s)
                if (starts_with(remove_blanks(low), 'extends(')) then
                    base = parts(k)%s(index(parts(k)%s, '(') + 1:)
                    e%more%extends = strip(base(:len(base) - 1))
                else if (low == 'public' .or. low == 'private') then
                    e%permission = low
                else
                    call push(e%attribs, parts(k)%s)
                end if
            end do
        end if
        rest = strip(rest(at + 2:))
    end if
    open = index(rest, '(')
    if (open > 0) then
        e%more%parameters_list = top_split(rest(open + 1:len(rest) - 1), ',')
        e%name = strip(rest(:open - 1))
    else
        e%name = rest
    end if
end subroutine read_type_statement

!> Create the entity for a `subroutine` or `function` statement.
subroutine open_procedure(list, parent, line, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: parent               !! the entity around it
    character(len=*), intent(in) :: line        !! the statement
    integer, intent(out) :: id                  !! the new entity, or 0
    type(procedure_header_t) :: h
    type(parsed_type_t) :: t
    integer :: var

    call parse_procedure_header(line, h)
    id = 0
    if (.not. h%ok) return
    id = list%add(merge(E_FUNCTION, E_SUBROUTINE, h%is_function), parent)
    associate (e => list%box(id)%e)
        e%name = h%name
        e%permission = inherited_permission(list, parent)
        call move_alloc(h%attribs, e%attribs)
        call move_alloc(h%args, e%more%args)
        allocate (e%more%arg_ids(size(e%more%args)))
        e%more%arg_ids = 0
        e%is_module = contains_string(e%attribs, 'module')
        if (allocated(h%bind_c)) e%more%bind_c = h%bind_c
        if (h%is_function) then
            e%more%result_name = h%name
            if (allocated(h%result_name)) e%more%result_name = h%result_name
        end if
    end associate
    if (.not. h%is_function) return
    call parse_type(h%prefix, t)
    if (.not. t%ok) return
    var = list%add(E_VARIABLE, id)
    associate (v => list%box(var)%e)
        v%name = list%box(id)%e%more%result_name
        v%var_role = VAR_RESULT
        v%permission = 'public'
        allocate (v%attribs(0), v%doc(0), v%meta(0))
        call set_type(v, t)
    end associate
    list%box(id)%e%result = var
end subroutine open_procedure

!> Copy a parsed type to variable `v`.
subroutine set_type(v, t)
    type(entity_t), intent(inout) :: v      !! the variable
    type(parsed_type_t), intent(in) :: t    !! the type

    v%vartype = t%vartype
    if (allocated(t%kind)) v%type_kind = t%kind
    if (allocated(t%strlen)) v%strlen = t%strlen
    if (allocated(t%proto)) v%proto = t%proto
end subroutine set_type

!> Finish entity `id` at its closing statement.
subroutine close_unit(list, id, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the entity
    type(settings_t), intent(in) :: s           !! the settings

    select case (list%box(id)%e%kind)
    case (E_MODULE, E_SUBMODULE, E_PROGRAM, E_BLOCKDATA, E_MODPROC)
        call apply_attributes(list, id)
    case (E_SUBROUTINE, E_FUNCTION)
        call apply_attributes(list, id)
        call attach_arguments(list, id)
    case (E_INTERFACE)
        call close_interface(list, id)
    end select
end subroutine close_unit

!> Apply statements such as `public :: x` to the entities they name.
subroutine apply_attributes(list, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the unit
    character(len=:), allocatable :: name
    integer :: c, k, child

    associate (u => list%box(id)%e)
        do c = 1, size(u%children)
            child = u%children(c)
            associate (e => list%box(child)%e)
                select case (e%kind)
                case (E_FUNCTION, E_SUBROUTINE, E_TYPE, E_INTERFACE, E_VARIABLE)
                    if (.not. allocated(e%name)) cycle
                    name = lowercase(e%name)
                    do k = 1, size(u%more%pending)
                        if (u%more%pending(k)%name == name) then
                            call apply_one(e, u, u%more%pending(k)%value)
                            u%more%pending(k)%name = ''
                        end if
                    end do
                    if (allocated(e%permission)) then
                        if (e%permission == 'public') call push(u%more%public_list, name)
                    end if
                end select
            end associate
        end do
        do k = 1, size(u%more%pending)
            if (u%more%pending(k)%value == 'public' .and. len(u%more%pending(k)%name) > 0) then
                call push(u%more%public_list, u%more%pending(k)%name)
            end if
        end do
        do c = 1, size(u%children)
            child = u%children(c)
            if (list%box(child)%e%kind /= E_VARIABLE) cycle
            if (contains_string(list%box(child)%e%attribs, 'external')) list%box(child)%e%var_role = VAR_HIDDEN
        end do
        call mark_common_members(list, id)
    end associate
end subroutine apply_attributes

!> Apply attribute `value`, from a statement in unit `u`, to entity `e`.
subroutine apply_one(e, u, value)
    type(entity_t), intent(inout) :: e      !! the entity
    type(entity_t), intent(in) :: u         !! the unit
    character(len=*), intent(in) :: value   !! the attribute
    integer :: k, at

    select case (value)
    case ('public', 'private', 'protected')
        e%permission = value
        return
    end select
    if (e%kind == E_VARIABLE) then
        if (starts_with(value, 'intent(')) then
            e%intent = value(8:len(value) - 1)
            return
        end if
        if (value == 'parameter') then
            call push(e%attribs, value)
            do k = 1, size(u%more%parameters)
                if (u%more%parameters(k)%name == lowercase(e%name)) e%initial = u%more%parameters(k)%value
            end do
            return
        end if
        at = index(value, '(')
        if (at > 0 .and. (starts_with(value, 'pointer') .or. starts_with(value, 'allocatable'))) then
            call push(e%attribs, value(:at - 1))
            e%dimension = value(at:)
            return
        end if
    else if (starts_with(value, 'bind')) then
        e%more%bind_c = value(6:len(value) - 1)
        return
    end if
    call push(e%attribs, value)
end subroutine apply_one

!> Connect the dummy arguments and result of a procedure with their declarations.
subroutine attach_arguments(list, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the procedure
    integer :: a, c, child, var
    character(len=:), allocatable :: wanted

    associate (p => list%box(id)%e)
        if (p%kind == E_FUNCTION .and. p%result == 0) then
            wanted = lowercase(p%more%result_name)
            do c = 1, size(p%children)
                child = p%children(c)
                if (list%box(child)%e%kind /= E_VARIABLE) cycle
                if (lowercase(list%box(child)%e%name) == wanted) then
                    p%result = child
                    list%box(child)%e%var_role = VAR_RESULT
                    exit
                end if
            end do
            if (p%result == 0) p%result = implicit_variable(list, id, p%more%result_name, VAR_RESULT)
        end if
        call doxygen_params(list, id)
        do a = 1, size(p%more%args)
            wanted = lowercase(p%more%args(a)%s)
            do c = 1, size(p%children)
                child = p%children(c)
                if (.not. allocated(list%box(child)%e%name)) cycle
                if (list%box(child)%e%kind == E_VARIABLE) then
                    if (list%box(child)%e%var_role == VAR_PLAIN .and. lowercase(list%box(child)%e%name) == wanted) then
                        p%more%arg_ids(a) = child
                        list%box(child)%e%var_role = VAR_ARGUMENT
                        exit
                    end if
                else if (list%box(child)%e%iface == IFACE_EXPLICIT .and. lowercase(list%box(child)%e%name) == wanted) then
                    p%more%arg_ids(a) = child
                    exit
                end if
            end do
            if (p%more%arg_ids(a) == 0) then
                var = implicit_variable(list, id, p%more%args(a)%s, VAR_ARGUMENT)
                p%more%arg_ids(a) = var
            end if
        end do
    end associate
end subroutine attach_arguments

!> Move doxygen `@param name text` lines from procedure `id` to the variables they describe.
subroutine doxygen_params(list, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the procedure
    type(string_t), allocatable :: kept(:), words(:)
    character(len=:), allocatable :: line
    integer :: k, c, at, child
    logical :: moved

    if (.not. allocated(list%box(id)%e%doc)) return
    allocate (kept(0))
    do k = 1, size(list%box(id)%e%doc)
        line = strip(list%box(id)%e%doc(k)%s)
        moved = .false.
        if (starts_with(line, '@param')) then
            at = index(line, ']')
            if (at == 0) at = 6
            words = split_words(line(at + 1:))
            if (size(words) >= 1) then
                do c = 1, size(list%box(id)%e%children)
                    child = list%box(id)%e%children(c)
                    if (list%box(child)%e%kind /= E_VARIABLE) cycle
                    if (lowercase(list%box(child)%e%name) /= lowercase(words(1)%s)) cycle
                    call push(list%box(child)%e%doc, join(words(2:), ' '))
                    moved = .true.
                end do
            end if
        end if
        if (.not. moved) call push(kept, list%box(id)%e%doc(k)%s)
    end do
    call move_alloc(kept, list%box(id)%e%doc)
end subroutine doxygen_params

!> Add a variable for `name`, implicitly typed.
function implicit_variable(list, parent, name, role) result(id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: parent               !! the procedure
    character(len=*), intent(in) :: name        !! the name
    integer, intent(in) :: role                 !! one of the `VAR_*` constants
    integer :: id

    id = list%add(E_VARIABLE, parent)
    associate (v => list%box(id)%e)
        v%name = name
        v%var_role = role
        v%permission = 'public'
        v%vartype = merge('integer', 'real   ', index('ijklmn', lowercase(name(1:1))) > 0)
        v%vartype = trim(v%vartype)
        allocate (v%attribs(0), v%doc(0), v%meta(0))
    end associate
end function implicit_variable

!> Finish an interface block. All but generic interfaces dissolve, leaving their bodies in the unit
!> around them.
subroutine close_interface(list, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the interface
    integer :: parent, c, child, kind_of_body

    if (list%box(id)%e%generic) return
    parent = list%box(id)%e%parent
    kind_of_body = merge(IFACE_ABSTRACT, IFACE_EXPLICIT, list%box(id)%e%abstract)
    do c = 1, size(list%box(id)%e%children)
        child = list%box(id)%e%children(c)
        associate (e => list%box(child)%e)
            if (.not. is_procedure(e%kind)) cycle
            e%iface = kind_of_body
            e%parent = parent
            e%permission = list%box(id)%e%permission
            call push_int(list%box(parent)%e%children, child)
        end associate
    end do
    call remove_child(list%box(parent)%e, id)
    list%box(id)%e%kind = E_NONE
    list%box(id)%e%visible = .false.
end subroutine close_interface

!> Remove `id` from the children of `e`.
pure subroutine remove_child(e, id)
    type(entity_t), intent(inout) :: e  !! the parent
    integer, intent(in) :: id           !! the child
    e%children = pack(e%children, e%children /= id)
end subroutine remove_child

!> Read a statement that opens nothing, if it declares anything.
subroutine parse_statement(list, unit, line, doc, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the entity it is in
    character(len=*), intent(in) :: line        !! the statement
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    character(len=len(line)) :: low

    if (len(line) == 0) return
    low = lowercase(line)
    associate (u => list%box(unit)%e)
        if (.not. allocated(u%name)) return
        select case (trim(low))
        case ('public', 'private', 'protected')
            u%child_permission = trim(low)
            if (u%kind /= E_TYPE) u%permission = trim(low)
            return
        case ('sequence')
            u%sequence = .true.
            return
        end select
        if (u%kind == E_FILE) return

        if (starts_word(low, 'use')) then
            call read_use(u, line)
        else if (u%kind == E_TYPE .and. u%in_contains .and. &
                 (starts_word(low, 'procedure') .or. starts_word(low, 'generic'))) then
            call read_binding(list, unit, line, doc, s)
        else if (u%kind == E_TYPE .and. u%in_contains .and. starts_word(low, 'final')) then
            call read_final(list, unit, line)
        else if (u%kind == E_INTERFACE .and. (starts_word(low, 'module') .or. starts_word(low, 'procedure'))) then
            call read_module_procedures(u, line)
        else if (starts_word(low, 'namelist')) then
            call read_namelist(list, unit, line, doc, s)
        else if (starts_word(low, 'common')) then
            call read_common(list, unit, line, doc, s)
        else if (is_attribute_statement(low)) then
            call read_attribute_statement(u, line, low)
        else if (is_type_declaration(low)) then
            call read_declaration(list, unit, line, doc, s)
        end if
    end associate
end subroutine parse_statement

!> Read a `use` statement.
subroutine read_use(u, line)
    type(entity_t), intent(inout) :: u      !! the unit
    character(len=*), intent(in) :: line    !! the statement
    character(len=:), allocatable :: rest, name, spec
    integer :: at

    rest = strip(line(4:))
    at = top_index(rest, '::')
    if (at > 0 .and. (index(rest, ',') == 0 .or. index(rest, ',') < at .or. at > 0)) then
        if (at < index(rest//',', ',') .or. index(rest, ',') > 0 .and. at > 0) rest = strip(rest(at + 2:))
    end if
    at = index(rest, ',')
    if (at > 0) then
        name = lowercase(strip(rest(:at - 1)))
        spec = strip(rest(at + 1:))
    else
        name = lowercase(rest)
        spec = ''
    end if
    u%more%uses = [u%more%uses, use_t(name, spec, 0)]
end subroutine read_use

!> True if `low` starts with a word that gives attributes to names listed after it.
logical function is_attribute_statement(low)
    character(len=*), intent(in) :: low     !! the statement, in lowercase
    character(len=:), allocatable :: compact
    integer :: k, n

    is_attribute_statement = .false.
    if (starts_word(low, 'bind')) then
        is_attribute_statement = index(low, ')') > 0
        return
    end if
    if (starts_word(low, 'intent')) then
        is_attribute_statement = .true.
        return
    end if
    do k = 1, size(ATTRIBUTE_WORDS)
        if (.not. starts_word(low, trim(ATTRIBUTE_WORDS(k)))) cycle
        n = len_trim(ATTRIBUTE_WORDS(k))
        compact = strip(low(n + 1:))
        if (len(compact) == 0) then
            is_attribute_statement = trim(ATTRIBUTE_WORDS(k)) == 'save'
            return
        end if
        ! not an assignment to a variable named like the attribute
        is_attribute_statement = compact(1:1) /= '=' .and. compact(1:1) /= '%'
        return
    end do
end function is_attribute_statement

!> Read a statement such as `public :: x`, keeping what it says until the unit is finished.
subroutine read_attribute_statement(u, line, low)
    type(entity_t), intent(inout) :: u      !! the unit
    character(len=*), intent(in) :: line    !! the statement
    character(len=*), intent(in) :: low     !! the statement, in lowercase
    character(len=:), allocatable :: attr, rest, name, dims
    type(string_t), allocatable :: names(:), parts(:)
    integer :: k, at, close

    if (starts_word(low, 'bind') .or. starts_word(low, 'intent')) then
        close = closing_paren(low, index(low, '('))
        attr = remove_blanks(low(:close))
        if (starts_with(attr, 'bind')) attr = replace_commas(attr)
        rest = line(close + 1:)
    else
        at = verify(low, 'abcdefghijklmnopqrstuvwxyz_')
        if (at == 0) at = len(low) + 1
        attr = low(:at - 1)
        rest = line(at:)
    end if
    if (is_procedure(u%kind) .and. (attr == 'data' .or. attr == 'save')) u%more%saved_state = .true.
    if (attr == 'data' .or. attr == 'save' .and. len(strip(rest)) == 0) return
    if (.not. allocated(u%more%pending)) return
    rest = strip(rest)
    if (starts_with(rest, '::')) rest = strip(rest(3:))
    if (attr == 'parameter' .and. len(rest) > 1) rest = strip(rest(2:len(rest) - 1))
    names = top_split(rest, ',')
    do k = 1, size(names)
        name = lowercase(names(k)%s)
        if (attr == 'dimension' .or. attr == 'allocatable' .or. attr == 'pointer') then
            at = index(name, '(')
            if (at > 0) then
                dims = name(at:)
                name = strip(name(:at - 1))
                u%more%pending = [u%more%pending, attribute_t(name, attr//dims)]
                cycle
            end if
        else if (attr == 'parameter') then
            parts = top_split(names(k)%s, '=')
            if (size(parts) < 2) cycle
            name = lowercase(parts(1)%s)
            u%more%parameters = [u%more%parameters, attribute_t(name, parts(2)%s)]
        end if
        u%more%pending = [u%more%pending, attribute_t(name, attr)]
    end do
end subroutine read_attribute_statement

!> `attr` with a blank after each comma.
pure function replace_commas(attr) result(out)
    character(len=*), intent(in) :: attr    !! the text
    character(len=len(attr) + comma_count(attr)) :: out
    integer :: k, n

    n = 0
    do k = 1, len(attr)
        n = n + 1
        out(n:n) = attr(k:k)
        if (attr(k:k) == ',') then
            n = n + 1
            out(n:n) = ' '
        end if
    end do
end function replace_commas

!> Read a variable declaration, adding a variable for each name.
subroutine read_declaration(list, unit, line, doc, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the entity it is in
    character(len=*), intent(in) :: line        !! the statement
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    type(parsed_type_t) :: t
    type(string_t), allocatable :: attributes(:), names(:), kept(:)
    character(len=:), allocatable :: rest, low, permission, intent, name, dimension, initial
    logical :: optional, parameter, points
    integer :: k, id

    call parse_type(line, t)
    if (.not. t%ok) return
    call split_attributes(t%rest, attributes, rest)
    allocate (kept(0))
    permission = inherited_permission(list, unit)
    intent = ''
    optional = .false.
    parameter = .false.
    do k = 1, size(attributes)
        low = remove_blanks(lowercase(attributes(k)%s))
        select case (low)
        case ('public', 'private', 'protected')
            permission = low
        case ('optional')
            optional = .true.
        case ('parameter')
            parameter = .true.
        case ('intent(in)')
            intent = 'in'
        case ('intent(out)')
            intent = 'out'
        case ('intent(inout)', 'intent(in out)')
            intent = 'inout'
        case default
            call push(kept, attributes(k)%s)
        end select
    end do
    names = top_split(rest, ',')
    do k = 1, size(names)
        call parse_declarator(names(k)%s, name, dimension, initial, points)
        ! what is initialized in a declaration in a procedure is saved, even with no `save`
        if (is_procedure(list%box(unit)%e%kind) .and. .not. parameter) then
            if (allocated(initial) .or. contains_string(kept, 'save')) list%box(unit)%e%more%saved_state = .true.
        end if
        id = list%add(E_VARIABLE, unit)
        associate (v => list%box(id)%e)
            call move_alloc(name, v%name)
            if (allocated(dimension)) call move_alloc(dimension, v%dimension)
            if (allocated(initial)) call move_alloc(initial, v%initial)
            call set_type(v, t)
            v%attribs = kept
            v%permission = permission
            v%intent = intent
            v%optional = optional
            v%parameter = parameter
            v%points = points
            if (allocated(doc%lines)) then
                call set_doc(v, s, doc%lines)
            else
                call set_doc(v, s, [string_t ::])
            end if
        end associate
    end do
end subroutine read_declaration

!> Read a type-bound `procedure` or `generic` statement.
subroutine read_binding(list, unit, line, doc, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the type
    character(len=*), intent(in) :: line        !! the statement
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    type(string_t), allocatable :: names(:), attributes(:), kept(:), bindings(:)
    character(len=:), allocatable :: rest, proto, permission, low, name
    logical :: generic, deferred
    integer :: k, id, open, close

    low = lowercase(line)
    generic = starts_word(low, 'generic')
    rest = strip(line(merge(8, 10, generic):))
    proto = ''
    if (len(rest) > 0) then
        if (rest(1:1) == '(') then
            close = closing_paren(rest, 1)
            proto = strip(rest(2:close - 1))
            rest = strip(rest(close + 1:))
        end if
    end if
    call split_attributes(rest, attributes, name)
    rest = name
    allocate (kept(0))
    permission = list%box(unit)%e%child_permission
    deferred = .false.
    do k = 1, size(attributes)
        low = lowercase(attributes(k)%s)
        select case (low)
        case ('public', 'private')
            permission = low
        case ('deferred')
            deferred = .true.
        case default
            call push(kept, low)
        end select
    end do

    if (generic) then
        allocate (names(1))
        names(1)%s = rest
    else
        names = top_split(rest, ',')
    end if
    do k = size(names), 1, -1
        id = list%add(E_BOUNDPROC, unit)
        associate (b => list%box(id)%e, text => names(k)%s)
            open = index(text, '=>')
            if (open > 0) then
                b%name = strip(text(:open - 1))
                b%more%bindings = top_split(text(open + 2:), ',')
            else
                b%name = strip(text)
                bindings = [string_t(b%name)]
                call move_alloc(bindings, b%more%bindings)
            end if
            b%generic = generic
            b%deferred = deferred
            b%permission = permission
            b%attribs = kept
            if (len(proto) > 0) b%more%proto_text = proto
            if (allocated(doc%lines)) then
                call set_doc(b, s, doc%lines)
            else
                call set_doc(b, s, [string_t ::])
            end if
        end associate
    end do
end subroutine read_binding

!> Read a `final` statement.
subroutine read_final(list, unit, line)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the type
    character(len=*), intent(in) :: line        !! the statement
    type(string_t), allocatable :: names(:)
    integer :: k, id, at

    at = index(line, '::')
    if (at == 0) return
    names = top_split(line(at + 2:), ',')
    do k = 1, size(names)
        id = list%add(E_FINAL, unit)
        list%box(id)%e%name = names(k)%s
        list%box(id)%e%permission = 'public'
        allocate (list%box(id)%e%attribs(0), list%box(id)%e%doc(0), list%box(id)%e%meta(0))
    end do
end subroutine read_final

!> Read a `module procedure` or `procedure` statement in an interface.
subroutine read_module_procedures(u, line)
    type(entity_t), intent(inout) :: u      !! the interface
    character(len=*), intent(in) :: line    !! the statement
    type(string_t), allocatable :: names(:)
    character(len=:), allocatable :: rest
    integer :: at, k

    rest = line(index(lowercase(line), 'procedure') + 9:)
    at = index(rest, '::')
    if (at > 0) rest = rest(at + 2:)
    names = top_split(rest, ',')
    do k = 1, size(names)
        call push(u%more%modprocs, names(k)%s)
    end do
end subroutine read_module_procedures

!> Read a `common` statement, adding a common block entity for each block it names.
subroutine read_common(list, unit, line, doc, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the entity it is in
    character(len=*), intent(in) :: line        !! the statement
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    character(len=:), allocatable :: rest, name
    integer :: a, b, next, id

    rest = strip(line(7:))
    do while (len(rest) > 0)
        name = ''
        if (rest(1:1) == '/') then
            b = index(rest(2:), '/') + 1
            name = strip(rest(2:b - 1))
            rest = strip(rest(b + 1:))
        end if
        next = top_index(rest, '/')
        a = merge(next - 1, len(rest), next > 0)
        if (is_procedure(list%box(unit)%e%kind)) list%box(unit)%e%more%common_block = .true.
        id = list%add(E_COMMON, unit)
        associate (c => list%box(id)%e)
            c%name = name
            c%permission = 'public'
            c%more%args = top_split(rest(:a), ',')
            allocate (c%attribs(0))
            if (allocated(doc%lines)) then
                call set_doc(c, s, doc%lines)
            else
                call set_doc(c, s, [string_t ::])
            end if
        end associate
        rest = strip(rest(a + 1:))
    end do
end subroutine read_common

!> Mark the variables of unit `id` named in its common blocks.
subroutine mark_common_members(list, id)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: id                   !! the unit
    character(len=:), allocatable :: member
    integer :: c, m, v, block, child, at

    do c = 1, size(list%box(id)%e%children)
        block = list%box(id)%e%children(c)
        if (list%box(block)%e%kind /= E_COMMON) cycle
        do m = 1, size(list%box(block)%e%more%args)
            member = lowercase(list%box(block)%e%more%args(m)%s)
            at = index(member, '(')
            if (at > 0) member = strip(member(:at - 1))
            do v = 1, size(list%box(id)%e%children)
                child = list%box(id)%e%children(v)
                if (list%box(child)%e%kind /= E_VARIABLE) cycle
                if (list%box(child)%e%var_role /= VAR_PLAIN) cycle
                if (lowercase(list%box(child)%e%name) == member) list%box(child)%e%var_role = VAR_COMMON
            end do
        end do
    end do
end subroutine mark_common_members

!> Read a `namelist` statement.
subroutine read_namelist(list, unit, line, doc, s)
    type(entity_list_t), intent(inout) :: list  !! the entities
    integer, intent(in) :: unit                 !! the entity it is in
    character(len=*), intent(in) :: line        !! the statement
    type(doc_lines_t), intent(in) :: doc        !! the statement's documentation
    type(settings_t), intent(in) :: s           !! the settings
    integer :: a, b, id

    a = index(line, '/')
    b = index(line, '/', back=.true.)
    if (a == 0 .or. b <= a) return
    id = list%add(E_NAMELIST, unit)
    associate (n => list%box(id)%e)
        n%name = strip(line(a + 1:b - 1))
        n%permission = inherited_permission(list, unit)
        n%more%args = top_split(line(b + 1:), ',')
        allocate (n%attribs(0))
        if (allocated(doc%lines)) then
            call set_doc(n, s, doc%lines)
        else
            call set_doc(n, s, [string_t ::])
        end if
    end associate
end subroutine read_namelist

end module fdoc_parser
 
 
!>>>>> ././src/fdoc_project.f90
module fdoc_project
!! The whole project: loads and parses the files, merges them into one list of entities, and
!! connects the entities with each other.
use json_module, only: json_core, json_value
use fdoc_util
use fdoc_model
use fdoc_settings, only: settings_t
use ffmt_fs, only: parent_directory
use fdoc_input, only: find_sources, load_source, runs_command, expand_includes
use fdoc_progress, only: progress_start, progress_tick, progress_finish, warn
use fdoc_parser, only: parse_file
use fdoc_shell, only: make_directory, quoted, quoted_path, run_command
implicit none
private

public :: load_project_sources, correlate, prune, public_symbols, find_symbol

type, public :: symbol_t
    !! An entity under the name it is known by in some scope.
    character(len=:), allocatable :: name   !! the name, in lowercase
    integer :: id = 0                       !! the entity
end type symbol_t

type :: symbol_list_t
    !! Names, in the order they were added, with an index.
    type(symbol_t), allocatable :: s(:)         !! storage; only `s(1:n)` is in use
    integer :: n = 0                            !! how many there are
    type(name_index_t) :: index                 !! the position of each name
end type symbol_list_t

type :: symbols_t
    !! The names a module makes public, by category.
    type(symbol_list_t) :: procs                !! procedures and interfaces
    type(symbol_list_t) :: absints              !! abstract interfaces
    type(symbol_list_t) :: types                !! derived types
    type(symbol_list_t) :: vars                 !! variables
    type(name_index_t) :: public_list           !! the names of the module's `public` statements
    integer :: state = 0                        !! 0 not computed, 1 being computed, 2 computed
end type symbols_t

type, public :: project_t
    !! The parsed project.
    type(entity_list_t) :: list             !! all entities
    integer, allocatable :: files(:)        !! the file entities
    integer, allocatable :: modules(:)      !! the module entities
    type(symbols_t), allocatable :: pub(:)  !! the public names of each entity in `modules`
    integer, allocatable :: submodules(:)   !! the submodule entities
end type project_t

contains

!> The public names of module `which` in a category: 1 procedures, 2 abstract interfaces, 3 types,
!> 4 variables.
function public_symbols(p, which, category) result(symbols)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: which        !! position in `p%modules`
    integer, intent(in) :: category     !! the category
    type(symbol_t), allocatable :: symbols(:)

    select case (category)
    case (1); symbols = p%pub(which)%procs%s(:p%pub(which)%procs%n)
    case (2); symbols = p%pub(which)%absints%s(:p%pub(which)%absints%n)
    case (3); symbols = p%pub(which)%types%s(:p%pub(which)%types%n)
    case default; symbols = p%pub(which)%vars%s(:p%pub(which)%vars%n)
    end select
end function public_symbols

!> Find, load and parse the source files, and merge the results into `p`.
subroutine load_project_sources(s, p, stat, errmsg)
    type(settings_t), intent(in) :: s                   !! the settings
    type(project_t), intent(out) :: p                   !! the project
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg  !! what is wrong
    type(string_t), allocatable :: paths(:), texts(:), raws(:)
    type(entity_list_t), allocatable :: lists(:)
    integer :: k

    stat = 0
    call find_sources(s, paths)
    if (size(paths) == 0) then
        stat = 1
        errmsg = 'No source files with appropriate extension found in specified directory.'
        return
    end if
    allocate (texts(size(paths)), lists(size(paths)), raws(size(paths)))
    ! files that go through an external command share its temporary files, so they take turns
    call progress_start('Reading files', size(paths))
    !$omp parallel do schedule(dynamic) num_threads(max(1, s%parallel)) default(shared) private(k)
    do k = 1, size(paths)
        if (.not. runs_command(s, paths(k)%s)) call read_source(s, paths(k)%s, raws(k)%s, texts(k)%s)
        call progress_tick()
    end do
    !$omp end parallel do
    do k = 1, size(paths)
        if (runs_command(s, paths(k)%s)) call read_source(s, paths(k)%s, raws(k)%s, texts(k)%s)
        call expand_includes(s%include, parent_directory(paths(k)%s), texts(k)%s, 1)
    end do
    call progress_finish()

    call progress_start('Parsing files', size(paths))
    !$omp parallel do schedule(dynamic) num_threads(max(1, s%parallel)) default(shared)
    do k = 1, size(paths)
        call parse_file(paths(k)%s, texts(k)%s, s, lists(k))
        call progress_tick()
    end do
    !$omp end parallel do
    call progress_finish()

    do k = 1, size(lists)
        call move_alloc(raws(k)%s, lists(k)%box(1)%e%source_text)
        call merge_list(p, lists(k))
    end do
end subroutine load_project_sources

!> Read source file `path`, warning if that fails.
subroutine read_source(s, path, raw, text)
    type(settings_t), intent(in) :: s                   !! the settings
    character(len=*), intent(in) :: path                !! the file
    character(len=:), allocatable, intent(out) :: raw   !! the file as it is
    character(len=:), allocatable, intent(out) :: text  !! the text to parse
    character(len=:), allocatable :: msg
    integer :: ios

    call load_source(s, path, raw, text, ios, msg)
    if (ios /= 0) then
        call warn('could not read '//path//': '//msg)
        text = ''
        raw = ''
    end if
end subroutine read_source

!> Move the entities of `from` to the end of `p%list`, adjusting their indices.
subroutine merge_list(p, from)
    type(project_t), intent(inout) :: p         !! the project
    type(entity_list_t), intent(inout) :: from  !! the entities of a file
    type(entity_box_t), allocatable :: grown(:)
    integer :: offset, k, needed

    offset = p%list%n
    needed = offset + from%n
    if (.not. allocated(p%list%box)) allocate (p%list%box(max(needed, 64)))
    if (needed > size(p%list%box)) then
        allocate (grown(2*needed))
        do k = 1, offset
            call move_alloc(p%list%box(k)%e, grown(k)%e)
        end do
        call move_alloc(grown, p%list%box)
    end if
    do k = 1, from%n
        call move_alloc(from%box(k)%e, p%list%box(offset + k)%e)
        associate (e => p%list%box(offset + k)%e)
            if (e%parent > 0) e%parent = e%parent + offset
            e%file = e%file + offset
            e%children = e%children + offset
            if (e%result > 0) e%result = e%result + offset
            if (allocated(e%more%arg_ids)) e%more%arg_ids = e%more%arg_ids + offset
            if (e%kind == E_MODULE) call push_int(p%modules, offset + k)
            if (e%kind == E_SUBMODULE) call push_int(p%submodules, offset + k)
            if (e%kind == E_FILE) call push_int(p%files, offset + k)
        end associate
    end do
    p%list%n = needed
end subroutine merge_list

!> Connect entities across files: the public names of each module, and what types inherit.
subroutine correlate(p, s)
    type(project_t), intent(inout) :: p     !! the project
    type(settings_t), intent(in) :: s       !! the settings
    integer :: k, n

    if (.not. allocated(p%modules)) allocate (p%modules(0))
    if (.not. allocated(p%submodules)) allocate (p%submodules(0))
    call add_external_modules(p, s)
    allocate (p%pub(size(p%modules)))
    call link_uses(p)
    do k = 1, size(p%modules)
        call public_names(p, k)
    end do
    n = p%list%n
    do k = 1, n
        if (p%list%box(k)%e%kind /= E_TYPE) cycle
        if (p%list%box(k)%e%parent == 0) cycle
        call set_constructor(p, k)
        call inherit(p, k)
    end do
end subroutine correlate

!> Add modules documented elsewhere: `extra_mods`, and the `modules.json` of external projects.
subroutine add_external_modules(p, s)
    type(project_t), intent(inout) :: p     !! the project
    type(settings_t), intent(in) :: s       !! the settings
    integer :: k, id

    do k = 1, size(s%extra_mods)
        id = p%list%add(E_MODULE, 0)
        associate (e => p%list%box(id)%e)
            e%name = s%extra_mods(k)%key
            e%external_url = s%extra_mods(k)%value
            e%permission = 'public'
            allocate (e%more%uses(0), e%more%public_list(0), e%attribs(0), e%doc(0), e%meta(0))
        end associate
        call push_int(p%modules, id)
    end do
    do k = 1, size(s%external)
        call load_external_project(p, s, s%external(k)%value)
    end do
end subroutine add_external_modules

!> Add the modules in the `modules.json` of an external project at `url`, a path or a web address.
subroutine load_external_project(p, s, url)
    type(project_t), intent(inout) :: p     !! the project
    type(settings_t), intent(in) :: s       !! the settings
    character(len=*), intent(in) :: url     !! where the project's documentation is
    type(json_core) :: json
    type(json_value), pointer :: root, modules, item
    character(len=:), allocatable :: path, base, fetched
    character(len=32) :: tag
    logical :: found, remote
    integer :: k, n, id, status

    remote = starts_with(url, 'http://') .or. starts_with(url, 'https://')
    if (remote) then
        base = url
        if (.not. ends_with(base, '/')) base = base//'/'
        call unique_tag(tag)
        fetched = s%output_dir//'/.external-modules-'//trim(tag)//'.json'
        call make_directory(s%output_dir, status)
        call run_command('curl -fsSL -o '//quoted_path(fetched)//' '//quoted(base//'modules.json'), status)
        path = fetched
        if (status /= 0) then
            call warn("Could not open external URL '"//url//"'")
            return
        end if
    else
        base = resolve_path(s%directory, url)//'/'
        path = base//'modules.json'
    end if

    call json%initialize()
    call json%load(path, root)
    if (remote) then
        call remove_file(fetched)
    end if
    if (json%failed()) then
        call json%clear_exceptions()
        call warn("Could not open external URL '"//url//"'")
        return
    end if
    call json%get_child(root, 'modules', modules, found)
    if (found) then
        call json%info(modules, n_children=n)
        do k = 1, n
            call json%get_child(modules, k, item, found)
            call read_external(p, json, item, base, 0, id)
            if (id > 0) call push_int(p%modules, id)
        end do
    end if
    call json%destroy(root)
    if (remote) then
        call remove_file(path)
    end if
end subroutine load_external_project

!> Add the entity described by `node` of an external `modules.json`, with those inside it.
recursive subroutine read_external(p, json, node, base, parent, id)
    type(project_t), intent(inout) :: p             !! the project
    type(json_core), intent(inout) :: json          !! the JSON handler
    type(json_value), pointer, intent(in) :: node   !! the entity
    character(len=*), intent(in) :: base            !! the external project's address, ending in `/`
    integer, intent(in) :: parent                   !! the entity it goes in, or 0
    integer, intent(out) :: id                      !! the new entity, or 0
    character(len=*), parameter :: LISTS(*) = [character(len=13) :: 'pub_procs', 'pub_absints', 'pub_types', 'pub_vars', &
                                               'boundprocs', 'variables']
    character(len=:), allocatable :: name, url, obj, proctype, text
    type(json_value), pointer :: list, item
    logical :: found
    integer :: k, n, j, child, kind

    id = 0
    call json%get(node, 'name', name, found)
    if (.not. found) return
    call json%get(node, 'obj', obj, found)
    call json%get(node, 'proctype', proctype, found)
    if (.not. found) proctype = ''
    select case (obj)
    case ('module'); kind = E_MODULE
    case ('type'); kind = E_TYPE
    case ('variable'); kind = E_VARIABLE
    case ('boundprocedure'); kind = E_BOUNDPROC
    case ('interface'); kind = E_INTERFACE
    case default; kind = merge(E_FUNCTION, E_SUBROUTINE, proctype == 'Function')
    end select
    id = p%list%add(kind, parent)
    call json%get(node, 'external_url', url, found)
    associate (e => p%list%box(id)%e)
        e%name = name
        if (found) then
            if (starts_with(url, './')) url = url(3:)
            e%external_url = base//url
        end if
        call json%get(node, 'permission', text, found)
        e%permission = 'public'
        if (found) e%permission = text
        call json%get(node, 'vartype', text, found)
        e%vartype = ''
        if (found) e%vartype = text
        allocate (e%more%uses(0), e%more%public_list(0), e%attribs(0), e%doc(0), e%meta(0))
        e%var_role = VAR_PLAIN
    end associate
    do k = 1, size(LISTS)
        call json%get_child(node, trim(LISTS(k)), list, found)
        if (.not. found) cycle
        call json%info(list, n_children=n)
        do j = 1, n
            call json%get_child(list, j, item, found)
            call read_external(p, json, item, base, id, child)
        end do
    end do
end subroutine read_external

!> Find the modules that `use` statements and submodules refer to.
subroutine link_uses(p)
    type(project_t), intent(inout) :: p     !! the project
    integer :: k, u, j, found

    do k = 1, p%list%n
        associate (e => p%list%box(k)%e)
            if (allocated(e%more%uses)) then
                do u = 1, size(e%more%uses)
                    found = find_module(p, e%more%uses(u)%module)
                    if (found > 0) e%more%uses(u)%target = p%modules(found)
                    call read_use_spec(e%more%uses(u)%spec, e%more%uses(u)%only, e%more%uses(u)%renames)
                end do
            end if
            if (e%kind /= E_SUBMODULE) cycle
            found = find_module(p, e%more%ancestor)
            if (found > 0) e%ancestor_id = p%modules(found)
            if (allocated(e%more%parent_submodule)) then
                do j = 1, size(p%submodules)
                    if (lowercase(p%list%box(p%submodules(j))%e%name) == e%more%parent_submodule) then
                        e%parent_submodule_id = p%submodules(j)
                    end if
                end do
            end if
        end associate
    end do
end subroutine link_uses

!> The position of `name` in `symbols`, or 0.
pure integer function find_in(symbols, name)
    type(symbol_list_t), intent(in) :: symbols  !! the names
    character(len=*), intent(in) :: name        !! the name, in lowercase
    integer :: at

    find_in = 0
    at = index_find(symbols%index, name)
    if (at > 0) find_in = symbols%s(at)%id
end function find_in

!> True if entity `e` declares a name of category `category`: 1 procedures, 2 abstract interfaces,
!> 3 types, 4 variables.
pure logical function in_category(e, category)
    type(entity_t), intent(in) :: e     !! the entity
    integer, intent(in) :: category     !! the category

    select case (category)
    case (1)
        in_category = e%kind == E_INTERFACE .or. ((is_procedure(e%kind) .or. &
                                                   e%kind == E_MODPROC) .and. e%iface /= IFACE_ABSTRACT)
    case (2)
        in_category = is_procedure(e%kind) .and. e%iface == IFACE_ABSTRACT
    case (3)
        in_category = e%kind == E_TYPE
    case default
        in_category = e%kind == E_VARIABLE
    end select
end function in_category

!> What `name` means in scope `scope` for category `category` (see [[in_category]]), or 0.
recursive integer function find_symbol(p, scope, name, category) result(id)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: scope            !! the entity to look in
    character(len=*), intent(in) :: name    !! the name, in lowercase
    integer, intent(in) :: category         !! the category
    integer :: c, b, child, u, j, used, target

    id = 0
    associate (e => p%list%box(scope)%e)
        do c = 1, size(e%children)
            child = e%children(c)
            associate (item => p%list%box(child)%e)
                if (.not. allocated(item%name)) cycle
                if (in_category(item, category)) then
                    if (lowercase(item%name) == name) then
                        id = child
                        return
                    end if
                end if
                if (category == 1 .and. item%kind == E_INTERFACE) then
                    do b = 1, size(item%children)
                        associate (body => p%list%box(item%children(b))%e)
                            if (.not. allocated(body%name)) cycle
                            if (body%kind /= E_VARIABLE .and. lowercase(body%name) == name) then
                                id = item%children(b)
                                return
                            end if
                        end associate
                    end do
                end if
                if (category == 1 .and. item%kind == E_VARIABLE) then
                    if (item%vartype == 'procedure' .and. lowercase(item%name) == name) then
                        id = child
                        return
                    end if
                end if
            end associate
        end do
        if (allocated(e%more%uses)) then
            do u = 1, size(e%more%uses)
                target = e%more%uses(u)%target
                if (target == 0) cycle
                used = module_position(p, target)
                if (used == 0) cycle
                if (e%more%uses(u)%only) then
                    do j = 1, size(e%more%uses(u)%renames)
                        if (e%more%uses(u)%renames(j)%local /= name) cycle
                        id = public_symbol(p, used, e%more%uses(u)%renames(j)%used, category)
                        if (id > 0) return
                    end do
                else
                    id = public_symbol(p, used, name, category)
                    if (id > 0) return
                end if
            end do
        end if
        if (e%kind == E_SUBMODULE) then
            if (e%parent_submodule_id > 0) then
                id = find_symbol(p, e%parent_submodule_id, name, category)
            else if (e%ancestor_id > 0) then
                id = find_symbol(p, e%ancestor_id, name, category)
            end if
            if (id > 0) return
        end if
        if (e%parent > 0) id = find_symbol(p, e%parent, name, category)
    end associate
end function find_symbol

!> The public entity of module `which` named `name` in category `category`, or 0.
pure integer function public_symbol(p, which, name, category) result(id)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: which            !! position in `p%modules`
    character(len=*), intent(in) :: name    !! the name, in lowercase
    integer, intent(in) :: category         !! the category

    id = 0
    if (p%pub(which)%state == 0) return
    select case (category)
    case (1); id = find_in(p%pub(which)%procs, name)
    case (2); id = find_in(p%pub(which)%absints, name)
    case (3); id = find_in(p%pub(which)%types, name)
    case default; id = find_in(p%pub(which)%vars, name)
    end select
end function public_symbol

!> The position in `p%modules` of module entity `id`, or 0.
pure integer function module_position(p, id)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: id           !! the module
    integer :: k

    module_position = 0
    do k = 1, size(p%modules)
        if (p%modules(k) == id) then
            module_position = k
            return
        end if
    end do
end function module_position

!> Work out what type `id` inherits, after its parent type.
recursive subroutine inherit(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the type
    integer, allocatable :: parent_items(:)
    integer :: base, k, item, copy

    if (p%list%box(id)%e%inherit_state /= 0) return
    p%list%box(id)%e%inherit_state = 1
    allocate (p%list%box(id)%e%more%inherited(0))
    if (allocated(p%list%box(id)%e%more%extends)) then
        base = find_symbol(p, p%list%box(id)%e%parent, lowercase(p%list%box(id)%e%more%extends), 3)
        if (base > 0 .and. base /= id) then
            p%list%box(id)%e%extends_id = base
            call inherit(p, base)
            parent_items = [p%list%box(base)%e%more%inherited, p%list%box(base)%e%children]
            do k = 1, size(parent_items)
                item = parent_items(k)
                associate (e => p%list%box(item)%e)
                    select case (e%kind)
                    case (E_VARIABLE)
                        if (e%permission == 'public') call push_int(p%list%box(id)%e%more%inherited, item)
                    case (E_BOUNDPROC)
                        if (e%permission == 'private') cycle
                        if (overrides(p, id, e%name)) cycle
                        if (e%generic) then
                            copy = copy_binding(p, item, id)
                        else
                            call push_int(p%list%box(id)%e%more%inherited, item)
                        end if
                    end select
                end associate
            end do
        end if
    end if
    p%list%box(id)%e%inherit_state = 2
end subroutine inherit

!> True if type `id` declares a binding named `name` itself.
logical function overrides(p, id, name)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: id               !! the type
    character(len=*), intent(in) :: name    !! the binding
    integer :: c, child

    overrides = .false.
    do c = 1, size(p%list%box(id)%e%children)
        child = p%list%box(id)%e%children(c)
        if (p%list%box(child)%e%kind /= E_BOUNDPROC) cycle
        if (lowercase(p%list%box(child)%e%name) == lowercase(name)) then
            overrides = .true.
            return
        end if
    end do
end function overrides

!> Add to type `id` a copy of generic binding `item`, returning the copy.
integer function copy_binding(p, item, id) result(copy)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: item             !! the binding
    integer, intent(in) :: id               !! the type
    integer :: file

    copy = p%list%add(E_BOUNDPROC, id)
    file = p%list%box(copy)%e%file
    p%list%box(copy)%e = p%list%box(item)%e
    if (p%list%box(item)%e%kind /= E_VARIABLE) allocate (p%list%box(copy)%e%more, source=p%list%box(item)%e%more)
    p%list%box(copy)%e%parent = id
    p%list%box(copy)%e%file = file
end function copy_binding

!> Give a procedure or interface named like type `id`, its constructor, the type's permission.
subroutine set_constructor(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the type
    integer :: c, child, parent

    parent = p%list%box(id)%e%parent
    do c = 1, size(p%list%box(parent)%e%children)
        child = p%list%box(parent)%e%children(c)
        associate (e => p%list%box(child)%e)
            select case (e%kind)
            case (E_INTERFACE, E_SUBROUTINE, E_FUNCTION)
                if (lowercase(e%name) == lowercase(p%list%box(id)%e%name)) e%permission = p%list%box(id)%e%permission
            end select
        end associate
    end do
end subroutine set_constructor

!> Add `name` for entity `id` to `list`, replacing any entity it has.
subroutine add_symbol(list, name, id)
    type(symbol_list_t), intent(inout) :: list  !! the names
    character(len=*), intent(in) :: name        !! the name
    integer, intent(in) :: id                   !! the entity
    type(symbol_t), allocatable :: grown(:)
    integer :: k, at

    at = index_find(list%index, name)
    if (at > 0) then
        list%s(at)%id = id
        return
    end if
    if (list%n == size(list%s)) then
        allocate (grown(2*list%n))
        do k = 1, list%n
            call move_alloc(list%s(k)%name, grown(k)%name)
            grown(k)%id = list%s(k)%id
        end do
        call move_alloc(grown, list%s)
    end if
    list%n = list%n + 1
    list%s(list%n)%name = name
    list%s(list%n)%id = id
    call index_set(list%index, name, list%n)
end subroutine add_symbol

!> The position in `p%modules` of the module named `name`, or 0.
integer function find_module(p, name)
    type(project_t), intent(in) :: p        !! the project
    character(len=*), intent(in) :: name    !! the name, in lowercase
    integer :: k

    find_module = 0
    do k = 1, size(p%modules)
        if (lowercase(p%list%box(p%modules(k))%e%name) == name) then
            find_module = k
            return
        end if
    end do
end function find_module

!> Compute the public names of module `which`, after those of the modules it uses.
recursive subroutine public_names(p, which)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: which            !! position in `p%modules`
    integer :: id, c, child, u, used

    if (p%pub(which)%state /= 0) return
    p%pub(which)%state = 1
    id = p%modules(which)
    allocate (p%pub(which)%procs%s(16), p%pub(which)%absints%s(16), p%pub(which)%types%s(16), p%pub(which)%vars%s(16))
    do c = 1, size(p%list%box(id)%e%more%public_list)
        call index_set(p%pub(which)%public_list, p%list%box(id)%e%more%public_list(c)%s, c)
    end do

    associate (m => p%list%box(id)%e)
        do c = 1, size(m%children)
            child = m%children(c)
            associate (e => p%list%box(child)%e)
                if (.not. allocated(e%permission)) cycle
                if (e%permission /= 'public' .and. e%permission /= 'protected') cycle
                select case (e%kind)
                case (E_TYPE)
                    call add_symbol(p%pub(which)%types, lowercase(e%name), child)
                case (E_VARIABLE)
                    if (e%var_role == VAR_HIDDEN) cycle
                    call add_symbol(p%pub(which)%vars, lowercase(e%name), child)
                    if (e%vartype == 'procedure') call add_symbol(p%pub(which)%procs, lowercase(e%name), child)
                case (E_SUBROUTINE, E_FUNCTION)
                    if (e%iface == IFACE_ABSTRACT) then
                        call add_symbol(p%pub(which)%absints, lowercase(e%name), child)
                    else
                        call add_symbol(p%pub(which)%procs, lowercase(e%name), child)
                    end if
                case (E_INTERFACE)
                    call add_symbol(p%pub(which)%procs, lowercase(e%name), child)
                end select
            end associate
        end do
    end associate
    call generic_bodies(p, which, id)

    do u = 1, size(p%list%box(id)%e%more%uses)
        used = module_position(p, p%list%box(id)%e%more%uses(u)%target)
        if (used == 0) cycle
        if (p%pub(used)%state == 1) cycle
        call public_names(p, used)
        call import_names(p, which, used, p%list%box(id)%e%more%uses(u)%spec)
    end do
    p%pub(which)%state = 2
end subroutine public_names

!> Add the public bodies of the generic interfaces of module `id`.
subroutine generic_bodies(p, which, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: which            !! position in `p%modules`
    integer, intent(in) :: id               !! the module
    integer :: c, b, child, body

    do c = 1, size(p%list%box(id)%e%children)
        child = p%list%box(id)%e%children(c)
        if (p%list%box(child)%e%kind /= E_INTERFACE) cycle
        do b = 1, size(p%list%box(child)%e%children)
            body = p%list%box(child)%e%children(b)
            associate (e => p%list%box(body)%e)
                if (.not. is_procedure(e%kind)) cycle
                if (e%permission == 'public' .or. e%permission == 'protected') then
                    call add_symbol(p%pub(which)%procs, lowercase(e%name), body)
                end if
            end associate
        end do
    end do
end subroutine generic_bodies

!> Add to module `which` what it makes public of what `use` with `spec` imports from module `used`.
subroutine import_names(p, which, used, spec)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: which            !! position in `p%modules` of the importing module
    integer, intent(in) :: used             !! position in `p%modules` of the used module
    character(len=*), intent(in) :: spec    !! what follows the module name
    type(rename_t), allocatable :: renames(:)
    type(name_index_t) :: wanted
    logical :: only
    integer :: k

    call read_use_spec(spec, only, renames)
    do k = size(renames), 1, -1
        call index_set(wanted, renames(k)%used, k)
    end do
    call import_category(p%pub(used)%procs, p%pub(which)%procs)
    call import_category(p%pub(used)%absints, p%pub(which)%absints)
    call import_category(p%pub(used)%types, p%pub(which)%types)
    call import_category(p%pub(used)%vars, p%pub(which)%vars)

contains

    !> Import the names of one category.
    subroutine import_category(from, to)
        type(symbol_list_t), intent(in) :: from     !! the used module's names
        type(symbol_list_t), intent(inout) :: to    !! the importing module's names
        integer :: k, j

        do k = 1, from%n
            if (.not. only) then
                if (is_public_here(from%s(k)%name)) call add_symbol(to, from%s(k)%name, from%s(k)%id)
                cycle
            end if
            j = index_find(wanted, from%s(k)%name)
            if (j == 0) cycle
            if (is_public_here(renames(j)%local)) call add_symbol(to, renames(j)%local, from%s(k)%id)
        end do
    end subroutine import_category

    !> True if the importing module makes `name` public.
    logical function is_public_here(name)
        character(len=*), intent(in) :: name    !! the name
        is_public_here = p%list%box(p%modules(which))%e%permission == 'public' .or. &
                         index_find(p%pub(which)%public_list, name) > 0
    end function is_public_here

end subroutine import_names

!> Read what follows the module name in a `use` statement.
subroutine read_use_spec(spec, only, renames)
    character(len=*), intent(in) :: spec                    !! the text
    logical, intent(out) :: only                            !! true for an `only` list
    type(rename_t), allocatable, intent(out) :: renames(:)  !! the names used
    character(len=:), allocatable :: text
    type(string_t), allocatable :: items(:)
    integer :: k, at

    allocate (renames(0))
    text = strip(lowercase(spec))
    only = starts_with(text, 'only')
    if (.not. only) return
    at = index(text, ':')
    text = text(at + 1:)
    items = top_split(text, ',')
    do k = 1, size(items)
        at = index(items(k)%s, '=>')
        if (at > 0) then
            renames = [renames, rename_t(strip(items(k)%s(at + 2:)), strip(items(k)%s(:at - 1)))]
        else
            renames = [renames, rename_t(items(k)%s, items(k)%s)]
        end if
    end do
end subroutine read_use_spec

!> Hide what should not be displayed.
subroutine prune(p, s)
    type(project_t), intent(inout) :: p     !! the project
    type(settings_t), intent(in) :: s       !! the settings
    integer :: k

    do k = 1, p%list%n
        associate (e => p%list%box(k)%e)
            if (e%kind == E_NONE .or. e%parent == 0) cycle
            if (.not. allocated(e%permission)) cycle
            associate (parent => p%list%box(e%parent)%e)
                if (e%kind == E_VARIABLE .and. e%var_role /= VAR_PLAIN) cycle
                if (allocated(parent%display) .and. .not. is_program_unit(e%kind)) then
                    if (.not. contains_string(parent%display, e%permission)) e%visible = .false.
                end if
                if (s%hide_undoc .and. size(e%doc) == 0) e%visible = .false.
                if (is_procedure(parent%kind) .and. .not. parent%internals) then
                    e%visible = .false.
                end if
            end associate
        end associate
    end do
end subroutine prune

!> True if entities of `kind` are program units. The permission of a module is what its members get
!> by default, so `display` says nothing about whether the module itself is shown.
pure logical function is_program_unit(kind)
    integer, intent(in) :: kind     !! the kind of entity
    is_program_unit = kind == E_MODULE .or. kind == E_SUBMODULE .or. kind == E_PROGRAM .or. kind == E_BLOCKDATA
end function is_program_unit

end module fdoc_project
 
 
!>>>>> ././src/fdoc_docs.f90
module fdoc_docs
!! Rendering the documentation of every entity from Markdown to HTML.
use fdoc_util
use fdoc_model
use fdoc_settings, only: settings_t, map_entry_t
use fdoc_project, only: project_t
use fdoc_markdown, only: markdown_to_html, markdown_options_t, dedent
use fdoc_urls, only: link_context_t, resolve_link
use fdoc_progress, only: progress_start, progress_tick, progress_finish
implicit none
private

public :: base_options, render_documentation, render_text, collect_abbreviations

contains

!> The Markdown options of a project.
subroutine base_options(s, root, options)
    type(settings_t), intent(in) :: s                   !! the settings
    character(len=*), intent(in) :: root                !! from the pages to the root of the site
    type(markdown_options_t), intent(out) :: options    !! the options
    integer :: k
    character(len=:), allocatable :: url

    url = root
    options%aliases = [s%alias, s%external, map_entry_t('url', url), map_entry_t('media', url//'/media'), &
                       map_entry_t('page', url//'/page')]
    options%base_path = s%md_base_dir
    options%resolver => resolve_link
    do k = 1, size(s%md_extensions)
        select case (s%md_extensions(k)%s)
        case ('markdown.extensions.toc', 'toc')
            options%toc = .true.
        case ('markdown.extensions.smarty', 'smarty')
            options%smarty = .true.
        end select
    end do
end subroutine base_options

!> Make the abbreviations defined in any documentation apply everywhere, as they do in FORD.
subroutine collect_abbreviations(p, options)
    type(project_t), intent(in) :: p                    !! the project
    type(markdown_options_t), intent(inout) :: options  !! the options
    type(map_entry_t), allocatable :: found(:)
    integer :: k, j, at

    allocate (found(0))
    do k = 1, p%list%n
        if (.not. allocated(p%list%box(k)%e%doc)) cycle
        associate (doc => p%list%box(k)%e%doc)
            do j = 1, size(doc)
                if (.not. starts_with(strip(doc(j)%s), '*[')) cycle
                at = index(doc(j)%s, ']:')
                if (at == 0) cycle
                found = [found, map_entry_t(doc(j)%s(index(doc(j)%s, '*[') + 2:at - 1), strip(doc(j)%s(at + 2:)))]
            end do
        end associate
    end do
    if (size(found) > 0) options%abbreviations = found
end subroutine collect_abbreviations

!> Render `text`, as if it belonged to entity `context`, for a page `prefix` away from the root.
subroutine render_text(p, base, context, prefix, text, html)
    type(project_t), intent(inout), target :: p         !! the project
    type(markdown_options_t), intent(in) :: base        !! the Markdown options
    integer, intent(in) :: context                      !! the entity, or 0
    character(len=*), intent(in) :: prefix              !! from the page to the root of the site
    character(len=*), intent(in) :: text                !! the Markdown
    character(len=:), allocatable, intent(out) :: html  !! the HTML
    type(markdown_options_t) :: options
    type(link_context_t), target :: link

    options = base
    link%list => p%list
    link%entity = context
    link%prefix = prefix
    options%resolver_data => link
    call markdown_to_html(text, options, html)
end subroutine render_text

!> The first paragraph of `html`, or `''`.
pure subroutine first_paragraph(html, out)
    character(len=*), intent(in) :: html                !! the HTML
    character(len=:), allocatable, intent(out) :: out   !! the paragraph
    integer :: a, b

    out = ''
    a = index(html, '<p>')
    if (a == 0) a = index(html, '<p ')
    if (a == 0) return
    b = index(html(a:), '</p>')
    if (b > 0) out = html(a:a + b + 2)
end subroutine first_paragraph

!> Render the documentation and summary of each entity.
subroutine render_documentation(p, s, options)
    type(project_t), intent(inout), target :: p         !! the project
    type(settings_t), intent(in) :: s                   !! the settings
    type(markdown_options_t), intent(in) :: options     !! the Markdown options
    integer :: k

    call progress_start('Converting Markdown', p%list%n)
    !$omp parallel do schedule(dynamic, 16) num_threads(max(1, s%parallel)) default(shared)
    do k = 1, p%list%n
        call render_entity(p, options, k)
        call progress_tick()
    end do
    !$omp end parallel do
    call progress_finish()
end subroutine render_documentation

!> Render the documentation and summary of entity `id`.
subroutine render_entity(p, options, id)
    type(project_t), intent(inout), target :: p         !! the project
    type(markdown_options_t), intent(in) :: options     !! the Markdown options
    integer, intent(in) :: id                           !! the entity
    type(string_t), allocatable :: lines(:)
    integer :: k

    if (.not. allocated(p%list%box(id)%e%doc)) return
    if (p%list%box(id)%e%kind == E_NONE) return
    associate (e => p%list%box(id)%e)
        lines = e%doc
        call dedent(lines)
        call render_text(p, options, id, '../', join(lines, achar(10)), e%html)
        do k = 1, size(e%meta)
            if (e%meta(k)%key /= 'summary') cycle
            call render_text(p, options, id, '../', join(split_words(join(e%meta(k)%values, ' ')), ' '), e%summary)
        end do
        if (.not. allocated(e%summary)) call first_paragraph(e%html, e%summary)
    end associate
end subroutine render_entity

end module fdoc_docs
 
 
!>>>>> ././src/fdoc_graphs.f90
module fdoc_graphs
!! Dependency graphs: which modules use which, what procedures call, how types extend each other and
!! how files depend on each other. Graphs are laid out and drawn by fdot, in parallel, each by one
!! thread.
use fdoc_util
use fdoc_buffer
use fdoc_model
use fdoc_settings, only: settings_t
use fdoc_project, only: project_t
use fdoc_urls, only: entity_url
use fdoc_progress, only: progress_start, progress_tick, progress_finish, warn
use fdoc_shell, only: make_directory
use fdot, only: layout_t => graph_t, RANK_LR, RANK_RL, FDOT_OK
implicit none
private

public :: graph_set_t, build_graphs

integer, parameter, public :: REL_USES = 1       !! modules used
integer, parameter, public :: REL_CALLS = 2      !! procedures called
integer, parameter, public :: REL_INHERITS = 3   !! types extended
integer, parameter, public :: REL_FILES = 4      !! files depended on
integer, parameter :: NUM_RELATIONS = 4

character(len=*), parameter :: EDGE_COLOURS(*) = [character(len=7) :: '#3657c9', '#1d7a55', '#a15c00', '#b3261e', &
                                                  '#6a4fb3', '#0b7285', '#a61e69', '#5c6f2d']

type :: int_list_t
    !! A list of entities.
    integer, allocatable :: ids(:)              !! the entities
end type int_list_t

type :: label_list_t
    !! Labels of edges.
    type(string_t), allocatable :: text(:)      !! the label of each edge, `''` for a solid edge
end type label_list_t

type :: adjacency_t
    !! Each direction of one relation, for each entity.
    type(int_list_t), allocatable :: out(:)     !! what each entity points to
    type(int_list_t), allocatable :: in(:)      !! what points to each entity
    type(label_list_t), allocatable :: labels(:)    !! the labels of `out`
end type adjacency_t

type :: graph_t
    !! A graph of a page.
    character(len=:), allocatable :: title      !! its heading
    character(len=:), allocatable :: svg        !! its drawing
    integer :: owner = 0                        !! the entity whose page shows it, or 0
    integer :: list_page = 0                    !! the list page that shows it, or 0
end type graph_t

type :: graph_set_t
    !! The graphs of a project.
    type(graph_t), allocatable :: graphs(:)     !! the graphs
end type graph_set_t

type :: graph_job_t
    !! A graph waiting to be drawn.
    integer, allocatable :: roots(:)            !! where to start
    character(len=:), allocatable :: title      !! its heading
    integer :: relation = 0                     !! the relation
    logical :: forward = .true.                 !! true to follow edges forward
    integer :: max_depth = 0                    !! how many hops to follow
    integer :: max_nodes = 0                    !! how many nodes to allow
    integer :: direction = RANK_LR              !! which way ranks go
    integer :: owner = 0                        !! the entity whose page shows it, or 0
    integer :: list_page = 0                    !! the list page that shows it, or 0
end type graph_job_t

type :: walk_t
    !! The working space of one thread, sized once, for finding what a graph holds.
    integer, allocatable :: marked(:)           !! when each entity was last reached
    integer, allocatable :: places(:)           !! the number of each entity in the graph
    integer, allocatable :: queue(:)            !! the entities reached
    integer, allocatable :: levels(:)           !! the hops to each of `queue`
    integer, allocatable :: from(:)             !! where each edge starts
    integer, allocatable :: to(:)               !! where each edge ends
    integer :: stamp = 0                        !! a number new for each graph
end type walk_t

contains

!> Build the relations between entities.
subroutine build_relations(p, relations)
    type(project_t), intent(in) :: p                        !! the project
    type(adjacency_t), intent(out) :: relations(NUM_RELATIONS)  !! the relations
    integer, allocatable :: seen(:)
    logical, allocatable :: done(:)
    logical :: changed
    integer :: r, k, j, target, seen_stamp

    allocate (seen(p%list%n))
    seen = 0
    seen_stamp = 0
    do r = 1, NUM_RELATIONS
        allocate (relations(r)%out(p%list%n), relations(r)%in(p%list%n), relations(r)%labels(p%list%n))
    end do
    do k = 1, p%list%n
        associate (e => p%list%box(k)%e)
            if (e%kind == E_NONE) cycle
            if (allocated(e%more%uses)) then
                do j = 1, size(e%more%uses)
                    if (e%more%uses(j)%target > 0) call connect(relations(REL_USES), k, e%more%uses(j)%target)
                end do
            end if
            if (e%kind == E_SUBMODULE) then
                if (e%parent_submodule_id > 0) then
                    call connect(relations(REL_USES), k, e%parent_submodule_id)
                else if (e%ancestor_id > 0) then
                    call connect(relations(REL_USES), k, e%ancestor_id)
                end if
            end if
            if (e%visible .and. e%kind /= E_BOUNDPROC) then
                seen_stamp = seen_stamp + 1
                call visible_calls(p, k, k, seen, seen_stamp, relations(REL_CALLS))
            end if
            if (allocated(e%more%modproc_ids)) then
                do j = 1, size(e%more%modproc_ids)
                    if (e%more%modproc_ids(j) == 0) cycle
                    if (p%list%box(e%more%modproc_ids(j))%e%visible) call connect(relations(REL_CALLS), k, e%more%modproc_ids(j))
                end do
            end if
            if (e%kind == E_INTERFACE) then
                do j = 1, size(e%children)
                    if (p%list%box(e%children(j))%e%visible) call connect(relations(REL_CALLS), k, e%children(j))
                end do
            end if
            if (e%extends_id > 0) call connect(relations(REL_INHERITS), k, e%extends_id)
            if (e%kind == E_TYPE .and. e%visible) then
                do j = 1, size(e%children)
                    associate (c => p%list%box(e%children(j))%e)
                        if (c%kind /= E_VARIABLE .or. c%proto_id == 0) cycle
                        if (p%list%box(c%proto_id)%e%kind == E_TYPE) then
                            call connect(relations(REL_INHERITS), k, c%proto_id, c%name)
                        end if
                    end associate
                end do
            end if
            if (e%file > 0 .and. allocated(e%more%uses)) then
                do j = 1, size(e%more%uses)
                    target = e%more%uses(j)%target
                    if (target == 0) cycle
                    target = p%list%box(target)%e%file
                    if (target > 0 .and. target /= e%file) call connect(relations(REL_FILES), e%file, target)
                end do
            end if
        end associate
    end do

    ! a generic binding is a node only once something refers to it
    allocate (done(p%list%n))
    done = .false.
    changed = .true.
    do while (changed)
        changed = .false.
        do k = 1, p%list%n
            if (done(k) .or. p%list%box(k)%e%kind /= E_BOUNDPROC) cycle
            if (.not. allocated(relations(REL_CALLS)%in(k)%ids)) cycle
            done(k) = .true.
            changed = .true.
            seen_stamp = seen_stamp + 1
            call visible_calls(p, k, k, seen, seen_stamp, relations(REL_CALLS))
        end do
    end do
end subroutine build_relations

!> True if a graph shows binding `id` as the procedure it binds: it binds one, which can be shown.
logical function is_simple_binding(p, id)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: id           !! the entity

    is_simple_binding = .false.
    associate (e => p%list%box(id)%e)
        if (e%kind /= E_BOUNDPROC .or. .not. allocated(e%more%binding_ids)) return
        if (size(e%more%binding_ids) /= 1) return
        if (e%deferred) then
            is_simple_binding = .true.
        else if (e%more%binding_ids(1) > 0) then
            is_simple_binding = p%list%box(e%more%binding_ids(1))%e%kind /= E_BOUNDPROC .and. &
                                p%list%box(e%more%binding_ids(1))%e%visible
        end if
    end associate
end function is_simple_binding

!> Add edges from `from` to what `id` calls. What cannot be shown is replaced by what it calls.
recursive subroutine visible_calls(p, id, from, seen, stamp, relation)
    type(project_t), intent(in) :: p                !! the project
    integer, intent(in) :: id                       !! the entity whose calls to follow
    integer, intent(in) :: from                     !! where the edges start
    integer, intent(inout) :: seen(:)               !! when each entity was last visited
    integer, intent(in) :: stamp                    !! a number new for each `from`
    type(adjacency_t), intent(inout) :: relation    !! the relation
    integer :: j

    associate (e => p%list%box(id)%e)
        if (allocated(e%call_ids)) then
            do j = 1, size(e%call_ids)
                call visit(e%call_ids(j))
            end do
        end if
        if (allocated(e%more%binding_ids)) then
            do j = 1, size(e%more%binding_ids)
                if (e%more%binding_ids(j) > 0) call visit(e%more%binding_ids(j))
            end do
        end if
    end associate

contains

    !> Handle a call to `target`.
    recursive subroutine visit(target)
        integer, intent(in) :: target   !! what is called

        if (seen(target) == stamp) return
        seen(target) = stamp
        if (p%list%box(target)%e%visible .and. .not. is_simple_binding(p, target)) then
            call connect(relation, from, target)
        else
            call visible_calls(p, target, from, seen, stamp, relation)
        end if
    end subroutine visit

end subroutine visible_calls

!> Add an edge, once. With `label`, the edge is dashed and labelled: components of a type have one.
subroutine connect(relation, from, to, label)
    type(adjacency_t), intent(inout) :: relation    !! the relation
    integer, intent(in) :: from                     !! where it starts
    integer, intent(in) :: to                       !! where it ends
    character(len=*), intent(in), optional :: label !! its label
    integer :: k

    if (from == to .and. .not. present(label)) return
    if (allocated(relation%out(from)%ids)) then
        do k = 1, size(relation%out(from)%ids)
            if (relation%out(from)%ids(k) /= to) cycle
            if (present(label)) then
                if (len(relation%labels(from)%text(k)%s) > 0) then
                    relation%labels(from)%text(k)%s = relation%labels(from)%text(k)%s//', '//label
                end if
            end if
            return
        end do
    end if
    call push_int(relation%out(from)%ids, to)
    call push_int(relation%in(to)%ids, from)
    if (present(label)) then
        call push(relation%labels(from)%text, label)
    else
        call push(relation%labels(from)%text, '')
    end if
end subroutine connect

!> True if entity `id` is drawn with graphs.
logical function graphs_wanted(p, s, id, depth, nodes)
    type(project_t), intent(in) :: p    !! the project
    type(settings_t), intent(in) :: s   !! the settings
    integer, intent(in) :: id           !! the entity
    integer, intent(out) :: depth       !! its `graph_maxdepth`
    integer, intent(out) :: nodes       !! its `graph_maxnodes`
    logical :: flag, ok
    integer :: k, value

    graphs_wanted = s%graph
    depth = s%graph_maxdepth
    nodes = s%graph_maxnodes
    associate (e => p%list%box(id)%e)
        if (.not. allocated(e%meta)) return
        do k = 1, size(e%meta)
            select case (e%meta(k)%key)
            case ('graph')
                call parse_bool(e%meta(k)%values(1)%s, flag, ok)
                if (ok) graphs_wanted = flag
            case ('graph_maxdepth')
                call parse_int(e%meta(k)%values(1)%s, value, ok)
                if (ok) depth = value
            case ('graph_maxnodes')
                call parse_int(e%meta(k)%values(1)%s, value, ok)
                if (ok) nodes = value
            end select
        end do
    end associate
end function graphs_wanted

!> Put the graph of `job` in `g`. `found` is false if it would have only one node or no edges. Nodes go
!> in as they are reached, and edges after them.
subroutine describe_graph(p, s, relation, job, w, g, found)
    type(project_t), intent(in) :: p        !! the project
    type(settings_t), intent(in) :: s       !! the settings
    type(adjacency_t), intent(in) :: relation   !! the relation
    type(graph_job_t), intent(in) :: job    !! the graph
    type(walk_t), intent(inout) :: w        !! the working space
    type(layout_t), intent(out) :: g        !! the description
    logical, intent(out) :: found           !! whether there is a graph
    integer, allocatable :: next(:)
    integer :: head, k, id, other, j, reached, edges

    w%stamp = w%stamp + 1
    reached = size(job%roots)
    do k = 1, reached
        w%marked(job%roots(k)) = w%stamp
        w%queue(k) = job%roots(k)
        w%levels(k) = 0
    end do
    head = 1
    edges = 0
    do while (head <= reached)
        id = w%queue(head)
        if (w%levels(head) < job%max_depth) then
            if (job%forward) then
                if (allocated(relation%out(id)%ids)) then
                    next = relation%out(id)%ids
                else
                    allocate (next(0))
                end if
            else
                if (allocated(relation%in(id)%ids)) then
                    next = relation%in(id)%ids
                else
                    allocate (next(0))
                end if
            end if
            do j = 1, size(next)
                other = next(j)
                if (p%list%box(other)%e%kind == E_NONE) cycle
                if (w%marked(other) /= w%stamp) then
                    if (reached >= job%max_nodes) cycle
                    w%marked(other) = w%stamp
                    reached = reached + 1
                    w%queue(reached) = other
                    w%levels(reached) = w%levels(head) + 1
                end if
                edges = edges + 1
                if (edges > size(w%from)) call grow_edges(w)
                w%from(edges) = merge(id, other, job%forward)
                w%to(edges) = merge(other, id, job%forward)
            end do
            deallocate (next)
        end if
        head = head + 1
    end do
    found = reached > 1 .and. edges > 0
    if (.not. found) return
    call g%initialize(direction=job%direction, concentrate=.true.)
    do k = 1, reached
        call add_node(p, w%queue(k), k == 1 .and. size(job%roots) == 1, g, w%places(w%queue(k)))
    end do
    do k = 1, edges
        call add_edge(s, relation, w%from(k), w%to(k), w%places, g)
    end do
end subroutine describe_graph

!> Make room for more edges.
pure subroutine grow_edges(w)
    type(walk_t), intent(inout) :: w    !! the working space
    integer, allocatable :: grown(:)
    integer :: n

    n = size(w%from)
    allocate (grown(2*n))
    grown(1:n) = w%from
    call move_alloc(grown, w%from)
    allocate (grown(2*n))
    grown(1:n) = w%to
    call move_alloc(grown, w%to)
end subroutine grow_edges

!> Add node `id` to a description.
subroutine add_node(p, id, root, g, place)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: id           !! the entity
    logical, intent(in) :: root         !! true for the entity the graph is about
    type(layout_t), intent(inout) :: g  !! the description
    integer, intent(out) :: place       !! its number in `g`
    character(len=:), allocatable :: url, colour, name, outline
    integer :: at

    associate (e => p%list%box(id)%e)
        select case (e%kind)
        case (E_MODULE); colour = '#3657c9'
        case (E_SUBMODULE); colour = '#5a78de'
        case (E_PROGRAM); colour = '#a61e69'
        case (E_SUBROUTINE); colour = '#1d7a55'
        case (E_FUNCTION); colour = '#0b7285'
        case (E_INTERFACE, E_MODPROC); colour = '#6a4fb3'
        case (E_TYPE); colour = '#a15c00'
        case (E_BOUNDPROC); colour = '#7a6a2d'
        case (E_FILE); colour = '#5c6f2d'
        case default; colour = '#646d7e'
        end select
        name = e%name
        if (e%kind == E_FILE) then
            at = last_separator(name)
            name = name(at + 1:)
        end if
        if (e%kind == E_BOUNDPROC) name = p%list%box(e%parent)%e%name//'%'//name
        if (e%bound_to > 0) name = p%list%box(e%bound_to)%e%name//'%'//name
        url = ''
        if (e%visible .or. allocated(e%external_url)) call entity_url(p%list, id, url)
        if (.not. e%visible .and. .not. allocated(e%external_url)) colour = '#8a93a5'
        if (allocated(e%external_url)) colour = '#646d7e'
        if (len(url) > 0 .and. .not. allocated(e%external_url)) url = '../'//url
        outline = ''
        if (root) outline = '#f0a868'
        call g%add_node(name, place, fill=colour, link=url, outline=outline)
    end associate
end subroutine add_node

!> Add an edge to a description.
subroutine add_edge(s, relation, from, to, places, g)
    type(settings_t), intent(in) :: s           !! the settings
    type(adjacency_t), intent(in) :: relation   !! the relation
    integer, intent(in) :: from                 !! where it starts
    integer, intent(in) :: to                   !! where it ends
    integer, intent(in) :: places(:)            !! the number in `g` of each entity
    type(layout_t), intent(inout) :: g          !! the description
    character(len=:), allocatable :: label
    integer :: k

    label = ''
    do k = 1, size(relation%out(from)%ids)
        if (relation%out(from)%ids(k) /= to) cycle
        label = relation%labels(from)%text(k)%s
        exit
    end do
    if (s%coloured_edges) then
        call g%add_edge(places(from), places(to), colour=EDGE_COLOURS(mod(from, size(EDGE_COLOURS)) + 1), label=label)
    else
        call g%add_edge(places(from), places(to), label=label)
    end if
end subroutine add_edge

!> Build the graphs of the project: those of `s%graph`, and of entities that ask for them.
subroutine build_graphs(p, s, members, list_codes, set, stat, errmsg)
    type(project_t), intent(in) :: p                    !! the project
    type(settings_t), intent(in) :: s                   !! the settings
    integer, intent(in) :: members(:)                   !! the entities that have pages
    integer, intent(in) :: list_codes(4)                !! the list pages of files, modules, procedures, types
    type(graph_set_t), intent(out) :: set               !! the graphs
    integer, intent(out) :: stat                        !! nonzero on failure
    character(len=:), allocatable, intent(out) :: errmsg !! what is wrong
    type(adjacency_t) :: relations(NUM_RELATIONS)
    type(graph_job_t), allocatable :: jobs(:)
    type(string_t), allocatable :: drawings(:), descriptions(:)
    logical, allocatable :: failed(:)
    integer, allocatable :: roots(:)
    character(len=:), allocatable :: directory
    character(len=32) :: tag
    logical :: any_wanted, keep
    integer :: k, m, n, depth, nodes, status, count_jobs

    stat = 0
    allocate (set%graphs(0))
    any_wanted = s%graph
    do k = 1, p%list%n
        if (.not. allocated(p%list%box(k)%e%meta)) cycle
        if (any([(p%list%box(k)%e%meta(n)%key == 'graph', n=1, size(p%list%box(k)%e%meta))])) any_wanted = .true.
    end do
    if (.not. any_wanted) return

    call progress_start('Finding dependencies', size(members))
    call build_relations(p, relations)
    allocate (jobs(0))
    count_jobs = 0
    do k = 1, size(members)
        call progress_tick()
        associate (id => members(k))
            if (.not. graphs_wanted(p, s, id, depth, nodes)) cycle
            select case (p%list%box(id)%e%kind)
            case (E_MODULE, E_SUBMODULE)
                call one(id, REL_USES, .true., 'Uses', RANK_RL)
                call one(id, REL_USES, .false., 'Used by', RANK_RL)
            case (E_TYPE)
                call one(id, REL_INHERITS, .true., 'Inherits', RANK_RL)
                call one(id, REL_INHERITS, .false., 'Inherited by', RANK_RL)
            case (E_SUBROUTINE, E_FUNCTION, E_MODPROC, E_INTERFACE)
                call one(id, REL_CALLS, .true., 'Calls', RANK_LR)
                call one(id, REL_CALLS, .false., 'Called by', RANK_RL)
            case (E_PROGRAM)
                call one(id, REL_CALLS, .true., 'Calls', RANK_LR)
                call one(id, REL_USES, .true., 'Uses', RANK_RL)
            case (E_BLOCKDATA)
                call one(id, REL_USES, .true., 'Uses', RANK_RL)
            case (E_FILE)
                call one(id, REL_FILES, .true., 'Files this one depends on', RANK_RL)
                call one(id, REL_FILES, .false., 'Files that depend on this one', RANK_RL)
            end select
        end associate
    end do
    if (s%graph) then
        call project_graph([E_MODULE, E_SUBMODULE], REL_USES, list_codes(2), 'Module graph')
        call project_graph([E_TYPE], REL_INHERITS, list_codes(4), 'Type graph')
        call project_graph([E_SUBROUTINE, E_FUNCTION, E_PROGRAM, E_INTERFACE], REL_CALLS, list_codes(3), 'Call graph')
        call project_graph([E_FILE], REL_FILES, list_codes(1), 'File graph')
    end if
    call progress_finish()

    n = count_jobs
    if (n == 0) return
    keep = allocated(s%graph_dir)
    allocate (drawings(n), descriptions(n), failed(n))
    call draw_graphs(p, s, relations, jobs(1:n), keep, drawings, descriptions, failed, max(1, s%parallel))

    if (keep) then
        call unique_tag(tag)
        ! a directory of this run's own, as the names of the files inside are the same in every run
        directory = s%graph_dir//'/'//trim(tag)
        call make_directory(directory, status)
    end if
    deallocate (set%graphs)
    allocate (set%graphs(count([(allocated(drawings(k)%s), k=1, n)])))
    m = 0
    do k = 1, n
        if (failed(k)) call warn('no layout for a graph of '//jobs(k)%title)
        if (.not. allocated(drawings(k)%s)) cycle
        m = m + 1
        if (keep) then
            call write_whole_file(directory//'/g'//trim(int_text(m))//'.gv', descriptions(k)%s, stat, errmsg)
            if (stat /= 0) return
            call write_whole_file(directory//'/g'//trim(int_text(m))//'.gv.svg', drawings(k)%s, stat, errmsg)
            if (stat /= 0) return
        end if
        call move_alloc(drawings(k)%s, set%graphs(m)%svg)
        call move_alloc(jobs(k)%title, set%graphs(m)%title)
        set%graphs(m)%owner = jobs(k)%owner
        set%graphs(m)%list_page = jobs(k)%list_page
    end do

contains

    !> Add a graph of the page of `id`.
    subroutine one(id, relation, forward, title, direction)
        integer, intent(in) :: id                   !! the entity
        integer, intent(in) :: relation             !! the relation
        logical, intent(in) :: forward              !! true to follow edges forward
        character(len=*), intent(in) :: title       !! the heading
        integer, intent(in) :: direction            !! which way ranks go

        call add_job([id], relation, forward, depth, nodes, direction, title, id, 0)
    end subroutine one

    !> Add the graph of a whole relation to a list page.
    subroutine project_graph(kinds, relation, page, title)
        integer, intent(in) :: kinds(:)         !! the kinds of entity
        integer, intent(in) :: relation         !! the relation
        integer, intent(in) :: page             !! the list page
        character(len=*), intent(in) :: title   !! the heading
        integer :: j

        allocate (roots(0))
        do j = 1, size(members)
            if (p%list%box(members(j))%e%iface == IFACE_ABSTRACT) cycle
            if (any(p%list%box(members(j))%e%kind == kinds)) call push_int(roots, members(j))
        end do
        if (size(roots) > s%graph_project_maxnodes) then
            call warn(title//' left out: it would have more than '//trim(int_text(s%graph_project_maxnodes))// &
                      ' nodes (see graph_project_maxnodes)')
        else if (size(roots) > 1) then
            call add_job(roots, relation, .true., 1, huge(1), RANK_RL, title, 0, page)
        end if
        deallocate (roots)
    end subroutine project_graph

    !> Add a graph to the list.
    subroutine add_job(start, relation, forward, max_depth, max_nodes, direction, title, owner, page)
        integer, intent(in) :: start(:)         !! where to start
        integer, intent(in) :: relation         !! the relation
        logical, intent(in) :: forward          !! true to follow edges forward
        integer, intent(in) :: max_depth        !! how many hops to follow
        integer, intent(in) :: max_nodes        !! how many nodes to allow
        integer, intent(in) :: direction        !! which way ranks go
        character(len=*), intent(in) :: title   !! its heading
        integer, intent(in) :: owner            !! the entity whose page shows it, or 0
        integer, intent(in) :: page             !! the list page that shows it, or 0
        type(graph_job_t), allocatable :: grown(:)
        integer :: j

        if (count_jobs == size(jobs)) then
            allocate (grown(max(64, 2*count_jobs)))
            do j = 1, count_jobs
                call move_alloc(jobs(j)%roots, grown(j)%roots)
                call move_alloc(jobs(j)%title, grown(j)%title)
                grown(j)%relation = jobs(j)%relation
                grown(j)%forward = jobs(j)%forward
                grown(j)%max_depth = jobs(j)%max_depth
                grown(j)%max_nodes = jobs(j)%max_nodes
                grown(j)%direction = jobs(j)%direction
                grown(j)%owner = jobs(j)%owner
                grown(j)%list_page = jobs(j)%list_page
            end do
            call move_alloc(grown, jobs)
        end if
        count_jobs = count_jobs + 1
        associate (job => jobs(count_jobs))
            job%roots = start
            job%title = title
            job%relation = relation
            job%forward = forward
            job%max_depth = max_depth
            job%max_nodes = max_nodes
            job%direction = direction
            job%owner = owner
            job%list_page = page
        end associate
    end subroutine add_job

end subroutine build_graphs

!> Lay out and draw `jobs`. A graph that turns out to have nothing to show gets no drawing.
subroutine draw_graphs(p, s, relations, jobs, keep, drawings, descriptions, failed, threads)
    type(project_t), intent(in) :: p                    !! the project
    type(settings_t), intent(in) :: s                   !! the settings
    type(adjacency_t), intent(in) :: relations(NUM_RELATIONS)   !! the relations
    type(graph_job_t), intent(in) :: jobs(:)            !! the graphs
    logical, intent(in) :: keep                         !! whether to give the descriptions too
    type(string_t), intent(inout) :: drawings(:)        !! the drawing of each graph
    type(string_t), intent(inout) :: descriptions(:)    !! the description of each graph, with `keep`
    logical, intent(out) :: failed(:)                   !! whether the layout of each graph failed
    integer, intent(in) :: threads                      !! how many threads to use

    failed = .false.
    call progress_start('Laying out graphs', size(jobs))
    !$omp parallel num_threads(threads) default(shared)
    call draw_some(p, s, relations, jobs, keep, drawings, descriptions, failed)
    !$omp end parallel
    call progress_finish()
end subroutine draw_graphs

!> The share of [[draw_graphs]] of one thread, with working space of its own.
subroutine draw_some(p, s, relations, jobs, keep, drawings, descriptions, failed)
    type(project_t), intent(in) :: p                    !! the project
    type(settings_t), intent(in) :: s                   !! the settings
    type(adjacency_t), intent(in) :: relations(NUM_RELATIONS)   !! the relations
    type(graph_job_t), intent(in) :: jobs(:)            !! the graphs
    logical, intent(in) :: keep                         !! whether to give the descriptions too
    type(string_t), intent(inout) :: drawings(:)        !! the drawing of each graph
    type(string_t), intent(inout) :: descriptions(:)    !! the description of each graph, with `keep`
    logical, intent(inout) :: failed(:)                 !! whether the layout of each graph failed
    type(walk_t) :: w
    integer :: k

    allocate (w%marked(p%list%n), source=0)
    allocate (w%places(p%list%n), w%queue(p%list%n), w%levels(p%list%n), w%from(1024), w%to(1024))
    !$omp do schedule(dynamic)
    do k = 1, size(jobs)
        call draw_graph(p, s, relations(jobs(k)%relation), jobs(k), keep, w, drawings(k), descriptions(k), failed(k))
        call progress_tick()
    end do
    !$omp end do
end subroutine draw_some

!> Lay out and draw one graph.
subroutine draw_graph(p, s, relation, job, keep, w, drawing, description, failed)
    type(project_t), intent(in) :: p            !! the project
    type(settings_t), intent(in) :: s           !! the settings
    type(adjacency_t), intent(in) :: relation   !! the relation
    type(graph_job_t), intent(in) :: job        !! the graph
    logical, intent(in) :: keep                 !! whether to give the description too
    type(walk_t), intent(inout) :: w            !! the working space
    type(string_t), intent(inout) :: drawing    !! the drawing
    type(string_t), intent(inout) :: description    !! the description, with `keep`
    logical, intent(out) :: failed              !! whether the layout failed
    type(layout_t) :: g
    logical :: found
    integer :: status

    failed = .false.
    call describe_graph(p, s, relation, job, w, g, found)
    if (.not. found) return
    if (keep) call g%write_dot(description%s)
    call g%layout(status)
    failed = status /= FDOT_OK
    if (.not. failed) call g%write_svg(drawing%s)
end subroutine draw_graph

end module fdoc_graphs
 
 
!>>>>> ././src/fdoc_links.f90
module fdoc_links
!! Connecting names to entities: bindings, interfaces, implementations and procedure calls.
use json_module, only: json_core, json_value
use fdoc_util
use fdoc_model
use fdoc_project, only: project_t, find_symbol
use fdoc_progress, only: progress_tick
implicit none
private

public :: link_project, dump_links

contains

!> Connect what the names in the project refer to.
subroutine link_project(p)
    type(project_t), intent(inout) :: p     !! the project
    integer :: k, n

    n = p%list%n
    do k = 1, n
        call progress_tick()
        if (allocated(p%list%box(k)%e%external_url)) cycle
        select case (p%list%box(k)%e%kind)
        case (E_SUBROUTINE, E_FUNCTION, E_MODPROC)
            call link_implementation(p, k)
            call link_calls(p, k)
        case (E_PROGRAM)
            call link_calls(p, k)
        case (E_SUBMODULE)
            call link_submodule(p, k)
        case (E_INTERFACE)
            call link_module_procedures(p, k)
        case (E_BOUNDPROC)
            call link_binding(p, k)
        case (E_TYPE)
            call link_constructor(p, k)
        case (E_FINAL)
            p%list%box(k)%e%proto_id = find_symbol(p, k, lowercase(p%list%box(k)%e%name), 1)
        case (E_VARIABLE)
            call link_variable(p, k)
        end select
    end do
end subroutine link_project

!> Add submodule `id` to the descendants of its parent.
subroutine link_submodule(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the submodule
    integer :: parent

    parent = p%list%box(id)%e%parent_submodule_id
    if (parent == 0) parent = p%list%box(id)%e%ancestor_id
    if (parent > 0) call push_int(p%list%box(parent)%e%more%descendants, id)
end subroutine link_submodule

!> Connect a separate module procedure with its interface, and copy what it does not repeat.
subroutine link_implementation(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the procedure
    integer :: found, parent

    if (p%list%box(id)%e%kind /= E_MODPROC .and. .not. p%list%box(id)%e%is_module) return
    if (p%list%box(id)%e%iface /= IFACE_NONE) return
    parent = p%list%box(id)%e%parent
    found = find_symbol(p, parent, lowercase(p%list%box(id)%e%name), 1)
    if (found == id .or. found == 0) then
        found = 0
        if (p%list%box(parent)%e%parent_submodule_id > 0) then
            found = find_symbol(p, p%list%box(parent)%e%parent_submodule_id, lowercase(p%list%box(id)%e%name), 1)
        else if (p%list%box(parent)%e%ancestor_id > 0) then
            found = find_symbol(p, p%list%box(parent)%e%ancestor_id, lowercase(p%list%box(id)%e%name), 1)
        end if
    end if
    if (found == 0 .or. found == id) return
    p%list%box(id)%e%implements = found
    p%list%box(found)%e%implements = id
    if (p%list%box(id)%e%kind /= E_MODPROC) return
    associate (e => p%list%box(id)%e, base => p%list%box(found)%e)
        if (allocated(base%attribs)) e%attribs = base%attribs
        if (allocated(base%more%args)) e%more%args = base%more%args
        if (allocated(base%more%arg_ids)) e%more%arg_ids = base%more%arg_ids
        e%result = base%result
    end associate
end subroutine link_implementation

!> Find what a generic interface lists with `module procedure`.
subroutine link_module_procedures(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the interface
    integer :: k, found

    allocate (p%list%box(id)%e%more%modproc_ids(size(p%list%box(id)%e%more%modprocs)))
    do k = 1, size(p%list%box(id)%e%more%modprocs)
        found = find_symbol(p, p%list%box(id)%e%parent, lowercase(p%list%box(id)%e%more%modprocs(k)%s), 1)
        p%list%box(id)%e%more%modproc_ids(k) = found
    end do
end subroutine link_module_procedures

!> Find what a type-bound procedure binds to and its interface.
subroutine link_binding(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the binding
    integer :: parent, k, found

    parent = p%list%box(id)%e%parent
    associate (b => p%list%box(id)%e)
        allocate (b%more%binding_ids(size(b%more%bindings)))
        b%more%binding_ids = 0
        if (allocated(b%more%proto_text)) then
            b%proto_id = find_symbol(p, parent, lowercase(b%more%proto_text), 1)
            if (b%proto_id == 0) b%proto_id = find_symbol(p, parent, lowercase(b%more%proto_text), 2)
        end if
        do k = 1, size(b%more%bindings)
            if (b%generic) then
                found = type_binding(p, parent, lowercase(b%more%bindings(k)%s))
            else if (b%deferred) then
                found = 0
            else
                found = find_symbol(p, parent, lowercase(b%more%bindings(k)%s), 1)
                if (found > 0) p%list%box(found)%e%bound_to = parent
            end if
            b%more%binding_ids(k) = found
        end do
    end associate
end subroutine link_binding

!> The binding named `name` of type `id`, including inherited ones, or 0.
integer function type_binding(p, id, name) result(found)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: id               !! the type
    character(len=*), intent(in) :: name    !! the name, in lowercase

    found = type_member(p, id, name, E_BOUNDPROC)
end function type_binding

!> The component of kind `kind` named `name` of type `id`, including inherited ones, or 0.
integer function type_member(p, id, name, kind) result(found)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: id               !! the type
    character(len=*), intent(in) :: name    !! the name, in lowercase
    integer, intent(in) :: kind             !! one of the `E_*` constants
    integer :: k

    found = 0
    associate (e => p%list%box(id)%e)
        ! a generic binding can be declared in several statements: the last counts
        do k = size(e%children), 1, -1
            if (p%list%box(e%children(k))%e%kind /= kind) cycle
            if (lowercase(p%list%box(e%children(k))%e%name) == name) then
                found = e%children(k)
                return
            end if
        end do
        if (.not. allocated(e%more%inherited)) return
        do k = 1, size(e%more%inherited)
            if (p%list%box(e%more%inherited(k))%e%kind /= kind) cycle
            if (lowercase(p%list%box(e%more%inherited(k))%e%name) == name) then
                found = e%more%inherited(k)
                return
            end if
        end do
    end associate
end function type_member

!> Find the procedure or interface named like type `id`.
subroutine link_constructor(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the type

    p%list%box(id)%e%constructor = find_symbol(p, p%list%box(id)%e%parent, lowercase(p%list%box(id)%e%name), 1)
end subroutine link_constructor

!> Find the type or interface that a variable declaration names.
subroutine link_variable(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the variable
    character(len=:), allocatable :: name

    associate (v => p%list%box(id)%e)
        if (.not. allocated(v%proto)) return
        name = lowercase(v%proto(1)%s)
        if (name == '*') return
        if (v%vartype == 'procedure') then
            v%proto_id = find_symbol(p, v%parent, name, 1)
            if (v%proto_id == 0) v%proto_id = find_symbol(p, v%parent, name, 2)
        else
            v%proto_id = find_symbol(p, v%parent, name, 3)
        end if
    end associate
end subroutine link_variable

!> Find what the calls of entity `id` refer to.
subroutine link_calls(p, id)
    type(project_t), intent(inout) :: p     !! the project
    integer, intent(in) :: id               !! the procedure or program
    type(string_t), allocatable :: parts(:)
    integer :: k, item, context, j

    allocate (p%list%box(id)%e%call_ids(0), p%list%box(id)%e%more%unknown_calls(0))
    if (.not. allocated(p%list%box(id)%e%more%calls)) return
    do k = 1, size(p%list%box(id)%e%more%calls)
        parts = split_on(p%list%box(id)%e%more%calls(k)%s, '%')
        context = id
        do j = 1, size(parts) - 1
            context = context_of(p, label_item(p, context, parts(j)%s))
            if (context == 0) exit
        end do
        item = 0
        if (context > 0) item = label_item(p, context, parts(size(parts))%s)
        if (item == 0) then
            call push(p%list%box(id)%e%more%unknown_calls, parts(size(parts))%s)
        else if (p%list%box(item)%e%kind /= E_VARIABLE .and. p%list%box(item)%e%kind /= E_TYPE) then
            call push_int(p%list%box(id)%e%call_ids, item)
        end if
    end do
end subroutine link_calls

!> The entity that `label` means in `context`, a scope or a type, or 0.
integer function label_item(p, context, label) result(item)
    type(project_t), intent(in) :: p        !! the project
    integer, intent(in) :: context          !! the scope or type
    character(len=*), intent(in) :: label   !! the name, in lowercase
    integer :: base, k

    item = 0
    if (p%list%box(context)%e%kind == E_TYPE) then
        item = type_member(p, context, label, E_VARIABLE)
        if (item > 0) return
    end if
    ! the arguments of a separate module procedure are those of its interface
    associate (e => p%list%box(context)%e)
        if (allocated(e%more%arg_ids)) then
            do k = 1, size(e%more%arg_ids)
                if (lowercase(p%list%box(e%more%arg_ids(k))%e%name) == label) then
                    item = e%more%arg_ids(k)
                    return
                end if
            end do
        end if
        if (e%result > 0) then
            if (lowercase(p%list%box(e%result)%e%name) == label) then
                item = e%result
                return
            end if
        end if
    end associate
    item = find_symbol(p, context, label, 4)
    if (item > 0) return
    if (p%list%box(context)%e%kind == E_TYPE) then
        base = p%list%box(context)%e%extends_id
        do while (base > 0)
            if (lowercase(p%list%box(base)%e%name) == label) then
                item = base
                return
            end if
            base = p%list%box(base)%e%extends_id
        end do
    end if
    item = find_symbol(p, context, label, 3)
    if (item > 0) return
    if (p%list%box(context)%e%kind == E_TYPE) then
        item = type_binding(p, context, label)
        if (item > 0) return
    end if
    item = find_symbol(p, context, label, 1)
end function label_item

!> The type whose members a reference through `item` reaches, or 0.
integer function context_of(p, item) result(context)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: item         !! the entity, or 0
    integer :: var

    context = 0
    if (item == 0) return
    select case (p%list%box(item)%e%kind)
    case (E_FUNCTION)
        var = p%list%box(item)%e%result
        if (var > 0) context = variable_type(p, var)
    case (E_TYPE)
        context = item
    case (E_VARIABLE)
        context = variable_type(p, item)
    end select
end function context_of

!> The derived type of variable `id`, or 0.
integer function variable_type(p, id) result(found)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: id           !! the variable

    found = 0
    associate (v => p%list%box(id)%e)
        if (.not. allocated(v%proto)) return
        if (v%vartype /= 'type' .and. v%vartype /= 'class') return
        found = find_symbol(p, v%parent, lowercase(v%proto(1)%s), 3)
    end associate
end function variable_type

!> How entities are connected, as JSON, for comparison with FORD.
function dump_links(p) result(text)
    type(project_t), intent(in) :: p    !! the project
    character(len=:), allocatable :: text
    type(json_core) :: json
    type(json_value), pointer :: root, node
    integer :: k

    call json%initialize()
    call json%create_object(root, '')
    do k = 1, p%list%n
        associate (e => p%list%box(k)%e)
            select case (e%kind)
            case (E_MODULE, E_SUBMODULE, E_PROGRAM, E_SUBROUTINE, E_FUNCTION, E_MODPROC, E_INTERFACE, E_BOUNDPROC, E_TYPE)
                if (allocated(e%external_url) .or. .not. allocated(e%name)) cycle
                if (e%kind == E_BOUNDPROC .and. .not. allocated(e%more%binding_ids)) cycle
                if (e%kind == E_TYPE) then
                    call json%create_object(node, qualified_name(p, k)//'#type')
                else
                    call json%create_object(node, qualified_name(p, k))
                end if
                call json%add(root, node)
                call add_links(json, node, p, k)
            end select
        end associate
    end do
    call json%serialize(root, text)
    call json%destroy(root)
end function dump_links

!> The name of entity `id` with those around it, up to its top-level unit.
recursive function qualified_name(p, id) result(name)
    type(project_t), intent(in) :: p    !! the project
    integer, intent(in) :: id           !! the entity
    character(len=:), allocatable :: name

    name = lowercase(p%list%box(id)%e%name)
    if (p%list%box(id)%e%parent == 0) return
    if (p%list%box(p%list%box(id)%e%parent)%e%kind == E_FILE) return
    name = qualified_name(p, p%list%box(id)%e%parent)//'/'//name
end function qualified_name

!> Add the links of entity `id` to `node`.
subroutine add_links(json, node, p, id)
    type(json_core), intent(inout) :: json          !! the JSON handler
    type(json_value), pointer, intent(in) :: node   !! the object
    type(project_t), intent(in) :: p                !! the project
    integer, intent(in) :: id                       !! the entity
    type(string_t), allocatable :: names(:)
    integer :: k

    associate (e => p%list%box(id)%e)
        allocate (names(0))
        if (allocated(e%more%uses) .and. e%kind /= E_BOUNDPROC) then
            do k = 1, size(e%more%uses)
                call push(names, e%more%uses(k)%module)
            end do
            call add_list('uses', names)
        end if
        if (allocated(e%call_ids)) then
            names = [string_t ::]
            do k = 1, size(e%call_ids)
                call push(names, lowercase(p%list%box(e%call_ids(k))%e%name))
            end do
            if (allocated(e%more%unknown_calls)) then
                do k = 1, size(e%more%unknown_calls)
                    call push(names, e%more%unknown_calls(k)%s)
                end do
            end if
            call add_list('calls', names)
        end if
        if (allocated(e%more%binding_ids)) call add_ids('bindings', e%more%binding_ids, e%more%bindings)
        if (allocated(e%more%modproc_ids)) call add_ids('modprocs', e%more%modproc_ids, e%more%modprocs)
        if (e%kind == E_SUBMODULE) then
            if (e%ancestor_id > 0) call json%add(node, 'ancestor', lowercase(p%list%box(e%ancestor_id)%e%name))
        end if
        if (e%kind == E_TYPE .and. e%extends_id > 0) then
            call json%add(node, 'extends', lowercase(p%list%box(e%extends_id)%e%name))
        end if
    end associate

contains

    !> Add sorted `list` under `key`.
    subroutine add_list(key, list)
        character(len=*), intent(in) :: key                 !! the key
        type(string_t), allocatable, intent(inout) :: list(:)   !! the strings
        type(json_value), pointer :: array
        integer :: j

        call sort_strings(list)
        call json%create_array(array, key)
        call json%add(node, array)
        do j = 1, size(list)
            call json%add(array, '', list(j)%s)
        end do
    end subroutine add_list

    !> Add the names of `ids`, or of `fallback` where an id is 0, under `key`.
    subroutine add_ids(key, ids, fallback)
        character(len=*), intent(in) :: key         !! the key
        integer, intent(in) :: ids(:)               !! the entities
        type(string_t), intent(in) :: fallback(:)   !! the names as written
        type(string_t), allocatable :: list(:)
        integer :: j

        allocate (list(0))
        do j = 1, size(ids)
            if (ids(j) > 0) then
                call push(list, lowercase(p%list%box(ids(j))%e%name))
            else
                call push(list, lowercase(fallback(j)%s))
            end if
        end do
        call add_list(key, list)
    end subroutine add_ids

end subroutine add_links

end module fdoc_links
 
 
